fn strip(v: Value) -> Option<Value> {
    match v {
        Value::Null => None,
        Value::Mapping(m) => {
            let mut out = serde_yaml::Mapping::new();
            for (k, v) in m {
                if let Some(v) = strip(v) { out.insert(k, v); }
