#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Modifier {
    Bold,
    Dim,
    Italic,
    Underlined,
    SlowBlink,
    RapidBlink,
    Reversed,
    Hidden,
    CrossedOut,
}

impl From<Modifier> for ratatui::style::Modifier {
    fn from(m: Modifier) -> Self {
        use ratatui::style::Modifier as R;
        match m {
            Modifier::Bold => R::BOLD,
            Modifier::Dim => R::DIM,
            Modifier::Italic => R::ITALIC,
            Modifier::Underlined => R::UNDERLINED,
            Modifier::SlowBlink => R::SLOW_BLINK,
            Modifier::RapidBlink => R::RAPID_BLINK,
            Modifier::Reversed => R::REVERSED,
            Modifier::Hidden => R::HIDDEN,
            Modifier::CrossedOut => R::CROSSED_OUT,
        }
    }
}

pub const ALL_MODIFIERS: [Modifier; 9] = [
    Modifier::Bold,
    Modifier::Dim,
    Modifier::Italic,
    Modifier::Underlined,
    Modifier::SlowBlink,
    Modifier::RapidBlink,
    Modifier::Reversed,
    Modifier::Hidden,
    Modifier::CrossedOut,
];

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub add_modifiers: Option<IndexSet<Modifier>>,
    pub sub_modifiers: Option<IndexSet<Modifier>>,
}

impl Style {
    /// Overlay `other` on top of `self`, like ratatui's `Style::patch`.
    pub fn extend(mut self, other: &Style) -> Style {
        if other.fg.is_some() {
            self.fg = other.fg;
        }
        if other.bg.is_some() {
            self.bg = other.bg;
        }
        if let Some(add) = &other.add_modifiers {
            let mut a = self.add_modifiers.take().unwrap_or_default();
            let mut s = self.sub_modifiers.take().unwrap_or_default();
            for m in add {
                a.insert(*m);
                s.shift_remove(m);
            }
            self.add_modifiers = Some(a);
            self.sub_modifiers = Some(s);
        }
        if let Some(sub) = &other.sub_modifiers {
            let mut a = self.add_modifiers.take().unwrap_or_default();
            let mut s = self.sub_modifiers.take().unwrap_or_default();
            for m in sub {
                s.insert(*m);
                a.shift_remove(m);
            }
            self.add_modifiers = Some(a);
            self.sub_modifiers = Some(s);
        }
        self
    }
}

impl From<Style> for ratatui::style::Style {
    fn from(s: Style) -> Self {
        let mut r = ratatui::style::Style::default();
        if let Some(fg) = s.fg {
            r = r.fg(fg.into());
        }
        if let Some(bg) = s.bg {
            r = r.bg(bg.into());
        }
        if let Some(add) = s.add_modifiers {
            for m in add {
                r = r.add_modifier(m.into());
            }
        }
        if let Some(sub) = s.sub_modifiers {
            for m in sub {
                r = r.remove_modifier(m.into());
            }
        }
        r
    }
}

impl From<ratatui::style::Style> for Style {
    fn from(s: ratatui::style::Style) -> Self {
        let add: IndexSet<Modifier> = ALL_MODIFIERS
            .iter()
            .copied()
            .filter(|m| s.add_modifier.contains((*m).into()))
            .collect();
        let sub: IndexSet<Modifier> = ALL_MODIFIERS
            .iter()
            .copied()
            .filter(|m| s.sub_modifier.contains((*m).into()))
            .collect();
        Style {
            fg: s.fg.map(Into::into),
            bg: s.bg.map(Into::into),
            add_modifiers: Some(add),
            sub_modifiers: Some(sub),
        }
    }
}

