#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Constraint {
    Percentage(u16),
    Ratio(u32, u32),
    Length(u16),
    LengthLessThanScreenHeight(u16),
    LengthLessThanScreenWidth(u16),
    LengthLessThanLayoutHeight(u16),
    LengthLessThanLayoutWidth(u16),
    Max(u16),
    MaxLessThanScreenHeight(u16),
    MaxLessThanScreenWidth(u16),
    MaxLessThanLayoutHeight(u16),
    MaxLessThanLayoutWidth(u16),
    Min(u16),
    MinLessThanScreenHeight(u16),
    MinLessThanScreenWidth(u16),
    MinLessThanLayoutHeight(u16),
    MinLessThanLayoutWidth(u16),
}

impl Constraint {
    pub fn to_tui(
        self,
        screen: ratatui::layout::Rect,
        layout: ratatui::layout::Rect,
    ) -> ratatui::layout::Constraint {
        use ratatui::layout::Constraint as C;
        match self {
            Self::Percentage(p) => C::Percentage(p),
            Self::Ratio(a, b) => C::Ratio(a, b),
            Self::Length(l) => C::Length(l),
            Self::LengthLessThanScreenHeight(l) => C::Length(screen.height.saturating_sub(l)),
            Self::LengthLessThanScreenWidth(l) => C::Length(screen.width.saturating_sub(l)),
            Self::LengthLessThanLayoutHeight(l) => C::Length(layout.height.saturating_sub(l)),
            Self::LengthLessThanLayoutWidth(l) => C::Length(layout.width.saturating_sub(l)),
            Self::Max(m) => C::Max(m),
            Self::MaxLessThanScreenHeight(m) => C::Max(screen.height.saturating_sub(m)),
            Self::MaxLessThanScreenWidth(m) => C::Max(screen.width.saturating_sub(m)),
            Self::MaxLessThanLayoutHeight(m) => C::Max(layout.height.saturating_sub(m)),
            Self::MaxLessThanLayoutWidth(m) => C::Max(layout.width.saturating_sub(m)),
            Self::Min(m) => C::Min(m),
            Self::MinLessThanScreenHeight(m) => C::Min(screen.height.saturating_sub(m)),
            Self::MinLessThanScreenWidth(m) => C::Min(screen.width.saturating_sub(m)),
            Self::MinLessThanLayoutHeight(m) => C::Min(layout.height.saturating_sub(m)),
            Self::MinLessThanLayoutWidth(m) => C::Min(layout.width.saturating_sub(m)),
        }
    }
}

