#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum Layout {
    Nothing,
    Table,
    InputAndLogs,
    Selection,
    HelpMenu,
    SortAndFilter,
    Static(CustomPanel),
    Dynamic(String),
    Horizontal {
        config: LayoutOptions,
        splits: Vec<Layout>,
    },
    Vertical {
        config: LayoutOptions,
        splits: Vec<Layout>,
    },
    CustomContent {
        title: Option<String>,
        body: ContentBody,
    },
}

impl Default for Layout {
    fn default() -> Self {
        Layout::Nothing
    }
}

impl Layout {
    /// Replace every occurrence of `target` in the tree with `replacement`.
    pub fn replace(self, target: &Layout, replacement: &Layout) -> Layout {
        if &self == target {
            return replacement.clone();
        }
        match self {
            Layout::Horizontal { config, splits } => Layout::Horizontal {
                config,
                splits: splits
                    .into_iter()
                    .map(|s| s.replace(target, replacement))
                    .collect(),
            },
            Layout::Vertical { config, splits } => Layout::Vertical {
                config,
                splits: splits
                    .into_iter()
                    .map(|s| s.replace(target, replacement))
                    .collect(),
            },
            other => other,
        }
    }
}

