#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct Action {
    pub help: Option<String>,
    pub messages: Vec<ExternalMsg>,
}

impl Action {
    pub fn sanitized(self, read_only: bool, recover_mode: bool) -> Option<Action> {
        if self.messages.is_empty() {
            return None;
        }
        let mut messages: Vec<ExternalMsg> = if read_only {
            self.messages
                .into_iter()
                .filter(|m| m.is_read_only())
                .collect()
        } else {
            self.messages
        };
        if recover_mode {
            // In recover mode the dangerous `Pop/Switch` chain after a
            // failure is preserved as-is; nothing to do here.
            let _ = &mut messages;
        }
        if messages.is_empty() {
            None
        } else {
            Some(Action {
                help: self.help,
                messages,
            })
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct KeyBindings {
    pub on_key: BTreeMap<String, Action>,
    pub on_alphabet: Option<Action>,
    pub on_number: Option<Action>,
    pub on_alphanumeric: Option<Action>,
    pub on_special_character: Option<Action>,
    pub on_character: Option<Action>,
    pub on_navigation: Option<Action>,
    pub on_function: Option<Action>,
    pub default: Option<Action>,
}

impl KeyBindings {
    pub fn sanitized(mut self, read_only: bool, recover_mode: bool) -> Self {
        if read_only {
            self.on_key = self
                .on_key
                .into_iter()
                .filter_map(|(k, a)| a.sanitized(read_only, recover_mode).map(|a| (k, a)))
                .collect();
            self.on_alphabet = self
                .on_alphabet
                .and_then(|a| a.sanitized(read_only, recover_mode));
            self.on_number = self
                .on_number
                .and_then(|a| a.sanitized(read_only, recover_mode));
            self.on_alphanumeric = self
                .on_alphanumeric
                .and_then(|a| a.sanitized(read_only, recover_mode));
            self.on_special_character = self
                .on_special_character
                .and_then(|a| a.sanitized(read_only, recover_mode));
            self.on_character = self
                .on_character
                .and_then(|a| a.sanitized(read_only, recover_mode));
            self.on_navigation = self
                .on_navigation
                .and_then(|a| a.sanitized(read_only, recover_mode));
            self.on_function = self
                .on_function
                .and_then(|a| a.sanitized(read_only, recover_mode));
            self.default = self
                .default
                .and_then(|a| a.sanitized(read_only, recover_mode));
        }
        self
    }

    /// Overlay `self` on top of `global`: mode specific bindings win.
    pub fn extend_global(mut self, global: &KeyBindings) -> Self {
        for (k, v) in &global.on_key {
            self.on_key.entry(k.clone()).or_insert_with(|| v.clone());
        }
        self.on_alphabet = self.on_alphabet.or_else(|| global.on_alphabet.clone());
        self.on_number = self.on_number.or_else(|| global.on_number.clone());
        self.on_alphanumeric = self
            .on_alphanumeric
            .or_else(|| global.on_alphanumeric.clone());
        self.on_special_character = self
            .on_special_character
            .or_else(|| global.on_special_character.clone());
        self.on_character = self.on_character.or_else(|| global.on_character.clone());
        self.on_navigation = self
            .on_navigation
            .or_else(|| global.on_navigation.clone());
        self.on_function = self.on_function.or_else(|| global.on_function.clone());
        self.default = self.default.or_else(|| global.default.clone());
        self
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct Mode {
    pub name: String,
    pub help: Option<String>,
    pub extra_help: Option<String>,
    pub key_bindings: KeyBindings,
    pub layout: Option<Layout>,
    pub prompt: Option<String>,
}

impl Mode {
    pub fn sanitized(mut self, read_only: bool, recover_mode: bool, global: &KeyBindings) -> Self {
        self.key_bindings = self
            .key_bindings
            .sanitized(read_only, recover_mode)
            .extend_global(&global.clone().sanitized(read_only, recover_mode));
        self
    }

    /// Build the help menu rows: (key, remaps, help).
    pub fn help_menu(&self, hide_remaps: bool) -> Vec<HelpMenuLine> {
        let kb = &self.key_bindings;
        let mut lines: Vec<HelpMenuLine> = Vec::new();
        if let Some(help) = &self.help {
            // Explicit help overrides the generated table.
            for l in help.lines() {
                lines.push(HelpMenuLine::Paragraph(l.to_string()));
            }
            return lines;
        }
        // Group keys with identical actions.
        let mut groups: Vec<(String, Vec<String>, String)> = Vec::new();
        for (key, action) in &kb.on_key {
            let help = match &action.help {
                Some(h) => h.clone(),
                None => continue,
            };
            if let Some(g) = groups.iter_mut().find(|(_, _, h)| {
                h == &help
                    && kb
                        .on_key
                        .get(&groups_first_key_placeholder())
                        .is_none()
            }) {
                // unreachable placeholder: real grouping handled below
                let _ = g;
            }
            let mut matched = false;
            for g in groups.iter_mut() {
                let first = &g.0;
                let first_action = &kb.on_key[first];
                if first_action.help == action.help && first_action.messages == action.messages {
                    g.1.push(key.clone());
                    matched = true;
                    break;
                }
            }
            if !matched {
                groups.push((key.clone(), vec![], help));
            }
        }
        for (key, remaps, help) in groups {
            lines.push(HelpMenuLine::KeyMap(
                key,
                if hide_remaps { vec![] } else { remaps },
                help,
            ));
        }
        let extras: [(&Option<Action>, &str); 8] = [
            (&kb.on_alphabet, "[a-Z]"),
            (&kb.on_number, "[0-9]"),
            (&kb.on_alphanumeric, "[0-Z]"),
            (&kb.on_special_character, "[^0-Z]"),
            (&kb.on_character, "[*]"),
            (&kb.on_navigation, "[nav]"),
            (&kb.on_function, "[f1-f12]"),
            (&kb.default, "[default]"),
        ];
        for (action, label) in extras {
            if let Some(a) = action {
                if let Some(h) = &a.help {
                    lines.push(HelpMenuLine::KeyMap(label.to_string(), vec![], h.clone()));
                }
            }
        }
        if let Some(extra) = &self.extra_help {
            for l in extra.lines() {
                lines.push(HelpMenuLine::Paragraph(l.to_string()));
            }
        }
        lines
    }
}

fn groups_first_key_placeholder() -> String {
    String::from("\u{0}never-a-key\u{0}")
}

