use serde_yaml::{Mapping, Value};
fn strip(v: Value) -> Option<Value> {
    match v {
        Value::Null => None,
        Value::Mapping(m) => {
            let mut out = Mapping::new();
            for (k, v) in m {
                if let Some(v) = strip(v) { out.insert(k, v); }
            }
            if out.is_empty() { None } else { Some(Value::Mapping(out)) }
        }
        Value::Sequence(s) => Some(Value::Sequence(s.into_iter().map(|x| strip(x).unwrap_or(Value::Null)).collect())),
