pub fn human_size(size: u64) -> String {
    const UNITS: [&str; 7] = ["B", "kB", "MB", "GB", "TB", "PB", "EB"];
    if size < 1000 {
        return format!("{} B", size);
    }
    let mut exp = 0usize;
    let mut div: u64 = 1;
    while exp + 1 < UNITS.len() && size / div >= 1000 {
        div *= 1000;
        exp += 1;
    }
    let value = size as f64 / div as f64;
    if value.fract() == 0.0 {
        format!("{} {}", value as u64, UNITS[exp])
    } else {
        format!("{:.2} {}", value, UNITS[exp])
    }
}

fn mime_essence(path: &Path, is_dir: bool, mode: u32) -> String {
    if is_dir {
        return "inode/directory".to_string();
    }
    let ext = path
        .extension()
        .map(|e| e.to_string_lossy().to_string())
        .unwrap_or_default();
    if let Some(m) = mime::from_extension(&ext) {
        return m.to_string();
    }
    if mode & 0o111 != 0 {
        return "application/x-executable".to_string();
    }
    String::new()
}

fn nanos(t: std::io::Result<std::time::SystemTime>) -> Option<u128> {
    t.ok()
        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
        .map(|d| d.as_nanos())
}

