/// Node together with the directory context, used for sorting and
/// filtering as well as for rendering.
pub fn cmp_natural(a: &str, b: &str) -> std::cmp::Ordering {
    natural_cmp(a, b)
}

/// Natural ("human") ordering: digit runs compare numerically.
pub fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    let (mut i, mut j) = (0, 0);
    while i < ac.len() && j < bc.len() {
        let ca = ac[i];
        let cb = bc[j];
        if ca.is_ascii_digit() && cb.is_ascii_digit() {
            let si = i;
            while i < ac.len() && ac[i].is_ascii_digit() {
                i += 1;
            }
            let sj = j;
            while j < bc.len() && bc[j].is_ascii_digit() {
                j += 1;
            }
            let na: String = ac[si..i].iter().collect();
            let nb: String = bc[sj..j].iter().collect();
            let na_t = na.trim_start_matches('0');
            let nb_t = nb.trim_start_matches('0');
            match na_t.len().cmp(&nb_t.len()).then_with(|| na_t.cmp(nb_t)) {
                Ordering::Equal => {
                    // fewer leading zeros sorts first
                    match na.len().cmp(&nb.len()) {
                        Ordering::Equal => {}
                        o => return o,
                    }
                }
                o => return o,
            }
        } else {
            match ca.cmp(&cb) {
                Ordering::Equal => {
                    i += 1;
                    j += 1;
                }
                o => return o,
            }
        }
    }
    (ac.len() - i).cmp(&(bc.len() - j))
}

pub fn read_dir_names(path: &Path) -> std::io::Result<Vec<String>> {
    let mut names = Vec::new();
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        names.push(entry.file_name().to_string_lossy().to_string());
    }
    Ok(names)
}
