            .as_ref()
            .map(|c| &c.mime_essence)
            .cmp(&b.symlink.as_ref().map(|c| &c.mime_essence)),
        BySymlinkSize => a
            .symlink
            .as_ref()
            .map(|c| c.size)
            .cmp(&b.symlink.as_ref().map(|c| c.size)),
        BySymlinkCreated => a
            .symlink
            .as_ref()
            .map(|c| c.created)
            .cmp(&b.symlink.as_ref().map(|c| c.created)),
        BySymlinkLastModified => a
            .symlink
            .as_ref()
            .map(|c| c.last_modified)
            .cmp(&b.symlink.as_ref().map(|c| c.last_modified)),
    };
    if s.reverse {
        ord.reverse()
    } else {
        ord
    }
}

/// Result of matching a single node against the searcher.
struct Ranked {
    rank: Vec<i64>,
    node: Node,
}

fn build_rank(
    criteria: &[RankCriteria],
    score: i64,
    begin: i64,
    end: i64,
    length: i64,
    index: i64,
) -> Vec<i64> {
    criteria
        .iter()
        .map(|c| match c {
            RankCriteria::Score => -score,
            RankCriteria::NegScore => score,
            RankCriteria::Begin => begin,
            RankCriteria::NegBegin => -begin,
            RankCriteria::End => end,
            RankCriteria::NegEnd => -end,
            RankCriteria::Length => length,
            RankCriteria::NegLength => -length,
            RankCriteria::Index => index,
            RankCriteria::NegIndex => -index,
        })
        .collect()
}

pub const DEFAULT_RANK_CRITERIA: [RankCriteria; 3] =
    [RankCriteria::Score, RankCriteria::Begin, RankCriteria::End];

impl NodeSearcherApplicable {
    pub fn search(&self, nodes: Vec<Node>) -> Vec<Node> {
        let criteria: Vec<RankCriteria> = self
            .rank_criteria
            .clone()
            .unwrap_or_else(|| DEFAULT_RANK_CRITERIA.to_vec());
        let mut ranked: Vec<Ranked> = Vec::new();
        match self.algorithm {
            SearchAlgorithm::Fuzzy => {
                let matcher = fuzzy::Matcher::new(self.exact_mode);
                for (index, node) in nodes.into_iter().enumerate() {
                    if let Some(m) = matcher.match_str(&node.relative_path, &self.pattern) {
                        let length = node.relative_path.chars().count() as i64;
                        let rank = build_rank(
                            &criteria,
                            m.score,
                            m.begin as i64,
                            m.end as i64,
                            length,
                            index as i64,
                        );
                        ranked.push(Ranked { rank, node });
                    }
                }
            }
            SearchAlgorithm::Regex => {
                let re = match regex::Regex::new(&self.pattern) {
                    Ok(r) => r,
                    Err(_) => return Vec::new(),
                };
                for (index, node) in nodes.into_iter().enumerate() {
                    if let Some(m) = re.find(&node.relative_path) {
                        let begin = node.relative_path[..m.start()].chars().count() as i64;
                        let end = node.relative_path[..m.end()].chars().count() as i64;
                        let length = node.relative_path.chars().count() as i64;
                        let score = -(end - begin);
                        let rank = build_rank(&criteria, score, begin, end, length, index as i64);
                        ranked.push(Ranked { rank, node });
                    }
                }
            }
        }
        if !self.unordered {
            ranked.sort_by(|a, b| a.rank.cmp(&b.rank));
        }
        ranked.into_iter().map(|r| r.node).collect()
    }
}

pub fn explore(path: &Path, config: &ExplorerConfig) -> std::io::Result<Vec<Node>> {
    let parent = path.to_string_lossy().to_string();
    let mut nodes: Vec<Node> = std::fs::read_dir(path)?
        .filter_map(|e| e.ok())
        .map(|e| Node::new(parent.clone(), e.file_name().to_string_lossy().to_string()))
        .filter(|n| config.filter(n))
        .collect();

    match &config.searcher {
        Some(searcher) => {
            nodes = searcher.search(nodes);
            if searcher.unordered {
                nodes.sort_by(|a, b| config.sort(a, b));
            }
        }
        None => {
            nodes.sort_by(|a, b| config.sort(a, b));
        }
    }
    Ok(nodes)
}
