//! A fuzzy matcher in the spirit of skim's V2 algorithm: subsequence
//! matching with bonuses for adjacency, word boundaries and case matches.

const BONUS_MATCHED: i64 = 4;
const BONUS_CASE_MATCH: i64 = 4;
const BONUS_UPPER_MATCH: i64 = 6;
const BONUS_ADJACENCY: i64 = 10;
const BONUS_SEPARATOR: i64 = 8;
const BONUS_CAMEL: i64 = 8;
const PENALTY_CASE_UNMATCHED: i64 = -1;
const PENALTY_LEADING: i64 = -6;
const PENALTY_MAX_LEADING: i64 = -18;
const PENALTY_UNMATCHED: i64 = -2;

#[derive(Debug, Clone)]
pub struct MatchResult {
    pub score: i64,
    pub begin: usize,
    pub end: usize,
    pub indices: Vec<usize>,
}

pub struct Matcher {
    exact: bool,
}

fn is_separator(c: char) -> bool {
    matches!(c, ' ' | '_' | '-' | '/' | '\\' | '.' | ',' | ':' | ';' | '\'' | '"' | '(' | ')' | '[' | ']' | '{' | '}' | '<' | '>')
}

fn char_eq(a: char, b: char, case_sensitive: bool) -> bool {
    if case_sensitive {
        a == b
    } else {
        a == b || a.to_lowercase().eq(b.to_lowercase())
    }
}

impl Matcher {
    pub fn new(exact: bool) -> Self {
        Matcher { exact }
    }

    pub fn match_str(&self, choice: &str, pattern: &str) -> Option<MatchResult> {
        if self.exact {
            return self.exact_match(choice, pattern);
        }
        self.fuzzy_match(choice, pattern)
    }

    fn exact_match(&self, choice: &str, pattern: &str) -> Option<MatchResult> {
        if pattern.is_empty() {
            return Some(MatchResult {
                score: 0,
                begin: 0,
                end: 0,
                indices: vec![],
            });
        }
        let case_sensitive = pattern.chars().any(|c| c.is_uppercase());
        let (c, p) = if case_sensitive {
            (choice.to_string(), pattern.to_string())
        } else {
            (choice.to_lowercase(), pattern.to_lowercase())
        };
        let byte_pos = c.find(&p)?;
        let begin = c[..byte_pos].chars().count();
        let plen = p.chars().count();
        let end = begin + plen;
        let indices: Vec<usize> = (begin..end).collect();
        // Exact matches get a bonus-less flat score so that shorter
        // choices / earlier matches rank first.
        let score = (plen as i64) * BONUS_MATCHED + (plen as i64 - 1).max(0) * BONUS_ADJACENCY;
        Some(MatchResult {
            score,
            begin,
            end,
            indices,
        })
    }

    fn fuzzy_match(&self, choice: &str, pattern: &str) -> Option<MatchResult> {
        if pattern.is_empty() {
            return Some(MatchResult {
                score: 0,
                begin: 0,
                end: 0,
                indices: vec![],
            });
        }
        let case_sensitive = pattern.chars().any(|c| c.is_uppercase());
        let choice: Vec<char> = choice.chars().collect();
        let pattern: Vec<char> = pattern.chars().collect();
        let n = choice.len();
        let m = pattern.len();
        if m > n {
            return None;
        }

        // Quick subsequence check.
        {
            let mut pi = 0;
            for &c in &choice {
                if pi < m && char_eq(c, pattern[pi], case_sensitive) {
                    pi += 1;
                }
            }
            if pi < m {
                return None;
            }
        }

        // Position bonuses depending on the previous character.
        let mut bonus = vec![0i64; n];
        for j in 0..n {
            let prev = if j == 0 { None } else { Some(choice[j - 1]) };
            let cur = choice[j];
            bonus[j] = match prev {
                None => BONUS_SEPARATOR,
                Some(p) if is_separator(p) => BONUS_SEPARATOR,
                Some(p) if p.is_lowercase() && cur.is_uppercase() => BONUS_CAMEL,
                Some(p) if !p.is_alphanumeric() && cur.is_alphanumeric() => BONUS_SEPARATOR,
                _ => 0,
            };
        }

        const NEG: i64 = i64::MIN / 4;
        // dp_m[i][j]: best score where pattern[i] is matched at choice[j].
        let mut dp: Vec<Vec<i64>> = vec![vec![NEG; n]; m];
        let mut from: Vec<Vec<Option<usize>>> = vec![vec![None; n]; m];
        for i in 0..m {
            for j in i..n {
                if !char_eq(choice[j], pattern[i], case_sensitive) {
                    continue;
                }
                let mut sc = BONUS_MATCHED + bonus[j];
                if choice[j] == pattern[i] {
                    if choice[j].is_uppercase() {
                        sc += BONUS_UPPER_MATCH;
                    } else {
                        sc += BONUS_CASE_MATCH;
                    }
                } else {
                    sc += PENALTY_CASE_UNMATCHED;
                }
                if i == 0 {
                    let leading = (j as i64) * PENALTY_LEADING;
                    sc += leading.max(PENALTY_MAX_LEADING);
                    dp[i][j] = sc;
                } else {
                    let mut best = NEG;
                    let mut best_k = None;
                    for k in (i - 1)..j {
                        if dp[i - 1][k] == NEG {
                            continue;
                        }
                        let gap = (j - k - 1) as i64;
                        let cand = dp[i - 1][k]
                            + if gap == 0 {
                                BONUS_ADJACENCY
                            } else {
                                gap * PENALTY_UNMATCHED
                            };
                        if cand > best {
                            best = cand;
                            best_k = Some(k);
                        }
                    }
                    if best == NEG {
                        continue;
                    }
                    dp[i][j] = best + sc;
                    from[i][j] = best_k;
                }
            }
        }
        let (mut best_j, mut best) = (None, NEG);
        for j in 0..n {
            if dp[m - 1][j] > best {
                best = dp[m - 1][j];
                best_j = Some(j);
            }
        }
        let mut j = best_j?;
        let mut indices = vec![0usize; m];
        for i in (0..m).rev() {
            indices[i] = j;
            if i > 0 {
                j = from[i][j]?;
            }
        }
        // Trailing unmatched characters are penalised lightly.
        let trailing = (n - 1 - indices[m - 1]) as i64;
        let score = best + trailing * PENALTY_UNMATCHED;
        Some(MatchResult {
            score,
            begin: indices[0],
            end: indices[m - 1] + 1,
            indices,
        })
    }
}
