//! Cursor based input buffer.

use crate::msg::InputOperation;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct InputBuffer {
    chars: Vec<char>,
    cursor: usize,
}

impl InputBuffer {
    pub fn new(value: &str) -> Self {
        let chars: Vec<char> = value.chars().collect();
        let cursor = chars.len();
        InputBuffer { chars, cursor }
    }

    pub fn value(&self) -> String {
        self.chars.iter().collect()
    }

    pub fn cursor(&self) -> usize {
        self.cursor
    }

    pub fn len(&self) -> usize {
        self.chars.len()
    }

    pub fn is_empty(&self) -> bool {
        self.chars.is_empty()
    }

    pub fn set_value(&mut self, value: &str) {
        self.chars = value.chars().collect();
        self.cursor = self.chars.len();
    }

    pub fn push_str(&mut self, s: &str) {
        for c in s.chars() {
            self.insert(c);
        }
    }

    fn insert(&mut self, c: char) {
        self.chars.insert(self.cursor, c);
        self.cursor += 1;
    }

    pub fn remove_last_char(&mut self) {
        if !self.chars.is_empty() {
            self.chars.pop();
            self.cursor = self.cursor.min(self.chars.len());
        }
    }

    pub fn remove_last_word(&mut self) {
        // Drop trailing spaces then the trailing word.
        while matches!(self.chars.last(), Some(' ')) {
            self.chars.pop();
        }
        while matches!(self.chars.last(), Some(c) if *c != ' ') {
            self.chars.pop();
        }
        self.cursor = self.cursor.min(self.chars.len());
    }

    fn prev_word_boundary(&self) -> usize {
        let mut i = self.cursor;
        while i > 0 && !self.chars[i - 1].is_alphanumeric() {
            i -= 1;
        }
        while i > 0 && self.chars[i - 1].is_alphanumeric() {
            i -= 1;
        }
        i
    }

    fn next_word_boundary(&self) -> usize {
        let mut i = self.cursor;
        let n = self.chars.len();
        while i < n && self.chars[i].is_alphanumeric() {
            i += 1;
        }
        while i < n && !self.chars[i].is_alphanumeric() {
            i += 1;
        }
        i
    }

    pub fn handle(&mut self, op: &InputOperation) {
        use InputOperation::*;
        match op {
            SetCursor(n) => self.cursor = (*n).min(self.chars.len()),
            InsertCharacter(c) => self.insert(*c),
            GoToPreviousCharacter => self.cursor = self.cursor.saturating_sub(1),
            GoToNextCharacter => self.cursor = (self.cursor + 1).min(self.chars.len()),
            GoToPreviousWord => self.cursor = self.prev_word_boundary(),
            GoToNextWord => self.cursor = self.next_word_boundary(),
            GoToStart => self.cursor = 0,
            GoToEnd => self.cursor = self.chars.len(),
            DeletePreviousCharacter => {
                if self.cursor > 0 {
                    self.chars.remove(self.cursor - 1);
                    self.cursor -= 1;
                }
            }
            DeleteNextCharacter => {
                if self.cursor < self.chars.len() {
                    self.chars.remove(self.cursor);
                }
            }
            DeletePreviousWord => {
                let b = self.prev_word_boundary();
                self.chars.drain(b..self.cursor);
                self.cursor = b;
            }
            DeleteNextWord => {
                let b = self.next_word_boundary();
                self.chars.drain(self.cursor..b);
            }
            DeleteLine => {
                self.chars.clear();
                self.cursor = 0;
            }
            DeleteTillEnd => {
                self.chars.truncate(self.cursor);
            }
        }
    }
}
