//! Keyboard input normalisation: crossterm events become key names such
//! as `ctrl-a`, `f1`, `space`, `back-tab` and get categorised.

use crate::msg::InputOperation;
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Key {
    /// Canonical name as used in the key bindings configuration.
    pub name: String,
    pub code: KeyCode,
    pub modifiers: KeyModifiers,
    pub supported: bool,
