    ("right", KeyCode::Right),
    ("up", KeyCode::Up),
    ("down", KeyCode::Down),
    ("home", KeyCode::Home),
    ("end", KeyCode::End),
    ("page-up", KeyCode::PageUp),
    ("page-down", KeyCode::PageDown),
    ("back-tab", KeyCode::BackTab),
    ("delete", KeyCode::Delete),
    ("insert", KeyCode::Insert),
    ("enter", KeyCode::Enter),
    ("tab", KeyCode::Tab),
    ("esc", KeyCode::Esc),
];

impl Key {
    pub fn from_event(ev: &KeyEvent) -> Key {
        let ctrl = ev.modifiers.contains(KeyModifiers::CONTROL);
        let alt = ev.modifiers.contains(KeyModifiers::ALT);
        let mut supported = true;
        let name = match ev.code {
            KeyCode::Char(c) => {
                if c == ' ' {
                    if ctrl {
                        "ctrl-space".to_string()
                    } else {
                        "space".to_string()
                    }
                } else if c.is_ascii_digit() {
                    if alt {
                        supported = false;
                        String::new()
                    } else {
                        c.to_string()
                    }
                } else if c.is_ascii_alphabetic() {
                    if ctrl {
                        format!("ctrl-{}", c.to_ascii_lowercase())
                    } else if alt && c.is_ascii_lowercase() {
                        format!("alt-{}", c)
                    } else {
                        c.to_string()
                    }
                } else if ctrl {
                    format!("ctrl-{}", c)
                } else {
                    c.to_string()
                }
            }
            KeyCode::F(n) => {
                if (ctrl || alt) || !(1..=12).contains(&n) {
                    supported = false;
                    String::new()
                } else {
                    format!("f{}", n)
                }
            }
            KeyCode::Null => {
                supported = false;
                String::new()
            }
            code => {
                let base = NAV_NAMES
                    .iter()
                    .find(|(_, c)| *c == code)
                    .map(|(n, _)| *n);
                match base {
                    Some(base) => {
                        if alt {
                            supported = false;
                            String::new()
                        } else if ctrl {
                            if matches!(code, KeyCode::Enter | KeyCode::Tab | KeyCode::Esc) {
                                supported = false;
                                String::new()
                            } else {
                                format!("ctrl-{}", base)
                            }
                        } else {
                            base.to_string()
                        }
                    }
                    None => {
                        supported = false;
                        String::new()
                    }
                }
            }
        };
        Key {
            name,
            code: ev.code,
            modifiers: ev.modifiers,
            supported,
        }
    }

    /// The plain character represented by this key, if any.
    pub fn to_char(&self) -> Option<char> {
        if !self.supported {
            return None;
        }
        match self.code {
            KeyCode::Char(c) => {
                if self.modifiers.contains(KeyModifiers::CONTROL) {
                    if c.is_ascii_digit() {
                        Some(c)
                    } else {
                        None
                    }
                } else if self.modifiers.contains(KeyModifiers::ALT) && c.is_ascii_lowercase() {
                    None
                } else {
                    Some(c)
                }
            }
            _ => None,
        }
    }

    pub fn is_alphabet(&self) -> bool {
        self.name.len() == 1 && self.name.chars().all(|c| c.is_ascii_alphabetic())
    }

    pub fn is_number(&self) -> bool {
        self.name.len() == 1 && self.name.chars().all(|c| c.is_ascii_digit())
    }

    pub fn is_alphanumeric(&self) -> bool {
        self.is_alphabet() || self.is_number()
    }

    pub fn is_special_character(&self) -> bool {
        self.supported
            && self.name.chars().count() == 1
            && !self.is_alphanumeric()
            && self.name != " "
    }

    pub fn is_character(&self) -> bool {
        self.is_alphanumeric() || self.is_special_character()
    }

    pub fn is_function(&self) -> bool {
        self.supported && matches!(self.code, KeyCode::F(_)) && self.name.starts_with('f')
    }

    pub fn is_navigation(&self) -> bool {
        self.supported
            && !self.is_character()
            && !self.is_function()
            && !matches!(self.name.as_str(), "space" | "tab" | "enter")
    }

    /// Map the key to an input buffer operation (readline style).
    pub fn to_input_operation(&self) -> Option<InputOperation> {
        use InputOperation::*;
        if !self.supported {
            return None;
        }
        let ctrl = self.modifiers.contains(KeyModifiers::CONTROL);
        let alt = self.modifiers.contains(KeyModifiers::ALT);
        match self.code {
            KeyCode::Char(c) if ctrl && !c.is_ascii_digit() => match c.to_ascii_lowercase() {
                'a' => Some(GoToStart),
                'e' => Some(GoToEnd),
                'b' => Some(GoToPreviousCharacter),
                'f' => Some(GoToNextCharacter),
                'w' => Some(DeletePreviousWord),
                'u' => Some(DeleteLine),
                'k' => Some(DeleteTillEnd),
                _ => None,
            },
            KeyCode::Char(c) if alt && c.is_ascii_lowercase() => None,
            KeyCode::Char(c) => Some(InsertCharacter(c)),
            KeyCode::Backspace if ctrl => Some(DeletePreviousWord),
            KeyCode::Backspace => Some(DeletePreviousCharacter),
            KeyCode::Delete if ctrl => Some(DeleteNextWord),
            KeyCode::Delete => Some(DeleteNextCharacter),
            KeyCode::Left if ctrl => Some(GoToPreviousWord),
            KeyCode::Left => Some(GoToPreviousCharacter),
            KeyCode::Right if ctrl => Some(GoToNextWord),
            KeyCode::Right => Some(GoToNextCharacter),
            KeyCode::Home => Some(GoToStart),
            KeyCode::End => Some(GoToEnd),
            _ => None,
        }
    }
}
