//! Path helpers: lexical absolutisation, relative paths and shortening.

use std::path::{Component, Path, PathBuf};

/// Make `path` absolute relative to `base`, resolving `.` and `..`
/// lexically (without touching the file system).
pub fn absolutize_with(path: &Path, base: &Path) -> PathBuf {
    let joined = if path.is_absolute() {
        path.to_path_buf()
    } else {
        base.join(path)
    };
    let mut out = PathBuf::new();
    for comp in joined.components() {
        match comp {
            Component::RootDir => out.push("/"),
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
                if out.as_os_str().is_empty() {
                    out.push("/");
                }
            }
            Component::Normal(c) => out.push(c),
            Component::Prefix(_) => {}
        }
    }
    if out.as_os_str().is_empty() {
        out.push("/");
    }
    out
}

pub fn absolutize(path: &Path) -> std::io::Result<PathBuf> {
    let cwd = std::env::current_dir()?;
    Ok(absolutize_with(path, &cwd))
}

pub fn pwd() -> std::io::Result<PathBuf> {
    match std::env::var("PWD") {
        Ok(p) if !p.is_empty() && Path::new(&p).is_absolute() => {
            let p = PathBuf::from(p);
            match (p.canonicalize(), std::env::current_dir()?.canonicalize()) {
                (Ok(a), Ok(b)) if a == b => Ok(p),
                _ => std::env::current_dir(),
            }
        }
        _ => std::env::current_dir(),
    }
}

/// Compute `path` relative to `base` (both absolute, normalised), like
/// Python's `os.path.relpath`.
pub fn diff_paths(path: &Path, base: &Path) -> Option<PathBuf> {
    if path.is_absolute() != base.is_absolute() {
        return None;
    }
    let mut ita = path.components();
    let mut itb = base.components();
    let mut comps: Vec<Component> = vec![];
    loop {
        match (ita.next(), itb.next()) {
            (None, None) => break,
            (Some(a), None) => {
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
            (None, _) => comps.push(Component::ParentDir),
            (Some(a), Some(b)) if comps.is_empty() && a == b => (),
            (Some(a), Some(Component::CurDir)) => comps.push(a),
            (Some(_), Some(Component::ParentDir)) => return None,
            (Some(a), Some(_)) => {
                comps.push(Component::ParentDir);
                for _ in itb {
                    comps.push(Component::ParentDir);
                }
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
        }
    }
    Some(comps.iter().map(|c| c.as_os_str()).collect())
}

#[derive(Debug, Clone, Default)]
pub struct RelativityConfig {
    pub base: Option<String>,
    pub with_prefix_dots: bool,
    pub without_suffix_dots: bool,
}

pub fn relative_to(path: &str, config: &RelativityConfig) -> std::io::Result<String> {
    let path = absolutize(Path::new(path))?;
    let base = match &config.base {
        Some(b) => absolutize(Path::new(b))?,
        None => pwd()?,
    };
    let diff = diff_paths(&path, &base).ok_or_else(|| {
        std::io::Error::new(
            std::io::ErrorKind::Other,
            format!("could not determine relative path for {:?}", path),
        )
    })?;
    let mut rel = if diff.as_os_str().is_empty() {
        ".".to_string()
    } else {
        diff.to_string_lossy().to_string()
    };

    if config.without_suffix_dots && (rel == "." || rel == ".." || rel.ends_with("/..")) {
        if let (Some(parent), Some(name)) = (path.parent(), path.file_name()) {
            let pdiff = diff_paths(parent, &base).unwrap_or_default();
            let pdiff = if pdiff.as_os_str().is_empty() {
                "..".to_string()
            } else {
                let s = pdiff.to_string_lossy().to_string();
                if s == "." {
                    "..".to_string()
                } else {
                    format!("../{}", s)
                }
            };
            rel = format!("{}/{}", pdiff, name.to_string_lossy());
        }
    }

    if config.with_prefix_dots {
        let first = rel.split('/').next().unwrap_or("");
        if first != "." && first != ".." {
            rel = format!("./{}", rel);
        }
    }
    Ok(rel)
}

pub fn shorten(path: &str, config: &RelativityConfig) -> std::io::Result<String> {
    let abs = absolutize(Path::new(path))?;
    let abs_str = abs.to_string_lossy().to_string();
    let mut candidates: Vec<String> = Vec::new();
    if let Ok(rel) = relative_to(path, config) {
        candidates.push(rel);
    }
    if let Ok(home) = std::env::var("HOME") {
        if !home.is_empty() {
            let home = absolutize(Path::new(&home))?;
            if let Ok(stripped) = abs.strip_prefix(&home) {
                let s = stripped.to_string_lossy();
                if s.is_empty() {
                    candidates.push("~".to_string());
                } else {
                    candidates.push(format!("~/{}", s));
                }
            }
        }
    }
    candidates.push(abs_str);
    let mut best = candidates[0].clone();
    for c in candidates.into_iter().skip(1) {
        if c.chars().count() < best.chars().count() {
            best = c;
        }
    }
    Ok(best)
}

