#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum LogLevel {
    Info,
    Success,
    Warning,
    Error,
}

impl std::fmt::Display for LogLevel {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            LogLevel::Info => write!(f, "INFO"),
            LogLevel::Success => write!(f, "SUCCESS"),
            LogLevel::Warning => write!(f, "WARNING"),
            LogLevel::Error => write!(f, "ERROR"),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Log {
    #[serde(serialize_with = "serialize_level")]
    pub level: LogLevel,
    pub message: String,
    pub created_at: OffsetDateTime,
}

fn serialize_level<S: serde::Serializer>(level: &LogLevel, s: S) -> Result<S::Ok, S::Error> {
    s.serialize_str(&level.to_string())
}

impl Log {
    pub fn new(level: LogLevel, message: String) -> Self {
        Log {
            level,
            message,
            created_at: OffsetDateTime::now_utc(),
        }
    }
}

impl std::fmt::Display for Log {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "[{}] {:<7} {}",
            crate::ui::format_datetime_full(&self.created_at),
            self.level.to_string(),
            self.message
        )
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct History {
    pub loc: usize,
    pub paths: Vec<String>,
}

impl History {
    pub fn push(&mut self, path: String) {
        if self.peek() != Some(&path) {
            self.paths = self.paths[..self.paths.len().min(self.loc + 1)].to_vec();
            self.paths.push(path);
            self.loc = self.paths.len().saturating_sub(1);
        }
    }

    pub fn visit_last(&mut self) -> Option<&String> {
        self.loc = self.loc.saturating_sub(1);
        self.paths.get(self.loc)
    }

    pub fn visit_next(&mut self) -> Option<&String> {
        self.loc = (self.loc + 1).min(self.paths.len().saturating_sub(1));
        self.paths.get(self.loc)
    }

    pub fn peek(&self) -> Option<&String> {
        self.paths.get(self.loc)
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Pipe {
