        let path = PathBuf::from(session_path).join("pipe");
        let p = |n: &str| path.join(n).to_string_lossy().to_string();
        Pipe {
            msg_in: p("msg_in"),
            selection_out: p("selection_out"),
            result_out: p("result_out"),
            directory_nodes_out: p("directory_nodes_out"),
            global_help_menu_out: p("global_help_menu_out"),
            logs_out: p("logs_out"),
            history_out: p("history_out"),
            path: path.to_string_lossy().to_string(),
        }
    }
}

