#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct App {
    pub bin: String,
    pub version: String,
    pub config: Config,
    pub hooks: Hooks,
    pub vroot: Option<String>,
    pub initial_vroot: Option<String>,
    pub pwd: String,
    pub initial_pwd: String,
    pub directory_buffer: Option<DirectoryBuffer>,
    pub last_focus: HashMap<String, Option<String>>,
    pub selection: IndexSet<Node>,
    pub msg_out: VecDeque<MsgOut>,
    pub mode: Mode,
    pub layout: Layout,
    pub input: InputState,
    pub pid: u32,
    pub session_path: String,
    pub pipe: Pipe,
    pub explorer_config: ExplorerConfig,
    pub logs: Vec<Log>,
    pub logs_hidden: bool,
    pub history: History,
    pub last_modes: Vec<Mode>,
    pub hostname: String,
    #[serde(skip)]
    pub scroll_top: usize,
    #[serde(skip)]
    pub read_only: bool,
    #[serde(skip)]
    pub print_pwd_as_result: bool,
}

fn hostname() -> String {
    let mut buf = [0u8; 256];
    let rc = unsafe { libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
    if rc != 0 {
        return String::new();
    }
    let end = buf.iter().position(|b| *b == 0).unwrap_or(buf.len());
    String::from_utf8_lossy(&buf[..end]).to_string()
}

pub fn runtime_dir() -> PathBuf {
    std::env::var("XDG_RUNTIME_DIR")
        .ok()
        .filter(|p| !p.is_empty() && Path::new(p).is_dir())
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
}

impl App {
    pub fn create(
        bin: String,
        pwd: PathBuf,
        config: Config,
        hooks: Hooks,
        vroot: Option<PathBuf>,
    ) -> Result<Self> {
        let pid = std::process::id();
        let session_path = runtime_dir()
            .join("xplr")
            .join("session")
            .join(pid.to_string())
            .to_string_lossy()
            .to_string();
        let pipe = Pipe::from_session_path(&session_path);

        let mode_name = config
            .general
            .initial_mode
            .clone()
            .unwrap_or_else(|| "default".to_string());
        let mode = config
            .modes
            .get(&mode_name)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("mode not found: {}", mode_name))?;
        let layout_name = config
            .general
            .initial_layout
            .clone()
            .unwrap_or_else(|| "default".to_string());
        let layout = config
            .layouts
            .get(&layout_name)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("layout not found: {}", layout_name))?;

        let mut explorer_config = ExplorerConfig::default();
        if !config.general.show_hidden {
            explorer_config.filters.insert(NodeFilterApplicable {
                filter: NodeFilter::RelativePathDoesNotStartWith,
                input: ".".to_string(),
            });
        }
        if let Some(sorters) = &config.general.initial_sorting {
            explorer_config.sorters = sorters.clone();
        }

        let pwd_str = pwd.to_string_lossy().to_string();
        let vroot = vroot.map(|v| v.to_string_lossy().to_string());
        let read_only = config.general.read_only;
        let input = InputState {
            buffer: None,
            prompt: config.general.prompt.format.clone().unwrap_or_default(),
        };

        let mut app = App {
            bin,
            version: VERSION.to_string(),
            config,
            hooks,
            vroot: vroot.clone(),
            initial_vroot: vroot,
            pwd: pwd_str.clone(),
            initial_pwd: pwd_str,
            directory_buffer: None,
            last_focus: HashMap::new(),
            selection: IndexSet::new(),
            msg_out: VecDeque::new(),
            mode,
            layout,
            input,
            pid,
            session_path,
            pipe,
            explorer_config,
            logs: Vec::new(),
            logs_hidden: false,
            history: History::default(),
            last_modes: Vec::new(),
            hostname: hostname(),
            scroll_top: 0,
            read_only,
            print_pwd_as_result: false,
        };
        app.mode = app.sanitize_mode(app.mode.clone());
        Ok(app)
    }

    fn sanitize_mode(&self, mode: Mode) -> Mode {
        mode.sanitized(
            self.read_only,
            self.config.general.enable_recover_mode,
            &self.config.general.global_key_bindings,
        )
    }

    // ------------------------------------------------------------ helpers

    pub fn focused_node(&self) -> Option<&Node> {
        self.directory_buffer
            .as_ref()
            .and_then(|d| d.focused_node())
    }

    pub fn focused_node_str(&self) -> String {
        self.focused_node()
            .map(|n| n.absolute_path.clone())
            .unwrap_or_default()
    }

    pub fn log(&mut self, level: LogLevel, message: String) {
        self.logs_hidden = false;
        self.logs.push(Log::new(level, message));
    }

    pub fn log_info(&mut self, m: String) {
        self.log(LogLevel::Info, m)
    }
    pub fn log_success(&mut self, m: String) {
        self.log(LogLevel::Success, m)
    }
    pub fn log_warning(&mut self, m: String) {
        self.log(LogLevel::Warning, m)
    }
    pub fn log_error(&mut self, m: String) {
        self.log(LogLevel::Error, m)
    }

    pub fn enqueue(&mut self, task: Task) {
        self.msg_out.push_back(MsgOut::Enqueue(task));
    }

    pub fn absolutize(&self, path: &str) -> PathBuf {
        path_util::absolutize_with(Path::new(path), Path::new(&self.pwd))
    }

    fn check_vroot(&self, path: &Path) -> Result<()> {
        if let Some(vroot) = &self.vroot {
            let vroot_path = Path::new(vroot);
            if !path.starts_with(vroot_path) {
                bail!(
                    "{:?} is outside of virtual root {:?}",
                    path.to_string_lossy(),
                    vroot
                );
            }
        }
        Ok(())
    }

    // ------------------------------------------------------------ tasks

    pub fn handle_task(&mut self, task: Task) -> Result<()> {
        let before_pwd = self.pwd.clone();
        let before_focus = self.focused_node_str();
        let before_mode = self.mode.name.clone();
        let before_layout = self.layout.clone();
        let before_selection: Vec<String> = self
            .selection
            .iter()
            .map(|n| n.absolute_path.clone())
            .collect();

        let res = match task.msg {
            MsgIn::Internal(msg) => self.handle_internal(msg),
            MsgIn::External(msg) => self.handle_external(msg, task.key.as_ref()),
        };
        if let Err(e) = res {
            self.log_error(e.to_string());
        }

        // Hooks
        if self.pwd != before_pwd {
            let msgs = self.hooks.on_directory_change.clone();
            self.enqueue_all(msgs);
        }
        if self.focused_node_str() != before_focus {
            let msgs = self.hooks.on_focus_change.clone();
            self.enqueue_all(msgs);
        }
        if self.mode.name != before_mode {
            let msgs = self.hooks.on_mode_switch.clone();
            self.enqueue_all(msgs);
        }
        if self.layout != before_layout {
            let msgs = self.hooks.on_layout_switch.clone();
            self.enqueue_all(msgs);
        }
        let after_selection: Vec<String> = self
            .selection
            .iter()
            .map(|n| n.absolute_path.clone())
            .collect();
        if after_selection != before_selection {
            let msgs = self.hooks.on_selection_change.clone();
            self.enqueue_all(msgs);
        }
        Ok(())
    }

    fn enqueue_all(&mut self, msgs: Vec<ExternalMsg>) {
        for m in msgs {
            self.enqueue(Task::new(MsgIn::External(m), None));
        }
    }

    fn handle_internal(&mut self, msg: InternalMsg) -> Result<()> {
        match msg {
            InternalMsg::AddLastFocus(parent, focus) => {
                self.last_focus.insert(parent, focus);
            }
            InternalMsg::SetDirectory(dir) => self.set_directory(dir),
            InternalMsg::HandleKey(key) => self.handle_key(key)?,
            InternalMsg::RefreshSelection => self.refresh_selection(),
        }
        Ok(())
    }

    fn handle_key(&mut self, key: Key) -> Result<()> {
        let kb = &self.mode.key_bindings;
        let action = kb
            .on_key
            .get(&key.name)
            .cloned()
            .or_else(|| {
                if key.is_alphabet() {
                    kb.on_alphabet.clone()
                } else {
                    None
                }
            })
            .or_else(|| {
                if key.is_number() {
                    kb.on_number.clone()
                } else {
                    None
                }
            })
            .or_else(|| {
                if key.is_alphanumeric() {
                    kb.on_alphanumeric.clone()
                } else {
                    None
                }
            })
            .or_else(|| {
                if key.is_special_character() {
                    kb.on_special_character.clone()
                } else {
                    None
                }
            })
            .or_else(|| {
                if key.is_character() {
                    kb.on_character.clone()
                } else {
                    None
                }
            })
            .or_else(|| {
                if key.is_navigation() {
                    kb.on_navigation.clone()
                } else {
                    None
                }
            })
            .or_else(|| {
                if key.is_function() {
                    kb.on_function.clone()
                } else {
                    None
                }
            })
            .or_else(|| kb.default.clone());

        if let Some(action) = action {
            for msg in action.messages {
                self.enqueue(Task::new(MsgIn::External(msg), Some(key.clone())));
            }
        }
        Ok(())
    }

    fn handle_external(&mut self, msg: ExternalMsg, key: Option<&Key>) -> Result<()> {
        if self.read_only && !msg.is_read_only() {
            bail!("could not execute code in read-only mode.");
        }
        use ExternalMsg::*;
        match msg {
            ExplorePwd => self.explore_pwd()?,
            ExplorePwdAsync => self.msg_out.push_back(MsgOut::ExplorePwdAsync),
            ExploreParentsAsync => self.msg_out.push_back(MsgOut::ExploreParentsAsync),
            TryCompletePath => self.try_complete_path()?,
            ClearScreen => self.msg_out.push_back(MsgOut::ClearScreen),
            Refresh => self.msg_out.push_back(MsgOut::Refresh),
            FocusNext => self.focus_next(),
            FocusNextSelection => self.focus_next_selection(),
            FocusNextByRelativeIndex(i) => self.focus_next_by_relative_index(i),
            FocusNextByRelativeIndexFromInput => self.focus_next_by_relative_index_from_input()?,
            FocusPrevious => self.focus_previous(),
            FocusPreviousSelection => self.focus_previous_selection(),
            FocusPreviousByRelativeIndex(i) => self.focus_previous_by_relative_index(i),
            FocusPreviousByRelativeIndexFromInput => {
                self.focus_previous_by_relative_index_from_input()?
            }
            FocusFirst => self.focus_first(true),
            FocusLast => self.focus_last(true),
            FocusPath(p) => self.focus_path(&p, true)?,
            FocusPathFromInput => self.focus_path_from_input()?,
            FocusByIndex(i) => self.focus_by_index(i, true),
            FocusByIndexFromInput => self.focus_by_index_from_input()?,
            FocusByFileName(n) => self.focus_by_file_name(&n, true)?,
            ScrollUp => self.scroll_up(),
            ScrollDown => self.scroll_down(),
            ScrollUpHalf => self.scroll_up_half(),
