            CallSilently0(c) => self.msg_out.push_back(MsgOut::CallSilently0(c)),
            BashExec(s) => self.msg_out.push_back(MsgOut::Call(bash_command(s))),
            BashExec0(s) => self.msg_out.push_back(MsgOut::Call0(bash_command(s))),
            BashExecSilently(s) => self.msg_out.push_back(MsgOut::CallSilently(bash_command(s))),
            BashExecSilently0(s) => {
                self.msg_out.push_back(MsgOut::CallSilently0(bash_command(s)))
            }
            CallLua(f) => self.msg_out.push_back(MsgOut::CallLua(f)),
            CallLuaSilently(f) => self.msg_out.push_back(MsgOut::CallLuaSilently(f)),
            LuaEval(c) => self.msg_out.push_back(MsgOut::LuaEval(c)),
