            LogWarning(m) => self.log_warning(m),
            LogError(m) => self.log_error(m),
            Debug(p) => self.msg_out.push_back(MsgOut::Debug(p)),
            Quit => self.msg_out.push_back(MsgOut::Quit),
            PrintPwdAndQuit => self.msg_out.push_back(MsgOut::PrintPwdAndQuit),
            PrintFocusPathAndQuit => self.msg_out.push_back(MsgOut::PrintFocusPathAndQuit),
            PrintSelectionAndQuit => self.msg_out.push_back(MsgOut::PrintSelectionAndQuit),
            PrintResultAndQuit => self.msg_out.push_back(MsgOut::PrintResultAndQuit),
            PrintAppStateAndQuit => self.msg_out.push_back(MsgOut::PrintAppStateAndQuit),
            Terminate => bail!("terminated"),
        }
        Ok(())
    }

    // ------------------------------------------------------------ exploring

    pub fn explore_pwd(&mut self) -> Result<()> {
        let dir = explorer::explore(Path::new(&self.pwd), &self.explorer_config)
            .map_err(|e| anyhow::anyhow!("could not explore {:?}: {}", self.pwd, e))?;
        let focus_name = self
            .last_focus
            .get(&self.pwd)
            .cloned()
            .flatten()
            .or_else(|| self.focused_node().map(|n| n.relative_path.clone()));
        let focus = focus_name
            .and_then(|name| dir.iter().position(|n| n.relative_path == name))
            .unwrap_or(0);
        let changed = self
            .directory_buffer
            .as_ref()
            .map(|d| d.parent != self.pwd)
            .unwrap_or(true);
        let buf = DirectoryBuffer::new(self.pwd.clone(), dir, focus);
        self.set_directory(buf);
        if changed {
            if let Some(n) = self.focused_node() {
                let p = n.absolute_path.clone();
                self.history.push(p);
            }
        }
        Ok(())
    }

    pub fn set_directory(&mut self, mut dir: DirectoryBuffer) {
        if dir.parent != self.pwd {
            // Stale result for a directory we already left.
            return;
        }
        let focus_name = self
            .directory_buffer
            .as_ref()
            .filter(|d| d.parent == dir.parent)
            .and_then(|d| d.focused_node().map(|n| n.relative_path.clone()))
            .or_else(|| self.last_focus.get(&dir.parent).cloned().flatten());
        if let Some(name) = focus_name {
            if let Some(idx) = dir.nodes.iter().position(|n| n.relative_path == name) {
                dir.focus = idx;
            } else if dir.focus >= dir.total {
                dir.focus = dir.total.saturating_sub(1);
            }
        } else if dir.focus >= dir.total {
            dir.focus = 0;
        }
        let focus_name = dir.focused_node().map(|n| n.relative_path.clone());
        self.last_focus.insert(dir.parent.clone(), focus_name);
        self.directory_buffer = Some(dir);
    }

    fn save_focus(&mut self) {
        if let Some(d) = &self.directory_buffer {
            let name = d.focused_node().map(|n| n.relative_path.clone());
            self.last_focus.insert(d.parent.clone(), name);
        }
    }

    pub fn refresh_selection(&mut self) {
        self.selection = self
            .selection
            .iter()
            .filter(|n| Path::new(&n.absolute_path).exists())
            .cloned()
            .collect();
    }

    // ------------------------------------------------------------ focus

    fn set_focus(&mut self, focus: usize, save_history: bool) {
        if let Some(d) = self.directory_buffer.as_mut() {
            if d.total == 0 {
                return;
            }
            d.focus = focus.min(d.total - 1);
            let name = d.focused_node().map(|n| n.relative_path.clone());
            let path = d.focused_node().map(|n| n.absolute_path.clone());
            self.last_focus.insert(d.parent.clone(), name);
            if save_history {
                if let Some(p) = path {
                    self.history.push(p);
                }
            }
        }
    }

    fn focus_next(&mut self) {
        let bounded = self.config.general.enforce_bounded_index_navigation;
        if let Some(d) = &self.directory_buffer {
            if d.total == 0 {
                return;
            }
            let f = if d.focus + 1 >= d.total {
                if bounded {
                    d.focus
                } else {
                    0
                }
            } else {
                d.focus + 1
            };
            self.set_focus(f, false);
        }
    }

    fn focus_previous(&mut self) {
        let bounded = self.config.general.enforce_bounded_index_navigation;
        if let Some(d) = &self.directory_buffer {
            if d.total == 0 {
                return;
            }
            let f = if d.focus == 0 {
                if bounded {
                    0
                } else {
                    d.total - 1
                }
            } else {
                d.focus - 1
            };
            self.set_focus(f, false);
        }
    }

    fn focus_next_by_relative_index(&mut self, i: usize) {
        if let Some(d) = &self.directory_buffer {
            if d.total == 0 {
                return;
            }
            let f = (d.focus + i).min(d.total - 1);
            self.set_focus(f, true);
        }
    }

    fn focus_previous_by_relative_index(&mut self, i: usize) {
        if let Some(d) = &self.directory_buffer {
            if d.total == 0 {
                return;
            }
            let f = d.focus.saturating_sub(i);
            self.set_focus(f, true);
        }
    }

    fn input_value(&self) -> Option<String> {
        self.input.buffer.as_ref().map(|b| b.value())
    }

    fn focus_next_by_relative_index_from_input(&mut self) -> Result<()> {
        if let Some(v) = self.input_value() {
            let i: usize = v.parse()?;
            self.focus_next_by_relative_index(i);
        }
        Ok(())
    }

    fn focus_previous_by_relative_index_from_input(&mut self) -> Result<()> {
        if let Some(v) = self.input_value() {
            let i: usize = v.parse()?;
            self.focus_previous_by_relative_index(i);
        }
        Ok(())
    }

    fn focus_first(&mut self, save_history: bool) {
        self.set_focus(0, save_history);
    }

    fn focus_last(&mut self, save_history: bool) {
        if let Some(d) = &self.directory_buffer {
            if d.total > 0 {
                let f = d.total - 1;
                self.set_focus(f, save_history);
            }
        }
    }

    fn focus_by_index(&mut self, i: usize, save_history: bool) {
        self.set_focus(i, save_history);
    }

    fn focus_by_index_from_input(&mut self) -> Result<()> {
        if let Some(v) = self.input_value() {
            let i: usize = v.parse()?;
            self.focus_by_index(i, true);
        }
        Ok(())
    }

    fn focus_by_file_name(&mut self, name: &str, save_history: bool) -> Result<()> {
        let idx = self
            .directory_buffer
            .as_ref()
            .and_then(|d| d.nodes.iter().position(|n| n.relative_path == name));
        match idx {
            Some(i) => {
                self.set_focus(i, save_history);
                Ok(())
            }
            None => bail!("{:?} not found in $PWD", name),
        }
    }

    pub fn focus_path(&mut self, path: &str, save_history: bool) -> Result<()> {
        let path = self.absolutize(path);
        let parent = match path.parent() {
            Some(p) => p.to_path_buf(),
            None => bail!("could not focus on {:?}", path.to_string_lossy()),
        };
        let name = match path.file_name() {
            Some(n) => n.to_string_lossy().to_string(),
            None => bail!("could not focus on {:?}", path.to_string_lossy()),
        };
        let parent_str = parent.to_string_lossy().to_string();
        if parent_str != self.pwd {
            self.change_directory(&parent_str, false)?;
            self.explore_pwd()?;
        }
        self.focus_by_file_name(&name, save_history)
    }

    fn focus_path_from_input(&mut self) -> Result<()> {
        if let Some(v) = self.input_value() {
            self.focus_path(&v, true)?;
        }
        Ok(())
    }

    fn focus_next_selection(&mut self) {
        if let Some(d) = &self.directory_buffer {
            if d.total == 0 || self.selection.is_empty() {
                return;
            }
            let start = d.focus;
            for step in 1..=d.total {
                let i = (start + step) % d.total;
                if self.selection.contains(&d.nodes[i]) {
                    self.set_focus(i, false);
                    return;
                }
            }
        }
    }

    fn focus_previous_selection(&mut self) {
        if let Some(d) = &self.directory_buffer {
            if d.total == 0 || self.selection.is_empty() {
                return;
            }
            let start = d.focus;
            for step in 1..=d.total {
                let i = (start + d.total - step) % d.total;
                if self.selection.contains(&d.nodes[i]) {
                    self.set_focus(i, false);
                    return;
                }
            }
        }
    }

    // ------------------------------------------------------------ scrolling

    pub fn visible_height(&self) -> usize {
        self.last_table_height.max(1)
    }

    fn scroll_up(&mut self) {
        let h = self.visible_height();
        self.focus_previous_by_relative_index_nohist(h);
    }

    fn scroll_down(&mut self) {
        let h = self.visible_height();
        self.focus_next_by_relative_index_nohist(h);
    }

    fn scroll_up_half(&mut self) {
        let h = self.visible_height() / 2;
        self.focus_previous_by_relative_index_nohist(h);
    }

    fn scroll_down_half(&mut self) {
        let h = self.visible_height() / 2;
        self.focus_next_by_relative_index_nohist(h);
    }

    fn focus_next_by_relative_index_nohist(&mut self, i: usize) {
        if let Some(d) = &self.directory_buffer {
            if d.total == 0 {
                return;
            }
            let f = (d.focus + i).min(d.total - 1);
            self.set_focus(f, false);
        }
    }

    fn focus_previous_by_relative_index_nohist(&mut self, i: usize) {
        if let Some(d) = &self.directory_buffer {
            if d.total == 0 {
                return;
            }
            let f = d.focus.saturating_sub(i);
            self.set_focus(f, false);
        }
    }

    // ------------------------------------------------------------ navigation

    pub fn change_directory(&mut self, dir: &str, save_history: bool) -> Result<()> {
        let dir = self.absolutize(dir);
        self.check_vroot(&dir)?;
        std::env::set_current_dir(&dir)
            .map_err(|e| anyhow::anyhow!("could not enter {:?}: {}", dir.to_string_lossy(), e))?;
        self.save_focus();
        let dir_str = dir.to_string_lossy().to_string();
        self.pwd = dir_str.clone();
        self.explorer_config.searcher = None;
        if save_history {
            let h = if dir_str.ends_with('/') {
                dir_str.clone()
            } else {
                format!("{}/", dir_str)
            };
            self.history.push(h);
        }
        self.msg_out.push_back(MsgOut::ExplorePwdAsync);
        Ok(())
    }

    fn enter(&mut self) -> Result<()> {
        if let Some(n) = self.focused_node() {
            let is_dir = n.is_dir || n.canonical.as_ref().map(|c| c.is_dir).unwrap_or(false);
            if is_dir {
                let p = n.absolute_path.clone();
                self.change_directory(&p, true)?;
            }
        }
        Ok(())
    }

    fn back(&mut self) -> Result<()> {
        let pwd = self.pwd.clone();
        if Path::new(&pwd).parent().is_some() {
            self.focus_path(&pwd, true)?;
        }
        Ok(())
    }

    fn visit_history_path(&mut self, path: String) -> Result<()> {
        if path.ends_with('/') {
            self.change_directory(&path, false)?;
        } else {
            self.focus_path(&path, false)?;
        }
        Ok(())
    }

    fn last_visited_path(&mut self) -> Result<()> {
        if let Some(p) = self.history.visit_last().cloned() {
            self.visit_history_path(p)?;
        }
        Ok(())
    }

    fn next_visited_path(&mut self) -> Result<()> {
        if let Some(p) = self.history.visit_next().cloned() {
            self.visit_history_path(p)?;
        }
        Ok(())
    }

    fn previous_visited_deep_branch(&mut self) -> Result<()> {
        let pwd = self.pwd.clone();
        let candidate = self
            .history
            .paths
            .iter()
            .take(self.history.loc + 1)
            .rev()
            .find(|p| p.starts_with(&pwd))
            .cloned();
        if let Some(p) = candidate {
            let dir = p.trim_end_matches('/').to_string();
            if dir != pwd {
                self.change_directory(&dir, false)?;
            }
        }
        Ok(())
    }

    fn next_visited_deep_branch(&mut self) -> Result<()> {
        let pwd = self.pwd.clone();
        let candidate = self
            .history
            .paths
            .iter()
            .skip(self.history.loc)
            .find(|p| p.starts_with(&pwd))
            .cloned();
        if let Some(p) = candidate {
            let dir = p.trim_end_matches('/').to_string();
            if dir != pwd {
                self.change_directory(&dir, false)?;
            }
        }
        Ok(())
    }

    fn follow_symlink(&mut self) -> Result<()> {
        let target = self
            .focused_node()
            .and_then(|n| n.symlink.as_ref().map(|s| s.absolute_path.clone()));
        if let Some(t) = target {
            self.focus_path(&t, true)?;
        }
        Ok(())
    }

    // ------------------------------------------------------------ vroot

    fn set_vroot(&mut self, path: &str) -> Result<()> {
        let path = self.absolutize(path);
        if !path.is_dir() {
            bail!("not a directory: {:?}", path.to_string_lossy());
        }
        let vroot = path.to_string_lossy().to_string();
        self.vroot = Some(vroot.clone());
        if !Path::new(&self.pwd).starts_with(&path) {
            self.change_directory(&vroot, true)?;
        }
        Ok(())
    }

    fn unset_vroot(&mut self) -> Result<()> {
        self.vroot = None;
        Ok(())
    }

    fn toggle_vroot(&mut self) -> Result<()> {
        match (&self.vroot, &self.initial_vroot) {
            (Some(v), Some(iv)) if v == iv => {
                let pwd = self.pwd.clone();
                self.set_vroot(&pwd)
            }
            (Some(_), Some(iv)) => {
                let iv = iv.clone();
                self.set_vroot(&iv)
            }
            (Some(_), None) => self.unset_vroot(),
            (None, Some(iv)) => {
                let iv = iv.clone();
                self.set_vroot(&iv)
            }
            (None, None) => {
                let pwd = self.pwd.clone();
                self.set_vroot(&pwd)
            }
        }
    }

    fn reset_vroot(&mut self) -> Result<()> {
        match self.initial_vroot.clone() {
            Some(iv) => self.set_vroot(&iv),
            None => self.unset_vroot(),
        }
    }

    // ------------------------------------------------------------ input

    fn update_input_buffer(&mut self, op: &InputOperation) {
        let buf = self.input.buffer.get_or_insert_with(InputBuffer::default);
        buf.handle(op);
    }

    fn update_input_buffer_from_key(&mut self, key: Option<&Key>) {
        if let Some(op) = key.and_then(|k| k.to_input_operation()) {
            self.update_input_buffer(&op);
        }
    }

    fn buffer_input(&mut self, s: &str) {
        let buf = self.input.buffer.get_or_insert_with(InputBuffer::default);
        buf.push_str(s);
    }

    fn buffer_input_from_key(&mut self, key: Option<&Key>) {
        if let Some(c) = key.and_then(|k| k.to_char()) {
            self.buffer_input(&c.to_string());
        }
    }

    fn set_input_buffer(&mut self, s: &str) {
        self.input.buffer = Some(InputBuffer::new(s));
        self.logs_hidden = true;
    }

    fn remove_input_buffer_last_character(&mut self) {
        if let Some(b) = self.input.buffer.as_mut() {
            b.remove_last_char();
            self.logs_hidden = true;
        }
    }

    fn remove_input_buffer_last_word(&mut self) {
        if let Some(b) = self.input.buffer.as_mut() {
            b.remove_last_word();
            self.logs_hidden = true;
        }
    }

    fn reset_input_buffer(&mut self) {
        self.input.buffer = None;
        self.input.prompt = self.config.general.prompt.format.clone().unwrap_or_default();
    }

    // ------------------------------------------------------------ modes

    fn apply_mode(&mut self, mode: Mode, keep_input: bool) {
        let prompt = mode
            .prompt
            .clone()
            .or_else(|| self.config.general.prompt.format.clone())
            .unwrap_or_default();
        let current = std::mem::replace(&mut self.mode, self.sanitize_mode(mode));
        self.last_modes.push(current);
        if !keep_input {
            self.input.buffer = None;
        }
        self.input.prompt = prompt;
    }

    fn switch_mode(&mut self, name: &str) -> Result<()> {
        match self.config.modes.get(name).cloned() {
            Some(m) => {
                self.apply_mode(m, false);
                Ok(())
            }
            None => bail!("mode not found: {}", name),
        }
    }

    fn switch_mode_keeping_input_buffer(&mut self, name: &str) -> Result<()> {
        match self.config.modes.get(name).cloned() {
            Some(m) => {
                self.apply_mode(m, true);
                Ok(())
            }
            None => bail!("mode not found: {}", name),
        }
    }

    fn switch_mode_builtin(&mut self, name: &str) -> Result<()> {
        match self.config.modes.get_builtin(name).cloned() {
            Some(m) => {
                self.apply_mode(m, false);
                Ok(())
            }
            None => bail!("builtin mode not found: {}", name),
        }
    }

    fn switch_mode_builtin_keeping_input_buffer(&mut self, name: &str) -> Result<()> {
        match self.config.modes.get_builtin(name).cloned() {
            Some(m) => {
                self.apply_mode(m, true);
                Ok(())
            }
            None => bail!("builtin mode not found: {}", name),
        }
    }

    fn switch_mode_custom(&mut self, name: &str) -> Result<()> {
        match self.config.modes.get_custom(name).cloned() {
            Some(m) => {
                self.apply_mode(m, false);
                Ok(())
            }
            None => bail!("custom mode not found: {}", name),
        }
    }

    fn switch_mode_custom_keeping_input_buffer(&mut self, name: &str) -> Result<()> {
        match self.config.modes.get_custom(name).cloned() {
            Some(m) => {
                self.apply_mode(m, true);
                Ok(())
            }
            None => bail!("custom mode not found: {}", name),
        }
    }

    fn pop_mode(&mut self) -> Result<()> {
        if let Some(m) = self.last_modes.pop() {
            let prompt = m
                .prompt
                .clone()
                .or_else(|| self.config.general.prompt.format.clone())
                .unwrap_or_default();
            self.mode = m;
            self.input.prompt = prompt;
        }
        self.input.buffer = None;
        Ok(())
    }

    fn pop_mode_keeping_input_buffer(&mut self) -> Result<()> {
        if let Some(m) = self.last_modes.pop() {
            let prompt = m
                .prompt
                .clone()
                .or_else(|| self.config.general.prompt.format.clone())
                .unwrap_or_default();
            self.mode = m;
            self.input.prompt = prompt;
        }
        Ok(())
    }

    // ------------------------------------------------------------ layouts

    fn switch_layout(&mut self, name: &str) -> Result<()> {
        match self.config.layouts.get(name).cloned() {
            Some(l) => {
                self.layout = l;
                Ok(())
            }
            None => bail!("layout not found: {}", name),
        }
    }

    fn switch_layout_builtin(&mut self, name: &str) -> Result<()> {
        match self.config.layouts.get_builtin(name).cloned() {
            Some(l) => {
                self.layout = l;
                Ok(())
            }
            None => bail!("builtin layout not found: {}", name),
        }
    }

    fn switch_layout_custom(&mut self, name: &str) -> Result<()> {
        match self.config.layouts.get_custom(name).cloned() {
            Some(l) => {
                self.layout = l;
                Ok(())
            }
            None => bail!("custom layout not found: {}", name),
        }
    }

    // ------------------------------------------------------------ selection

    fn select(&mut self) {
        if let Some(n) = self.focused_node().cloned() {
            self.selection.insert(n);
        }
    }

    fn select_all(&mut self) {
        if let Some(d) = &self.directory_buffer {
            let nodes: Vec<Node> = d.nodes.clone();
            for n in nodes {
                self.selection.insert(n);
            }
        }
    }

    fn select_path(&mut self, path: &str) {
        let p = self.absolutize(path);
        if let Some(n) = Node::from_path(&p) {
            self.selection.insert(n);
        }
    }

    fn un_select(&mut self) {
        if let Some(n) = self.focused_node().cloned() {
            self.selection.shift_remove(&n);
        }
    }

    fn un_select_all(&mut self) {
        if let Some(d) = &self.directory_buffer {
            let nodes: Vec<Node> = d.nodes.clone();
            for n in nodes {
                self.selection.shift_remove(&n);
            }
        }
    }

    fn un_select_path(&mut self, path: &str) {
        let p = self.absolutize(path);
        if let Some(n) = Node::from_path(&p) {
            self.selection.shift_remove(&n);
        }
    }

    fn toggle_selection(&mut self) {
        if let Some(n) = self.focused_node().cloned() {
            if self.selection.contains(&n) {
                self.selection.shift_remove(&n);
            } else {
                self.selection.insert(n);
            }
        }
    }

    fn toggle_select_all(&mut self) {
        if let Some(d) = &self.directory_buffer {
            let all_selected = d.nodes.iter().all(|n| self.selection.contains(n));
            if all_selected {
                self.un_select_all();
            } else {
                self.select_all();
            }
        }
    }

    fn toggle_selection_by_path(&mut self, path: &str) {
        let p = self.absolutize(path);
        if let Some(n) = Node::from_path(&p) {
            if self.selection.contains(&n) {
                self.selection.shift_remove(&n);
            } else {
                self.selection.insert(n);
            }
        }
    }

    // ------------------------------------------------------------ filters

    fn toggle_node_filter(&mut self, f: NodeFilterApplicable) {
        if self.explorer_config.filters.contains(&f) {
            self.explorer_config.filters.shift_remove(&f);
        } else {
            self.explorer_config.filters.insert(f);
        }
    }

    fn add_node_filter_from_input(&mut self, f: NodeFilter) {
        if let Some(input) = self.input_value() {
            self.explorer_config.filters.insert(NodeFilterApplicable {
                filter: f,
                input,
            });
        }
    }

    fn remove_node_filter_from_input(&mut self, f: NodeFilter) {
        if let Some(input) = self.input_value() {
            self.explorer_config.filters.shift_remove(&NodeFilterApplicable {
                filter: f,
                input,
            });
        }
    }

    fn reset_node_filters(&mut self) {
        self.explorer_config.filters.clear();
        if !self.config.general.show_hidden {
            self.explorer_config.filters.insert(NodeFilterApplicable {
                filter: NodeFilter::RelativePathDoesNotStartWith,
                input: ".".to_string(),
            });
        }
    }

    // ------------------------------------------------------------ sorters

    fn add_node_sorter(&mut self, s: NodeSorterApplicable) {
        self.explorer_config.sorters.insert(s);
    }

    fn remove_node_sorter(&mut self, s: NodeSorter) {
        self.explorer_config.sorters.retain(|x| x.sorter != s);
    }

    fn reverse_node_sorter(&mut self, s: NodeSorter) {
        self.explorer_config.sorters = self
            .explorer_config
            .sorters
            .iter()
            .map(|x| {
                if x.sorter == s {
                    NodeSorterApplicable {
                        sorter: x.sorter,
                        reverse: !x.reverse,
                    }
                } else {
                    x.clone()
                }
            })
            .collect();
    }

    fn toggle_node_sorter(&mut self, s: NodeSorterApplicable) {
        if self.explorer_config.sorters.contains(&s) {
            self.explorer_config.sorters.shift_remove(&s);
        } else {
            self.explorer_config.sorters.insert(s);
        }
    }

    fn reverse_node_sorters(&mut self) {
        self.explorer_config.sorters = self
            .explorer_config
            .sorters
            .iter()
            .map(|x| NodeSorterApplicable {
                sorter: x.sorter,
                reverse: !x.reverse,
            })
            .collect();
    }

    fn reset_node_sorters(&mut self) {
        self.explorer_config.sorters = self
            .config
            .general
            .initial_sorting
            .clone()
            .unwrap_or_default();
    }

    // ------------------------------------------------------------ search

    fn search(&mut self, pattern: &str, algorithm: Option<SearchAlgorithm>, unordered: Option<bool>) {
        let search_cfg = &self.config.general.search;
        let searcher = match self.explorer_config.searcher.take() {
            Some(mut s) => {
                s.pattern = pattern.to_string();
                if let Some(a) = algorithm {
                    s.algorithm = a;
                }
                if let Some(u) = unordered {
                    s.unordered = u;
                }
                s
            }
            None => NodeSearcherApplicable {
                pattern: pattern.to_string(),
                recoverable_focus: self.focused_node().map(|n| n.absolute_path.clone()),
                algorithm: algorithm.unwrap_or(search_cfg.algorithm),
                unordered: unordered.unwrap_or(search_cfg.unordered),
                exact_mode: search_cfg.exact_mode,
                rank_criteria: search_cfg.rank_criteria.clone(),
            },
        };
        self.explorer_config.searcher = Some(searcher);
    }

    fn search_from_input(&mut self, algorithm: Option<SearchAlgorithm>, unordered: Option<bool>) {
        if let Some(v) = self.input_value() {
            self.search(&v, algorithm, unordered);
        }
    }

    fn toggle_search_algorithm(&mut self) {
        if let Some(s) = self.explorer_config.searcher.as_mut() {
            s.algorithm = s.algorithm.toggle();
        } else {
            let a = self.config.general.search.algorithm.toggle();
            self.config.general.search.algorithm = a;
        }
    }

    fn set_search_order(&mut self, unordered: bool) {
        if let Some(s) = self.explorer_config.searcher.as_mut() {
            s.unordered = unordered;
        } else {
            self.config.general.search.unordered = unordered;
        }
    }

    fn toggle_search_order(&mut self) {
        if let Some(s) = self.explorer_config.searcher.as_mut() {
            s.unordered = !s.unordered;
        } else {
            self.config.general.search.unordered = !self.config.general.search.unordered;
        }
    }

    fn accept_search(&mut self) -> Result<()> {
        let focus = self.focused_node().map(|n| n.relative_path.clone());
        self.explorer_config.searcher = None;
        self.explore_pwd()?;
        if let Some(name) = focus {
            let _ = self.focus_by_file_name(&name, false);
        }
        Ok(())
    }

    fn cancel_search(&mut self) -> Result<()> {
        let recover = self
            .explorer_config
            .searcher
            .take()
            .and_then(|s| s.recoverable_focus);
        self.explore_pwd()?;
        if let Some(p) = recover {
            let _ = self.focus_path(&p, false);
        }
        Ok(())
    }

    // ------------------------------------------------------------ completion

    fn try_complete_path(&mut self) -> Result<()> {
        let input = match self.input_value() {
            Some(i) => i,
            None => return Ok(()),
        };
        let (dir, prefix) = if input.ends_with('/') || input.is_empty() {
            (self.absolutize(&input), String::new())
        } else {
            let p = self.absolutize(&input);
            let name = p
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_default();
            let parent = p.parent().map(|x| x.to_path_buf()).unwrap_or(p.clone());
            (parent, name)
        };
        let entries: Vec<String> = match std::fs::read_dir(&dir) {
            Ok(rd) => rd
                .filter_map(|e| e.ok())
                .map(|e| e.file_name().to_string_lossy().to_string())
                .filter(|n| n.starts_with(&prefix))
                .collect(),
            Err(_) => return Ok(()),
        };
        if entries.is_empty() {
            return Ok(());
        }
        let completed: PathBuf = if entries.len() == 1 {
            let p = dir.join(&entries[0]);
            p
        } else {
            let mut common: Vec<char> = entries[0].chars().collect();
            for e in &entries[1..] {
                let ec: Vec<char> = e.chars().collect();
                let mut n = 0;
                while n < common.len() && n < ec.len() && common[n] == ec[n] {
                    n += 1;
                }
                common.truncate(n);
            }
            let common: String = common.into_iter().collect();
            dir.join(common)
        };
        let is_dir = completed.is_dir() && (entries.len() == 1 || completed != dir);
        let mut shortened = path_util::shorten(
            &completed.to_string_lossy(),
            &path_util::RelativityConfig {
                base: Some(self.pwd.clone()),
                with_prefix_dots: true,
                without_suffix_dots: true,
            },
        )
        .unwrap_or_else(|_| completed.to_string_lossy().to_string());
        if is_dir && !shortened.ends_with('/') {
            shortened.push('/');
        }
        self.set_input_buffer(&shortened);
        Ok(())
    }

    // ------------------------------------------------------------ output helpers

    pub fn result(&self) -> Vec<Node> {
        if self.selection.is_empty() {
            self.focused_node().cloned().into_iter().collect()
        } else {
            self.selection.iter().cloned().collect()
        }
    }

    pub fn result_str(&self, delimiter: char) -> String {
        if self.print_pwd_as_result {
            return format!("{}{}", self.pwd, delimiter);
        }
        self.result()
            .iter()
            .map(|n| format!("{}{}", n.absolute_path, delimiter))
            .collect()
    }

    pub fn selection_str(&self, delimiter: char) -> String {
        self.selection
            .iter()
            .map(|n| format!("{}{}", n.absolute_path, delimiter))
            .collect()
    }

    pub fn directory_nodes_str(&self, delimiter: char) -> String {
        self.directory_buffer
            .as_ref()
            .map(|d| {
                d.nodes
                    .iter()
                    .map(|n| format!("{}{}", n.absolute_path, delimiter))
                    .collect()
            })
            .unwrap_or_default()
    }

    pub fn logs_str(&self, delimiter: char) -> String {
        self.logs
            .iter()
            .map(|l| format!("{}{}", l, delimiter))
            .collect()
    }

    pub fn history_str(&self, delimiter: char) -> String {
        self.history
            .paths
            .iter()
            .map(|p| format!("{}{}", p, delimiter))
            .collect()
    }

    pub fn global_help_menu_str(&self) -> String {
        let builtin = self.config.modes.builtin.clone();
        let custom = self.config.modes.custom.clone();
        let mut out = String::new();
        let current = (self.mode.name.clone(), self.mode.clone());
        let mut all: Vec<(String, Mode)> = vec![current];
        for (name, mode) in builtin.iter() {
            all.push((name.to_string(), mode.clone()));
        }
        for (name, mode) in custom.iter() {
            all.push((name.clone(), mode.clone()));
        }
        for (name, mode) in all {
            let mode = self.sanitize_mode(mode);
            out.push_str(&format!("### {}\n\n", name));
            out.push_str(&format!(
                " {:15} | {:25} | {}\n",
                "key", "remaps", "action"
            ));
            out.push_str(&format!(
                " {:15} | {:25} | {}\n",
                "---------------", "-------------------------", "------"
            ));
            for line in mode.help_menu(self.config.general.hide_remaps_in_help_menu) {
                match line {
                    crate::config::HelpMenuLine::KeyMap(k, remaps, h) => {
                        out.push_str(&format!(
                            " {:15} | {:25} | {}\n",
                            k,
                            remaps.join(", "),
                            h
                        ));
                    }
                    crate::config::HelpMenuLine::Paragraph(p) => {
                        out.push_str(&format!(" {}\n", p));
                    }
                }
            }
            out.push_str("\n\n");
        }
        out
    }

    pub fn to_yaml(&self) -> String {
        serde_yaml::to_string(self).unwrap_or_default()
    }
}

pub fn bash_command(script: String) -> Command {
    Command {
        command: "bash".to_string(),
        args: vec!["-c".to_string(), script],
    }
}
