//! Minimal LS_COLORS support: parse the environment variable (or the
//! conventional defaults) and compute a style for a path.

use crate::config::{Color, Style};
use std::collections::HashMap;
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::Path;

const DEFAULT_LS_COLORS: &str = "rs=0:lc=\x1b[:rc=m:cl=\x1b[K:ex=01;32:sg=30;43:su=37;41:di=01;34:st=37;44:ow=34;42:tw=30;42:ln=01;36:bd=01;33:cd=01;33:do=01;35:pi=33:so=01;35:";

#[derive(Debug, Clone, Default)]
pub struct LsColors {
    indicators: HashMap<String, Style>,
    suffixes: Vec<(String, Style)>,
}

fn parse_color(parts: &[u8], i: &mut usize, bright: bool) -> Option<Color> {
    let code = parts[*i];
    let base = if bright { 90 } else { 30 };
    let c = match code - base {
        0 => {
            if bright {
                Color::DarkGray
            } else {
                Color::Black
            }
        }
        1 => {
            if bright {
                Color::LightRed
            } else {
                Color::Red
            }
        }
        2 => {
            if bright {
                Color::LightGreen
            } else {
                Color::Green
            }
        }
        3 => {
            if bright {
                Color::LightYellow
            } else {
                Color::Yellow
            }
        }
        4 => {
            if bright {
                Color::LightBlue
            } else {
                Color::Blue
            }
        }
        5 => {
            if bright {
                Color::LightMagenta
            } else {
                Color::Magenta
            }
        }
        6 => {
            if bright {
                Color::LightCyan
            } else {
                Color::Cyan
            }
        }
        7 => Color::White,
        _ => return None,
    };
    Some(c)
}

fn parse_style(code: &str) -> Option<Style> {
    let parts: Vec<u8> = code
        .split(';')
        .map(|p| p.parse::<u8>().ok())
        .collect::<Option<Vec<u8>>>()?;
    let mut style = Style::default();
    let mut i = 0;
    while i < parts.len() {
        let p = parts[i];
        match p {
            30..=37 => style.fg = parse_color(&parts, &mut i, false),
            90..=97 => style.fg = parse_color(&parts, &mut i, true),
            40..=47 => {
                style.bg = parse_color(&[p - 10], &mut 0, false);
            }
            100..=107 => {
                style.bg = parse_color(&[p - 10], &mut 0, true);
            }
            38 | 48 => {
                let is_fg = p == 38;
                if i + 1 < parts.len() {
                    match parts[i + 1] {
                        5 => {
                            if i + 2 < parts.len() {
                                let c = Color::Indexed(parts[i + 2]);
                                if is_fg {
                                    style.fg = Some(c);
                                } else {
                                    style.bg = Some(c);
                                }
                                i += 2;
                            }
                        }
                        2 => {
                            if i + 4 < parts.len() {
                                let c = Color::Rgb(parts[i + 2], parts[i + 3], parts[i + 4]);
                                if is_fg {
                                    style.fg = Some(c);
                                } else {
                                    style.bg = Some(c);
                                }
                                i += 4;
                            }
                        }
                        _ => {}
                    }
                }
            }
            _ => {} // modifiers are intentionally ignored
        }
        i += 1;
    }
    Some(style)
}

impl LsColors {
    pub fn from_env() -> Self {
        let value = std::env::var("LS_COLORS")
            .ok()
            .filter(|v| !v.is_empty())
            .unwrap_or_else(|| DEFAULT_LS_COLORS.to_string());
        Self::from_string(&value)
    }

    pub fn from_string(s: &str) -> Self {
        let mut ls = LsColors::default();
        for entry in s.split(':') {
            let (k, v) = match entry.split_once('=') {
                Some(kv) => kv,
                None => continue,
            };
            let style = match parse_style(v) {
                Some(s) => s,
                None => continue,
            };
            if let Some(stripped) = k.strip_prefix('*') {
                ls.suffixes.push((stripped.to_string(), style));
            } else {
                ls.indicators.insert(k.to_string(), style);
            }
        }
        ls
    }

    fn get(&self, key: &str) -> Option<Style> {
        self.indicators.get(key).cloned()
    }

    pub fn style_for_path(&self, path: &Path) -> Option<Style> {
        let meta = path.symlink_metadata().ok()?;
        let ft = meta.file_type();
        let mode = meta.mode();
        if ft.is_symlink() {
            return self.get("ln");
        }
        if ft.is_dir() {
            let sticky = mode & 0o1000 != 0;
            let ow = mode & 0o002 != 0;
            let key = match (sticky, ow) {
                (true, true) => "tw",
                (false, true) => "ow",
                (true, false) => "st",
                (false, false) => "di",
            };
            return self.get(key);
        }
        if ft.is_fifo() {
            return self.get("pi");
        }
        if ft.is_socket() {
            return self.get("so");
        }
        if ft.is_block_device() {
            return self.get("bd");
        }
        if ft.is_char_device() {
            return self.get("cd");
        }
        if ft.is_file() {
            if mode & 0o4000 != 0 {
                return self.get("su");
            }
            if mode & 0o2000 != 0 {
                return self.get("sg");
            }
            if meta.nlink() > 1 {
                if let Some(s) = self.get("mh") {
                    return Some(s);
                }
            }
            if meta.permissions().mode() & 0o111 != 0 {
                return self.get("ex");
            }
            let name = path
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_default();
            let lname = name.to_lowercase();
            for (suffix, style) in &self.suffixes {
                if lname.ends_with(&suffix.to_lowercase()) {
                    return Some(style.clone());
                }
            }
            return self.get("fi");
        }
        None
    }
}
