//! Rendering of the application state with ratatui.

use crate::app::{App, LogLevel};
use crate::config::{
    Border, BorderType, Constraint as XConstraint, CustomPanel, HelpMenuLine, Layout,
    LayoutOptions, PanelUiConfig, Style as XStyle, UiElement,
};
use crate::lscolors::LsColors;
use crate::lua::Runtime;
