use crate::path_util::{self, RelativityConfig};
use crate::shell;
use ratatui::layout::{Constraint, Direction, Layout as TuiLayout, Rect};
use ratatui::style::{Modifier, Style};
use ratatui::text::{Line, Span, Text};
use ratatui::widgets::{Block, BorderType as TuiBorderType, Borders, Cell, List, ListItem, Paragraph, Row, Table};
use ratatui::Frame;
use serde::{Deserialize, Serialize};
