use time::OffsetDateTime;

pub struct RenderCtx<'a> {
    pub app: &'a mut App,
    pub lua: Option<&'a Runtime>,
    pub lscolors: &'a LsColors,
}

// ---------------------------------------------------------------- time helpers

pub fn local_offset() -> time::UtcOffset {
    unsafe {
        let now = libc::time(std::ptr::null_mut());
        let mut tm: libc::tm = std::mem::zeroed();
        if libc::localtime_r(&now, &mut tm).is_null() {
            return time::UtcOffset::UTC;
        }
        time::UtcOffset::from_whole_seconds(tm.tm_gmtoff as i32).unwrap_or(time::UtcOffset::UTC)
    }
}

pub fn now_local() -> OffsetDateTime {
    OffsetDateTime::now_utc().to_offset(local_offset())
}

pub fn format_datetime_full(dt: &OffsetDateTime) -> String {
    format!("{}", dt)
}

pub fn format_hms(dt: &OffsetDateTime) -> String {
    format!("{:02}:{:02}:{:02}", dt.hour(), dt.minute(), dt.second())
}

/// `asctime`-like formatting of a unix timestamp in local time.
pub fn format_timestamp(nanos: u128) -> String {
    let secs = (nanos / 1_000_000_000) as libc::time_t;
    unsafe {
        let mut tm: libc::tm = std::mem::zeroed();
        if libc::localtime_r(&secs, &mut tm).is_null() {
            return String::new();
        }
        let mut buf = [0u8; 64];
        let fmt = b"%a %b %d %H:%M:%S %Y\0";
        let n = libc::strftime(
            buf.as_mut_ptr() as *mut libc::c_char,
            buf.len(),
            fmt.as_ptr() as *const libc::c_char,
            &tm,
        );
        String::from_utf8_lossy(&buf[..n]).to_string()
    }
}

// ---------------------------------------------------------------- blocks

fn borders_of(set: &Option<indexmap::IndexSet<Border>>) -> Borders {
    match set {
        None => Borders::NONE,
        Some(s) => {
            let mut b = Borders::NONE;
            for x in s {
                b |= match x {
                    Border::Top => Borders::TOP,
                    Border::Right => Borders::RIGHT,
                    Border::Bottom => Borders::BOTTOM,
                    Border::Left => Borders::LEFT,
                };
            }
            b
        }
    }
}

fn border_type_of(t: Option<BorderType>) -> TuiBorderType {
    match t {
        Some(BorderType::Plain) | None => TuiBorderType::Plain,
        Some(BorderType::Rounded) => TuiBorderType::Rounded,
        Some(BorderType::Double) => TuiBorderType::Double,
        Some(BorderType::Thick) => TuiBorderType::Thick,
    }
}

fn block<'a>(config: &PanelUiConfig, default_title: String) -> Block<'a> {
    let title = config.title.format.clone().unwrap_or(default_title);
    let mut b = Block::default()
        .borders(borders_of(&config.borders))
        .border_type(border_type_of(config.border_type))
        .border_style(Style::from(config.border_style.clone()))
        .style(Style::from(config.style.clone()));
    if !title.is_empty() {
        b = b.title(Span::styled(title, Style::from(config.title.style.clone())));
    }
    b
}

fn panel_config(app: &App, specific: &PanelUiConfig) -> PanelUiConfig {
    app.config
        .general
        .panel_ui
        .default
        .clone()
        .extend(specific)
}

// ---------------------------------------------------------------- layout

fn tui_constraints(
    constraints: &Option<Vec<XConstraint>>,
    screen: Rect,
    layout: Rect,
) -> Vec<Constraint> {
    constraints
        .as_ref()
        .map(|cs| cs.iter().map(|c| c.to_tui(screen, layout)).collect())
        .unwrap_or_default()
}

fn split(direction: Direction, options: &LayoutOptions, screen: Rect, area: Rect) -> Vec<Rect> {
    let mut l = TuiLayout::default()
        .direction(direction)
        .constraints(tui_constraints(&options.constraints, screen, area));
    if let Some(m) = options.margin {
        l = l.margin(m);
    }
    if let Some(m) = options.horizontal_margin {
        l = l.horizontal_margin(m);
    }
    if let Some(m) = options.vertical_margin {
        l = l.vertical_margin(m);
    }
    l.split(area).to_vec()
}

pub fn draw(f: &mut Frame, ctx: &mut RenderCtx) {
    let screen = f.area();
    let layout = ctx
        .app
        .mode
        .layout
        .clone()
        .unwrap_or_else(|| ctx.app.layout.clone());
    draw_layout(f, ctx, &layout, screen, screen);
}

fn draw_layout(f: &mut Frame, ctx: &mut RenderCtx, layout: &Layout, screen: Rect, area: Rect) {
    match layout {
        Layout::Nothing => draw_nothing(f, ctx, area),
        Layout::Table => draw_table(f, ctx, screen, area),
        Layout::SortAndFilter => draw_sort_and_filter(f, ctx, area),
        Layout::HelpMenu => draw_help_menu(f, ctx, area),
        Layout::Selection => draw_selection(f, ctx, area),
        Layout::InputAndLogs => draw_input_and_logs(f, ctx, area),
        Layout::Static(panel) => draw_custom_panel(f, ctx, panel, screen, area),
        Layout::Dynamic(func) => {
            let panel = ctx
                .lua
                .and_then(|lua| lua.render_dynamic(func, ctx.app, screen, area).ok());
            match panel {
                Some(p) => draw_custom_panel(f, ctx, &p, screen, area),
                None => draw_nothing(f, ctx, area),
            }
        }
        Layout::Horizontal { config, splits } => {
            let rects = split(Direction::Horizontal, config, screen, area);
            for (l, r) in splits.iter().zip(rects.into_iter()) {
                draw_layout(f, ctx, l, screen, r);
            }
        }
        Layout::Vertical { config, splits } => {
            let rects = split(Direction::Vertical, config, screen, area);
            for (l, r) in splits.iter().zip(rects.into_iter()) {
                draw_layout(f, ctx, l, screen, r);
            }
        }
        Layout::CustomContent { title, body } => {
            let panel = crate::config::CustomPanel::from_legacy(title.clone(), body.clone(), ctx, screen, area);
            draw_custom_panel(f, ctx, &panel, screen, area);
        }
    }
}

fn draw_nothing(f: &mut Frame, ctx: &mut RenderCtx, area: Rect) {
    let cfg = panel_config(ctx.app, &PanelUiConfig::default());
    let b = block(&cfg, String::new());
    f.render_widget(b, area);
}

// ---------------------------------------------------------------- table

fn node_type_style_and_meta(
    app: &App,
    node: &Node,
) -> (XStyle, std::collections::HashMap<String, String>) {
    let nt = &app.config.node_types;
    let mut cfg = if node.is_symlink {
        nt.symlink.clone()
    } else if node.is_dir {
        nt.directory.clone()
    } else {
        nt.file.clone()
    };
    let mime = node.mime_essence.clone();
    if let Some((t, sub)) = mime.split_once('/') {
        if let Some(m) = nt.mime_essence.get(t) {
            if let Some(c) = m.get("*") {
                cfg = cfg.extend(c);
            }
            if let Some(c) = m.get(sub) {
                cfg = cfg.extend(c);
            }
        }
    }
    if let Some(c) = nt.extension.get(&node.extension) {
        cfg = cfg.extend(c);
    }
    if let Some(c) = nt.special.get(&node.relative_path) {
        cfg = cfg.extend(c);
    }
    (cfg.style, cfg.meta)
}

pub struct RowInfo<'a> {
    pub node: &'a Node,
    pub index: usize,
    pub relative_index: usize,
    pub is_before_focus: bool,
    pub is_after_focus: bool,
    pub tree: String,
    pub prefix: String,
    pub suffix: String,
    pub is_selected: bool,
    pub is_focused: bool,
    pub total: usize,
    pub style: XStyle,
    pub meta: std::collections::HashMap<String, String>,
}

fn format_col_0(r: &RowInfo) -> Vec<Span<'static>> {
    let sign = if r.is_before_focus { "-" } else { " " };
    vec![Span::raw(format!(
        " {}{}│{}",
        sign, r.relative_index, r.index
    ))]
}

fn format_col_1(ctx: &RenderCtx, r: &RowInfo) -> Vec<Span<'static>> {
    let node = r.node;
    let icon = r.meta.get("icon").cloned().unwrap_or_default();
    let mut name = node.relative_path.clone();
    if node.is_dir {
        name.push('/');
    }
    let name = shell::escape(&name);
    let ls_style = ctx
        .lscolors
        .style_for_path(Path::new(&node.absolute_path))
        .unwrap_or_default();
    let style = ls_style.extend(&r.style);

    let mut spans: Vec<Span<'static>> = Vec::new();
    spans.push(Span::raw(format!("{}{}{} ", r.tree, r.prefix, icon)));
    spans.push(Span::styled(name, Style::from(style)));
    spans.push(Span::raw(r.suffix.clone()));
    if node.is_symlink {
        if node.is_broken {
            spans.push(Span::raw(" -> ×".to_string()));
        } else if let Some(s) = &node.symlink {
            let mut target = path_util::shorten(
                &s.absolute_path,
                &RelativityConfig {
                    base: Some(ctx.app.pwd.clone()),
                    with_prefix_dots: false,
                    without_suffix_dots: false,
                },
            )
            .unwrap_or_else(|_| s.absolute_path.clone());
            if s.is_dir {
                target.push('/');
            }
            spans.push(Span::raw(format!(" -> {}", target)));
        }
    }
    spans
}

fn format_col_2(r: &RowInfo) -> Vec<Span<'static>> {
    let rwx = r.node.permissions.rwx();
    rwx.chars()
        .map(|c| {
            let style = match c {
                'r' => Style::default().fg(ratatui::style::Color::Green),
                'w' => Style::default().fg(ratatui::style::Color::Yellow),
                'x' | 's' | 'S' | 't' | 'T' => Style::default().fg(ratatui::style::Color::Red),
                _ => Style::default(),
            };
            Span::styled(c.to_string(), style)
        })
        .collect()
}

fn format_col_3(r: &RowInfo) -> Vec<Span<'static>> {
    if r.node.is_dir {
        vec![Span::raw(String::new())]
    } else {
        vec![Span::raw(r.node.human_size.clone())]
    }
}

fn format_col_4(r: &RowInfo) -> Vec<Span<'static>> {
    let s = r
        .node
        .last_modified
        .map(format_timestamp)
        .unwrap_or_default();
    vec![Span::raw(s)]
}

fn render_col(ctx: &RenderCtx, func: &str, r: &RowInfo) -> Vec<Span<'static>> {
    match func {
        "builtin.fmt_general_table_row_cols_0" => format_col_0(r),
        "builtin.fmt_general_table_row_cols_1" => format_col_1(ctx, r),
        "builtin.fmt_general_table_row_cols_2" => format_col_2(r),
        "builtin.fmt_general_table_row_cols_3" => format_col_3(r),
        "builtin.fmt_general_table_row_cols_4" => format_col_4(r),
        other => match ctx.lua {
            Some(lua) => match lua.render_column(other, r, ctx.app) {
                Ok(s) => crate::ansi::parse_spans(&s),
                Err(e) => vec![Span::raw(format!("{}", e))],
            },
            None => vec![Span::raw(String::new())],
        },
    }
}

pub fn table_title(app: &App) -> String {
    let total = app
        .directory_buffer
        .as_ref()
        .map(|d| d.total)
        .unwrap_or(0);
    let pwd = match &app.vroot {
        Some(vroot) => {
            let rel = app
                .pwd
                .strip_prefix(vroot.as_str())
                .unwrap_or(&app.pwd)
                .trim_start_matches('/');
            format!("vroot:/{}", shell::escape(rel))
        }
        None => {
            let rel = app.pwd.trim_start_matches('/');
            format!("/{}", shell::escape(rel))
        }
    };
    if total == 0 {
        format!(" {} ", pwd)
    } else {
        format!(" {} ({}) ", pwd, total)
    }
}

fn draw_table(f: &mut Frame, ctx: &mut RenderCtx, screen: Rect, area: Rect) {
    let cfg = panel_config(ctx.app, &ctx.app.config.general.panel_ui.table);
    let title = table_title(ctx.app);
    let b = block(&cfg, title);
    let inner = b.inner(area);
    let table_cfg = ctx.app.config.general.table.clone();
    let header_height = table_cfg.header.height.unwrap_or(1);
    let height = inner.height.saturating_sub(header_height) as usize;
    ctx.app.last_table_height = height;

    let widths: Vec<Constraint> = tui_constraints(&table_cfg.col_widths, screen, inner);
    let col_spacing = table_cfg.col_spacing.unwrap_or(1);

    let (rows, _total) = {
        let app: &App = ctx.app;
        match &app.directory_buffer {
            Some(dir) => {
                let total = dir.total;
                let focus = dir.focus;
                let start = compute_scroll_top(ctx.app, total, focus, height);
                let end = (start + height).min(total);
                let mut rows: Vec<Row> = Vec::new();
                let tree = table_cfg.tree.clone();
                let formats: Vec<String> = table_cfg
                    .row
                    .cols
                    .clone()
                    .unwrap_or_default()
                    .iter()
                    .map(|c| c.format.clone().unwrap_or_default())
                    .collect();
                let col_styles: Vec<Style> = table_cfg
                    .row
                    .cols
                    .clone()
                    .unwrap_or_default()
                    .iter()
                    .map(|c| Style::from(c.style.clone()))
                    .collect();
                for (index, node) in dir.nodes.iter().enumerate().take(end).skip(start) {
                    let is_focused = index == focus;
                    let is_selected = ctx.app.selection.contains(node);
                    let ui = if is_focused && is_selected {
                        &ctx.app.config.general.focus_selection_ui
                    } else if is_focused {
                        &ctx.app.config.general.focus_ui
                    } else if is_selected {
                        &ctx.app.config.general.selection_ui
                    } else {
                        &ctx.app.config.general.default_ui
                    };
                    let (nt_style, meta) = node_type_style_and_meta(ctx.app, node);
                    let style = nt_style.extend(&ui.style);
                    let tree_str = match &tree {
                        Some((first, mid, last)) => {
                            if index == total.saturating_sub(1) {
                                last.format.clone().unwrap_or_default()
                            } else if index == 0 {
                                first.format.clone().unwrap_or_default()
                            } else {
                                mid.format.clone().unwrap_or_default()
                            }
                        }
                        None => String::new(),
                    };
                    let info = RowInfo {
                        node,
                        index,
                        relative_index: if index > focus { index - focus } else { focus - index },
                        is_before_focus: index < focus,
                        is_after_focus: index > focus,
                        tree: tree_str,
                        prefix: ui.prefix.clone().unwrap_or_default(),
                        suffix: ui.suffix.clone().unwrap_or_default(),
                        is_selected,
                        is_focused,
                        total,
                        style,
                        meta,
                    };
                    let cells: Vec<Cell> = formats
                        .iter()
                        .zip(col_styles.iter())
                        .map(|(fmt, st)| {
                            let spans = render_col(ctx, fmt, &info);
                            Cell::from(Line::from(spans)).style(*st)
                        })
                        .collect();
                    let mut row = Row::new(cells).style(Style::from(table_cfg.row.style.clone()));
                    if let Some(h) = table_cfg.row.height {
                        if h > 0 {
                            row = row.height(h);
                        }
                    }
                    rows.push(row);
                }
                (rows, total)
            }
            None => (vec![], 0),
        }
    };

    let header_cells: Vec<Cell> = table_cfg
        .header
        .cols
        .clone()
        .unwrap_or_default()
        .into_iter()
        .map(|c| Cell::from(c.format.unwrap_or_default()).style(Style::from(c.style)))
        .collect();
    let header = Row::new(header_cells)
        .style(Style::from(table_cfg.header.style.clone()))
        .height(header_height);

    let table = Table::new(rows, widths)
        .header(header)
        .column_spacing(col_spacing)
        .style(Style::from(table_cfg.style.clone()))
        .block(b);
    f.render_widget(table, area);
}

fn compute_scroll_top(app: &mut App, total: usize, focus: usize, height: usize) -> usize {
    if height == 0 || total == 0 {
        app.scroll_top = 0;
        return 0;
    }
    let max_start = total.saturating_sub(height);
    let start = if app.config.general.paginated_scrolling {
        (focus / height) * height
    } else {
        let padding = (app.config.general.scroll_padding as usize).min(height / 2);
        let mut start = app.scroll_top.min(max_start);
        if focus + padding >= start + height {
            start = (focus + padding).saturating_sub(height);
        }
        if focus < start + padding.saturating_sub(1) {
            start = focus.saturating_sub(padding.saturating_sub(1));
        }
        if focus < start {
            start = focus;
        }
        start.min(max_start)
    };
    app.scroll_top = start;
    start
}

// ---------------------------------------------------------------- sort & filter

fn ui_element_span(el: &UiElement, text: Option<String>) -> Span<'static> {
    Span::styled(
        text.or_else(|| el.format.clone()).unwrap_or_default(),
        Style::from(el.style.clone()),
    )
}

fn draw_sort_and_filter(f: &mut Frame, ctx: &mut RenderCtx, area: Rect) {
    let app: &App = ctx.app;
    let cfg = panel_config(app, &app.config.general.panel_ui.sort_and_filter);
    let ec = &app.explorer_config;
    let count = ec.filters.len() + ec.sorters.len();
    let title = if count == 0 {
        " Sort & filter ".to_string()
    } else {
        format!(" Sort & filter ({}) ", count)
    };
    let b = block(&cfg, title);
    let ui = &app.config.general.sort_and_filter_ui;
    let sep = ui_element_span(&ui.separator, None);

    let mut items: Vec<Vec<Span<'static>>> = Vec::new();
    for fl in &ec.filters {
        let el = ui
            .filter_identifiers
            .get(&fl.filter)
            .cloned()
            .unwrap_or_else(|| ui.default_identifier.clone());
        let fmt = el.format.clone().unwrap_or_default();
        items.push(vec![Span::styled(
            format!("{}{}", fmt, fl.input),
            Style::from(el.style.clone()),
        )]);
    }
    let mut show_sorters = true;
    if let Some(s) = &ec.searcher {
        let el = ui
            .search_identifiers
            .get(&s.algorithm)
            .cloned()
            .unwrap_or_else(|| ui.default_identifier.clone());
        let fmt = el.format.clone().unwrap_or_default();
        let dir = if s.unordered {
            ui.search_direction_identifiers.unordered.clone()
        } else {
            ui.search_direction_identifiers.ordered.clone()
        };
        items.push(vec![
            Span::styled(format!("{}{}", fmt, s.pattern), Style::from(el.style.clone())),
            Span::styled(dir.format.clone().unwrap_or_default(), Style::from(dir.style.clone())),
        ]);
        show_sorters = s.unordered;
    }
    if show_sorters {
        for so in &ec.sorters {
            let el = ui
                .sorter_identifiers
                .get(&so.sorter)
                .cloned()
                .unwrap_or_else(|| ui.default_identifier.clone());
            let dir = if so.reverse {
                ui.sort_direction_identifiers.reverse.clone()
            } else {
                ui.sort_direction_identifiers.forward.clone()
            };
            items.push(vec![
                ui_element_span(&el, None),
                ui_element_span(&dir, None),
            ]);
        }
    }
    let mut spans: Vec<Span<'static>> = Vec::new();
    for (i, item) in items.into_iter().enumerate() {
        if i > 0 {
            spans.push(sep.clone());
        }
        spans.extend(item);
    }
    let p = Paragraph::new(Line::from(spans)).block(b);
    f.render_widget(p, area);
}

// ---------------------------------------------------------------- selection

pub fn selection_item_text(app: &App, node: &Node) -> String {
    let mut s = path_util::shorten(
        &node.absolute_path,
        &RelativityConfig {
            base: Some(app.pwd.clone()),
            with_prefix_dots: true,
            without_suffix_dots: true,
        },
    )
    .unwrap_or_else(|_| node.absolute_path.clone());
    if node.is_dir {
        s.push('/');
    }
    s
}

fn draw_selection(f: &mut Frame, ctx: &mut RenderCtx, area: Rect) {
    let app: &App = ctx.app;
    let cfg = panel_config(app, &app.config.general.panel_ui.selection);
    let count = app.selection.len();
    let title = if count == 0 {
        " Selection ".to_string()
    } else {
        format!(" Selection ({}) ", count)
    };
    let b = block(&cfg, title);
    let item_cfg = &app.config.general.selection.item;
    let fmt = item_cfg.format.clone().unwrap_or_default();
    let items: Vec<ListItem> = app
        .selection
        .iter()
        .map(|n| {
            let spans = if fmt == "builtin.fmt_general_selection_item" || fmt.is_empty() {
                vec![Span::raw(selection_item_text(app, n))]
            } else {
                match ctx.lua {
                    Some(lua) => match lua.render_selection_item(&fmt, n, app) {
                        Ok(s) => crate::ansi::parse_spans(&s),
                        Err(e) => vec![Span::raw(e.to_string())],
                    },
                    None => vec![Span::raw(selection_item_text(app, n))],
                }
            };
            ListItem::new(Line::from(spans)).style(Style::from(item_cfg.style.clone()))
        })
        .collect();
    let list = List::new(items).block(b);
    f.render_widget(list, area);
}

// ---------------------------------------------------------------- help menu

fn draw_help_menu(f: &mut Frame, ctx: &mut RenderCtx, area: Rect) {
    let app: &App = ctx.app;
    let cfg = panel_config(app, &app.config.general.panel_ui.help_menu);
    let title = format!(" Help [{}] ", app.mode.name);
    let b = block(&cfg, title);
    let lines = app
        .mode
        .help_menu(app.config.general.hide_remaps_in_help_menu);
    let rows: Vec<Row> = lines
        .into_iter()
        .map(|l| match l {
            HelpMenuLine::KeyMap(k, remaps, h) => {
                Row::new(vec![Cell::from(k), Cell::from(remaps.join("|")), Cell::from(h)])
            }
            HelpMenuLine::Paragraph(p) => Row::new(vec![Cell::from(p)]),
        })
        .collect();
    let widths = [
        Constraint::Percentage(20),
        Constraint::Percentage(20),
        Constraint::Percentage(60),
    ];
    let table = Table::new(rows, widths).column_spacing(1).block(b);
    f.render_widget(table, area);
}

// ---------------------------------------------------------------- input & logs

fn draw_input_and_logs(f: &mut Frame, ctx: &mut RenderCtx, area: Rect) {
    let app: &App = ctx.app;
    let cfg = panel_config(app, &app.config.general.panel_ui.input_and_logs);
    if let Some(buf) = &app.input.buffer {
        let title = format!(" Input [{}] ", app.mode.name);
        let b = block(&cfg, title);
        let inner = b.inner(area);
        let prompt = app.input.prompt.clone();
        let value = buf.value();
        let spans = vec![
            Span::styled(prompt.clone(), Style::from(app.config.general.prompt.style.clone())),
            Span::raw(value.clone()),
        ];
        let p = Paragraph::new(Line::from(spans)).block(b);
        f.render_widget(p, area);
        // cursor
        let prompt_w = unicode_width::UnicodeWidthStr::width(prompt.as_str()) as u16;
        let before: String = value.chars().take(buf.cursor()).collect();
        let cursor_w = unicode_width::UnicodeWidthStr::width(before.as_str()) as u16;
        if inner.width > 0 && inner.height > 0 {
            let x = (inner.x + prompt_w + cursor_w).min(inner.x + inner.width.saturating_sub(1));
            f.set_cursor_position((x, inner.y));
        }
    } else {
        let count = app.logs.len();
        let title = if count == 0 {
            format!(" Logs [{}] ", app.mode.name)
        } else {
            format!(" Logs ({}) [{}] ", count, app.mode.name)
        };
        let b = block(&cfg, title);
        let inner = b.inner(area);
        let lines: Vec<Line> = if app.logs_hidden {
            vec![]
        } else {
            app.logs
                .iter()
                .rev()
                .take(inner.height as usize)
                .map(|l| {
                    let el = match l.level {
                        LogLevel::Info => &app.config.general.logs.info,
                        LogLevel::Success => &app.config.general.logs.success,
                        LogLevel::Warning => &app.config.general.logs.warning,
                        LogLevel::Error => &app.config.general.logs.error,
                    };
                    let text = format!(
                        "{}|{}) {}",
                        format_hms(&l.created_at),
                        el.format.clone().unwrap_or_default(),
                        l.message
                    );
                    Line::from(Span::styled(text, Style::from(el.style.clone())))
                })
                .collect()
        };
        let p = Paragraph::new(Text::from(lines)).block(b);
        f.render_widget(p, area);
    }
}

// ---------------------------------------------------------------- custom panels

fn draw_custom_panel(
    f: &mut Frame,
    ctx: &mut RenderCtx,
    panel: &CustomPanel,
    screen: Rect,
    area: Rect,
) {
    match panel {
        CustomPanel::CustomParagraph(p) => {
            let cfg = panel_config(ctx.app, &p.ui.clone().unwrap_or_default());
            let b = block(&cfg, String::new());
            let text: Text = crate::ansi::parse_text(&p.body);
            let w = Paragraph::new(text).block(b);
            f.render_widget(w, area);
        }
        CustomPanel::CustomList(l) => {
            let cfg = panel_config(ctx.app, &l.ui.clone().unwrap_or_default());
            let b = block(&cfg, String::new());
            let items: Vec<ListItem> = l
                .body
                .iter()
                .map(|s| ListItem::new(Line::from(crate::ansi::parse_spans(s))))
                .collect();
            f.render_widget(List::new(items).block(b), area);
        }
        CustomPanel::CustomTable(t) => {
            let cfg = panel_config(ctx.app, &t.ui.clone().unwrap_or_default());
            let b = block(&cfg, String::new());
            let inner = b.inner(area);
            let widths = tui_constraints(&Some(t.widths.clone()), screen, inner);
            let rows: Vec<Row> = t
                .body
                .iter()
                .map(|r| {
                    Row::new(
                        r.iter()
                            .map(|c| Cell::from(Line::from(crate::ansi::parse_spans(c))))
                            .collect::<Vec<Cell>>(),
                    )
                })
                .collect();
            let table = Table::new(rows, widths)
                .column_spacing(t.col_spacing.unwrap_or(1))
                .block(b);
            f.render_widget(table, area);
        }
        CustomPanel::CustomLayout(l) => {
            draw_layout(f, ctx, l, screen, area);
        }
    }
}

/// Serializable size information for dynamic renderers.
#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
pub struct Size {
    pub x: u16,
    pub y: u16,
    pub height: u16,
    pub width: u16,
}

impl From<Rect> for Size {
    fn from(r: Rect) -> Self {
        Size {
            x: r.x,
            y: r.y,
            height: r.height,
            width: r.width,
        }
    }
}

pub fn bold() -> Modifier {
    Modifier::BOLD
}
