use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span, Text};

fn apply_sgr(style: Style, params: &[u16]) -> Style {
    let mut style = style;
    let mut i = 0;
    if params.is_empty() {
        return Style::default();
    }
    while i < params.len() {
        let p = params[i];
        match p {
            0 => style = Style::default(),
            1 => style = style.add_modifier(Modifier::BOLD),
            2 => style = style.add_modifier(Modifier::DIM),
            3 => style = style.add_modifier(Modifier::ITALIC),
            4 => style = style.add_modifier(Modifier::UNDERLINED),
            5 => style = style.add_modifier(Modifier::SLOW_BLINK),
            6 => style = style.add_modifier(Modifier::RAPID_BLINK),
            7 => style = style.add_modifier(Modifier::REVERSED),
            8 => style = style.add_modifier(Modifier::HIDDEN),
            9 => style = style.add_modifier(Modifier::CROSSED_OUT),
            22 => style = style.remove_modifier(Modifier::BOLD | Modifier::DIM),
            23 => style = style.remove_modifier(Modifier::ITALIC),
            24 => style = style.remove_modifier(Modifier::UNDERLINED),
            25 => style = style.remove_modifier(Modifier::SLOW_BLINK | Modifier::RAPID_BLINK),
            27 => style = style.remove_modifier(Modifier::REVERSED),
            28 => style = style.remove_modifier(Modifier::HIDDEN),
            29 => style = style.remove_modifier(Modifier::CROSSED_OUT),
            30..=37 => style = style.fg(basic_color(p - 30, false)),
            90..=97 => style = style.fg(basic_color(p - 90, true)),
            40..=47 => style = style.bg(basic_color(p - 40, false)),
            100..=107 => style = style.bg(basic_color(p - 100, true)),
            39 => style = style.fg(Color::Reset),
            49 => style = style.bg(Color::Reset),
            38 | 48 => {
                let is_fg = p == 38;
                if i + 1 < params.len() {
                    match params[i + 1] {
                        5 if i + 2 < params.len() => {
                            let c = Color::Indexed(params[i + 2] as u8);
                            style = if is_fg { style.fg(c) } else { style.bg(c) };
                            i += 2;
                        }
                        2 if i + 4 < params.len() => {
                            let c = Color::Rgb(
                                params[i + 2] as u8,
                                params[i + 3] as u8,
                                params[i + 4] as u8,
                            );
                            style = if is_fg { style.fg(c) } else { style.bg(c) };
                            i += 4;
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
        i += 1;
    }
    style
}

fn basic_color(n: u16, bright: bool) -> Color {
    match (n, bright) {
        (0, false) => Color::Black,
        (1, false) => Color::Red,
        (2, false) => Color::Green,
        (3, false) => Color::Yellow,
        (4, false) => Color::Blue,
        (5, false) => Color::Magenta,
        (6, false) => Color::Cyan,
        (7, false) => Color::Gray,
        (0, true) => Color::DarkGray,
        (1, true) => Color::LightRed,
        (2, true) => Color::LightGreen,
        (3, true) => Color::LightYellow,
        (4, true) => Color::LightBlue,
        (5, true) => Color::LightMagenta,
        (6, true) => Color::LightCyan,
        _ => Color::White,
    }
}

/// Parse a single line (no newlines) into spans.
pub fn parse_spans(s: &str) -> Vec<Span<'static>> {
    let mut spans = Vec::new();
    let mut style = Style::default();
    let mut buf = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\x1b' && i + 1 < chars.len() && chars[i + 1] == '[' {
            // find terminator
            let mut j = i + 2;
            let mut params = String::new();
            while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == ';') {
                params.push(chars[j]);
                j += 1;
            }
            if j < chars.len() && chars[j] == 'm' {
                if !buf.is_empty() {
                    spans.push(Span::styled(std::mem::take(&mut buf), style));
                }
                let nums: Vec<u16> = params
                    .split(';')
                    .filter(|p| !p.is_empty())
                    .filter_map(|p| p.parse().ok())
                    .collect();
                style = apply_sgr(style, &nums);
                i = j + 1;
                continue;
            } else if j < chars.len() {
                // unknown CSI: skip it
                i = j + 1;
                continue;
            }
        }
        buf.push(c);
        i += 1;
    }
    if !buf.is_empty() || spans.is_empty() {
        spans.push(Span::styled(buf, style));
    }
    spans
}

pub fn parse_text(s: &str) -> Text<'static> {
    let mut lines = Vec::new();
    // Keep style across lines.
    let mut carry = Style::default();
    for raw in s.split('\n') {
        let mut spans = parse_spans(raw);
        if let Some(first) = spans.first_mut() {
            if first.style == Style::default() {
                first.style = carry;
            }
        }
        if let Some(last) = spans.last() {
            carry = last.style;
        }
        lines.push(Line::from(spans));
    }
    Text::from(lines)
}
