//! Safe message templating: render a YAML template with `%s`/`%q` style
//! placeholders into compact JSON.

use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
pub struct JfError(pub String);

impl fmt::Display for JfError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "xplr -m: {}", self.0)
    }
}

impl std::error::Error for JfError {}

type JfResult<T> = Result<T, JfError>;

fn quote(s: &str) -> String {
    serde_json::to_string(s).unwrap_or_else(|_| format!("\"{}\"", s))
}

struct Values<'a> {
    all: &'a [String],
    next: usize,
    named: Option<HashMap<String, String>>,
}

impl<'a> Values<'a> {
    fn next_positional(&mut self) -> Option<&'a String> {
        let v = self.all.get(self.next);
        if v.is_some() {
            self.next += 1;
        }
        v
    }

    fn rest_positional(&mut self) -> Vec<&'a String> {
        let v: Vec<&String> = self.all[self.next.min(self.all.len())..].iter().collect();
        self.next = self.all.len();
        v
    }

    fn named(&mut self) -> JfResult<&HashMap<String, String>> {
        if self.named.is_none() {
            let mut map = HashMap::new();
            let start = self.next;
            for (i, v) in self.all[start.min(self.all.len())..].iter().enumerate() {
                let no = start + i + 1;
                if let Some((k, val)) = v.split_once('=') {
                    map.entry(k.to_string()).or_insert_with(|| val.to_string());
                } else if let Some((k, file)) = v.split_once('@') {
                    let content = std::fs::read_to_string(file)
                        .map_err(|e| JfError(format!("io: {}", e)))?;
                    map.entry(k.to_string()).or_insert(content);
                } else {
                    return Err(JfError(format!(
                        "invalid syntax for value no. {}, use 'NAME=VALUE' or 'NAME@FILE' syntax",
                        no
                    )));
                }
            }
            self.next = self.all.len();
            self.named = Some(map);
        }
        Ok(self.named.as_ref().unwrap())
    }

    fn has_remaining(&self) -> bool {
        self.named.is_none() && self.next < self.all.len()
    }
}

/// Render the template into a YAML string.
pub fn render(template: &str, args: &[String]) -> JfResult<String> {
    let chars: Vec<char> = template.chars().collect();
    let mut out = String::new();
    let mut values = Values {
        all: args,
        next: 0,
        named: None,
    };
    let mut used_named = false;
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c != '%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= chars.len() {
            return Err(JfError(
                "template ended with incomplete placeholder".to_string(),
            ));
        }
        let col = i;
        match chars[i] {
            '%' => {
                out.push('%');
                i += 1;
            }
            's' | 'q' => {
                if used_named {
                    return Err(JfError(format!(
                        "positional placeholder '%{}' at column {} was used after named placeholders, use named placeholder syntax",
                        chars[i], col
                    )));
                }
                let q = chars[i] == 'q';
                match values.next_positional() {
                    Some(v) => {
                        if q {
                            out.push_str(&quote(v));
                        } else {
                            out.push_str(v);
                        }
                    }
                    None => {
                        return Err(JfError(format!(
                            "placeholder missing value at column {}",
                            col
                        )))
                    }
                }
                i += 1;
            }
            '*' => {
                // %*s %*q %**s %**q
                let mut j = i + 1;
                let double = j < chars.len() && chars[j] == '*';
                if double {
                    j += 1;
                }
                if j >= chars.len() {
                    return Err(JfError(
                        "template ended with incomplete placeholder".to_string(),
                    ));
                }
                let kind = chars[j];
                if kind != 's' && kind != 'q' {
                    return Err(JfError(format!(
                        "invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                        chars[i..=j].iter().collect::<String>(),
                        j
                    )));
                }
                if used_named {
                    return Err(JfError(format!(
                        "positional placeholder '%{}' at column {} was used after named placeholders, use named placeholder syntax",
                        kind, j
                    )));
                }
                let q = kind == 'q';
                let rest = values.rest_positional();
                if double {
                    if rest.len() % 2 != 0 {
                        return Err(JfError(format!(
                            "placeholder missing value at column {}",
                            j
                        )));
                    }
                    let pairs: Vec<String> = rest
                        .chunks(2)
                        .map(|p| {
                            if q {
                                format!("{}: {}", quote(p[0]), quote(p[1]))
                            } else {
                                format!("{}: {}", p[0], p[1])
                            }
                        })
                        .collect();
                    out.push_str(&pairs.join(","));
                } else {
                    let items: Vec<String> = rest
                        .iter()
                        .map(|v| if q { quote(v) } else { v.to_string() })
                        .collect();
                    out.push_str(&items.join(","));
                }
                i = j + 1;
            }
            '(' => {
                // named placeholder
                let mut j = i + 1;
                let mut name = String::new();
                let mut default: Option<String> = None;
                while j < chars.len() && chars[j] != ')' {
                    if chars[j] == '=' && default.is_none() {
                        default = Some(String::new());
                    } else if let Some(d) = default.as_mut() {
                        d.push(chars[j]);
                    } else if chars[j].is_alphanumeric() || chars[j] == '_' {
                        name.push(chars[j]);
                    } else {
                        return Err(JfError(format!(
                            "invalid character '{}' in placeholder name at column {}, use numbers, letters and underscores only",
                            chars[j], j
                        )));
                    }
                    j += 1;
                }
                if j >= chars.len() {
                    return Err(JfError(
                        "template ended with incomplete placeholder".to_string(),
                    ));
                }
                // chars[j] == ')'
                j += 1;
                if name.is_empty() {
                    return Err(JfError(format!(
                        "placeholder missing name at column {}",
                        j
                    )));
                }
                let mut optional = false;
                if j < chars.len() && chars[j] == '?' {
                    if default.is_some() {
                        return Err(JfError(format!(
                            "optional placeholder '{}' at column {} cannot have a default value",
                            name, j
                        )));
                    }
                    optional = true;
                    j += 1;
                }
                if j >= chars.len() {
                    return Err(JfError(
                        "template ended with incomplete placeholder".to_string(),
                    ));
                }
                let kind = chars[j];
                if kind != 's' && kind != 'q' {
                    return Err(JfError(format!(
                        "invalid named placeholder '%({}){}' at column {}, use '%({})q' for quoted strings and '%({})s' for other values",
                        name, kind, j, name, name
                    )));
                }
                let q = kind == 'q';
                used_named = true;
                let named = values.named()?;
                match named.get(&name) {
                    Some(v) => {
                        if q {
                            out.push_str(&quote(v));
                        } else {
                            out.push_str(v);
                        }
                    }
                    None => {
                        if let Some(d) = default {
                            if q {
                                out.push_str(&quote(&d));
                            } else {
                                out.push_str(&d);
                            }
                        } else if optional {
                            out.push_str("null");
                        } else {
                            return Err(JfError(format!(
                                "no value for placeholder '%({}){}' at column {}",
                                name, kind, j
                            )));
                        }
                    }
                }
                i = j + 1;
            }
            other => {
                return Err(JfError(format!(
                    "invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                    other, col
                )));
            }
        }
    }
    if values.has_remaining() {
        return Err(JfError(
            "too many positional values, not enough positional placeholders".to_string(),
        ));
    }
    Ok(out)
}

fn yaml_to_json(v: serde_yaml::Value) -> serde_json::Value {
    match v {
        serde_yaml::Value::Null => serde_json::Value::Null,
        serde_yaml::Value::Bool(b) => serde_json::Value::Bool(b),
        serde_yaml::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                serde_json::Value::Number(i.into())
            } else if let Some(u) = n.as_u64() {
                serde_json::Value::Number(u.into())
            } else if let Some(f) = n.as_f64() {
                serde_json::Number::from_f64(f)
                    .map(serde_json::Value::Number)
                    .unwrap_or(serde_json::Value::Null)
            } else {
                serde_json::Value::Null
            }
        }
        serde_yaml::Value::String(s) => serde_json::Value::String(s),
        serde_yaml::Value::Sequence(s) => {
            serde_json::Value::Array(s.into_iter().map(yaml_to_json).collect())
        }
        serde_yaml::Value::Mapping(m) => {
            let mut out = serde_json::Map::new();
            for (k, v) in m {
                let key = match k {
                    serde_yaml::Value::String(s) => s,
                    serde_yaml::Value::Null => "null".to_string(),
                    serde_yaml::Value::Bool(b) => b.to_string(),
                    serde_yaml::Value::Number(n) => n.to_string(),
                    other => serde_yaml::to_string(&other)
                        .unwrap_or_default()
                        .trim()
                        .to_string(),
                };
                out.insert(key, yaml_to_json(v));
            }
            serde_json::Value::Object(out)
        }
        serde_yaml::Value::Tagged(t) => yaml_to_json(t.value),
    }
}

/// Render the template and convert the resulting YAML into compact JSON.
pub fn format(template: &str, args: &[String]) -> JfResult<String> {
    let yaml = render(template, args)?;
    let value: serde_yaml::Value =
        serde_yaml::from_str(&yaml).map_err(|e| JfError(format!("yaml: {}", e)))?;
    let json = yaml_to_json(value);
    Ok(serde_json::to_string(&json).unwrap_or_default())
}
EOF
