                        "invalid named placeholder '%({}){}' at column {}, use '%({})q' for quoted strings and '%({})s' for other values",
                        name, kind, j, name, name
                    )));
                }
                let q = kind == 'q';
                used_named = true;
                let named = values.named()?;
                match named.get(&name) {
                    Some(v) => {
                        if q {
                            out.push_str(&quote(v));
                        } else {
                            out.push_str(v);
                        }
                    }
                    None => {
                        if let Some(d) = default {
                            if q {
                                out.push_str(&quote(&d));
                            } else {
                                out.push_str(&d);
                            }
                        } else if optional {
                            out.push_str("null");
                        } else {
                            return Err(JfError(format!(
                                "no value for placeholder '%({}){}' at column {}",
                                name, kind, j
                            )));
                        }
                    }
                }
                i = j + 1;
            }
            other => {
                return Err(JfError(format!(
                    "invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                    other, col
                )));
            }
        }
    }
    if values.has_remaining() {
        return Err(JfError(
            "too many positional values, not enough positional placeholders".to_string(),
        ));
    }
    Ok(out)
}

fn yaml_to_json(v: serde_yaml::Value) -> serde_json::Value {
    match v {
        serde_yaml::Value::Null => serde_json::Value::Null,
        serde_yaml::Value::Bool(b) => serde_json::Value::Bool(b),
        serde_yaml::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                serde_json::Value::Number(i.into())
            } else if let Some(u) = n.as_u64() {
                serde_json::Value::Number(u.into())
            } else if let Some(f) = n.as_f64() {
                serde_json::Number::from_f64(f)
                    .map(serde_json::Value::Number)
                    .unwrap_or(serde_json::Value::Null)
            } else {
                serde_json::Value::Null
            }
        }
        serde_yaml::Value::String(s) => serde_json::Value::String(s),
        serde_yaml::Value::Sequence(s) => {
            serde_json::Value::Array(s.into_iter().map(yaml_to_json).collect())
        }
        serde_yaml::Value::Mapping(m) => {
            let mut out = serde_json::Map::new();
            for (k, v) in m {
                let key = match k {
                    serde_yaml::Value::String(s) => s,
                    serde_yaml::Value::Null => "null".to_string(),
                    serde_yaml::Value::Bool(b) => b.to_string(),
                    serde_yaml::Value::Number(n) => n.to_string(),
                    other => serde_yaml::to_string(&other)
                        .unwrap_or_default()
                        .trim()
                        .to_string(),
                };
                out.insert(key, yaml_to_json(v));
            }
            serde_json::Value::Object(out)
        }
        serde_yaml::Value::Tagged(t) => yaml_to_json(t.value),
    }
}

/// Render the template and convert the resulting YAML into compact JSON.
pub fn format(template: &str, args: &[String]) -> JfResult<String> {
    let yaml = render(template, args)?;
    let value: serde_yaml::Value =
        serde_yaml::from_str(&yaml).map_err(|e| JfError(format!("yaml: {}", e)))?;
    let json = yaml_to_json(value);
    Ok(serde_json::to_string(&json).unwrap_or_default())
}
