//! The main event loop: terminal handling, worker threads, pipes and
//! external command execution.

use crate::app::{App, DirectoryBuffer, InternalMsg, MsgIn, MsgOut, Task};
use crate::cli::Cli;
use crate::config::{Config, Hooks};
use crate::explorer;
use crate::key::Key;
use crate::lscolors::LsColors;
use crate::lua::Runtime;
use crate::msg::{Command, ExternalMsg};
use crate::ui::{self, RenderCtx};
use anyhow::{bail, Result};
use crossterm::event::{
    DisableMouseCapture, EnableMouseCapture, Event, KeyEventKind, MouseEventKind,
};
use crossterm::execute;
use crossterm::terminal::{
    disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen,
};
use ratatui::backend::CrosstermBackend;
use ratatui::Terminal;
use std::collections::VecDeque;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{self, Receiver, Sender};
use std::sync::Arc;
use std::time::Duration;

pub struct Runner {
    pub cli: Cli,
    pub pwd: PathBuf,
    pub focused_path: Option<PathBuf>,
    pub selection: Vec<PathBuf>,
}

impl Runner {
    pub fn from_cli(cli: Cli) -> Result<Self> {
        let mut paths = cli.paths.clone();
        let (pwd, focused_path) = match paths.first().cloned() {
            None => (crate::path_util::pwd()?, None),
            Some(p) => {
                paths.remove(0);
                let is_dir = p.is_dir();
                if is_dir && !cli.force_focus {
                    (p, None)
                } else {
                    let parent = p
                        .parent()
                        .map(|x| x.to_path_buf())
                        .unwrap_or_else(|| PathBuf::from("/"));
                    (parent, Some(p))
                }
            }
        };
        if let Some(vroot) = &cli.vroot {
            if !pwd.starts_with(vroot) {
                bail!(
                    "{:?} is outside of virtual root {:?}",
                    pwd.to_string_lossy(),
                    vroot.to_string_lossy()
                );
            }
        }
        Ok(Runner {
            cli,
            pwd,
            focused_path,
            selection: paths,
        })
    }
}

fn config_file(cli: &Cli) -> Option<PathBuf> {
    if let Some(c) = &cli.config {
        return Some(c.clone());
    }
    let home = std::env::var("HOME").ok().filter(|h| !h.is_empty());
    let xdg = std::env::var("XDG_CONFIG_HOME")
        .ok()
        .filter(|h| !h.is_empty())
        .map(PathBuf::from)
        .or_else(|| home.as_ref().map(|h| PathBuf::from(h).join(".config")));
    if let Some(x) = xdg {
        let p = x.join("xplr").join("init.lua");
        if p.exists() {
            return Some(p);
        }
    }
    let etc = PathBuf::from("/etc/xplr/init.lua");
    if etc.exists() {
        return Some(etc);
    }
    None
}

struct TerminalGuard {
    mouse: bool,
}

impl TerminalGuard {
    fn enter(mouse: bool) -> Result<Self> {
        enable_raw_mode()?;
        let mut out = io::stdout();
        execute!(out, EnterAlternateScreen, crossterm::cursor::Hide)?;
        if mouse {
            execute!(out, EnableMouseCapture)?;
        }
        Ok(TerminalGuard { mouse })
    }

    fn leave(&self) -> Result<()> {
        let mut out = io::stdout();
        execute!(
            out,
            crossterm::terminal::Clear(crossterm::terminal::ClearType::All),
            crossterm::cursor::MoveTo(0, 0),
            LeaveAlternateScreen,
            DisableMouseCapture,
            crossterm::cursor::Show
        )?;
        disable_raw_mode()?;
        Ok(())
    }
}

fn write_pipe(path: &str, content: &str) -> Result<()> {
    fs::write(path, content)?;
    Ok(())
}

fn init_pipes(app: &App) -> Result<()> {
    fs::create_dir_all(&app.pipe.path)?;
    write_pipe(&app.pipe.msg_in, "\n")?;
    write_pipe(&app.pipe.selection_out, "")?;
    write_pipe(&app.pipe.result_out, "")?;
    write_pipe(&app.pipe.directory_nodes_out, "")?;
    write_pipe(&app.pipe.global_help_menu_out, "")?;
    write_pipe(&app.pipe.logs_out, "")?;
    write_pipe(&app.pipe.history_out, "")?;
    Ok(())
}

fn write_pipes(app: &App, delimiter: char) -> Result<()> {
    write_pipe(&app.pipe.msg_in, &delimiter.to_string())?;
    write_pipe(&app.pipe.selection_out, &app.selection_str(delimiter))?;
    write_pipe(&app.pipe.result_out, &app.result_str(delimiter))?;
    write_pipe(
        &app.pipe.directory_nodes_out,
        &app.directory_nodes_str(delimiter),
    )?;
    write_pipe(&app.pipe.global_help_menu_out, &app.global_help_menu_str())?;
    write_pipe(&app.pipe.logs_out, &app.logs_str(delimiter))?;
    write_pipe(&app.pipe.history_out, &app.history_str(delimiter))?;
    Ok(())
}

/// Read and drain messages from the input pipe.
pub fn read_msg_in(path: &str) -> Result<Vec<ExternalMsg>> {
    let content = fs::read(path)?;
    if content.is_empty() {
        return Ok(vec![]);
    }
    let delimiter = content[0];
    if content.len() <= 1 {
        return Ok(vec![]);
    }
    let mut msgs = Vec::new();
    for part in content[1..].split(|b| *b == delimiter) {
        if part.is_empty() {
            continue;
        }
        let s = String::from_utf8_lossy(part);
        match serde_yaml::from_str::<ExternalMsg>(&s) {
            Ok(m) => msgs.push(m),
            Err(e) => msgs.push(ExternalMsg::LogError(e.to_string())),
        }
    }
    fs::write(path, [delimiter])?;
    Ok(msgs)
}

fn spawn_key_reader(tx: Sender<Task>, stop: Arc<AtomicBool>) {
    std::thread::spawn(move || loop {
        if stop.load(Ordering::Relaxed) {
            break;
        }
        match crossterm::event::poll(Duration::from_millis(100)) {
            Ok(true) => match crossterm::event::read() {
                Ok(Event::Key(k)) => {
                    if k.kind == KeyEventKind::Press || k.kind == KeyEventKind::Repeat {
                        let key = Key::from_event(&k);
                        let _ = tx.send(Task::new(
                            MsgIn::Internal(InternalMsg::HandleKey(key)),
                            None,
                        ));
                    }
                }
                Ok(Event::Mouse(m)) => {
                    let msg = match m.kind {
                        MouseEventKind::ScrollUp => Some(ExternalMsg::FocusPrevious),
                        MouseEventKind::ScrollDown => Some(ExternalMsg::FocusNext),
                        _ => None,
                    };
                    if let Some(msg) = msg {
                        let _ = tx.send(Task::new(MsgIn::External(msg), None));
                    }
                }
                Ok(Event::Resize(_, _)) => {
                    let _ = tx.send(Task::new(MsgIn::External(ExternalMsg::Refresh), None));
                }
                _ => {}
            },
            Ok(false) => {}
            Err(_) => break,
        }
    });
}

fn spawn_pipe_reader(tx: Sender<Task>, path: String, stop: Arc<AtomicBool>) {
    std::thread::spawn(move || loop {
        if stop.load(Ordering::Relaxed) {
            break;
        }
        std::thread::sleep(Duration::from_millis(50));
        if let Ok(msgs) = read_msg_in(&path) {
            for m in msgs {
                let _ = tx.send(Task::new(MsgIn::External(m), None));
            }
        }
    });
}

fn explore_async(tx: Sender<Task>, pwd: String, config: explorer::ExplorerConfig, parents: bool) {
    std::thread::spawn(move || {
        match explorer::explore(Path::new(&pwd), &config) {
            Ok(nodes) => {
                let buf = DirectoryBuffer::new(pwd.clone(), nodes, 0);
                let _ = tx.send(Task::new(
                    MsgIn::Internal(InternalMsg::SetDirectory(buf)),
                    None,
                ));
            }
            Err(e) => {
                let _ = tx.send(Task::new(
                    MsgIn::External(ExternalMsg::LogError(format!(
                        "could not explore {:?}: {}",
                        pwd, e
                    ))),
                    None,
                ));
            }
        }
        if parents {
            let mut path = PathBuf::from(&pwd);
            while let Some(parent) = path.parent().map(|p| p.to_path_buf()) {
                let child = path
                    .file_name()
                    .map(|n| n.to_string_lossy().to_string());
                let _ = tx.send(Task::new(
                    MsgIn::Internal(InternalMsg::AddLastFocus(
                        parent.to_string_lossy().to_string(),
                        child,
                    )),
                    None,
                ));
                path = parent;
            }
        }
    });
}

pub struct Fifo {
    path: String,
    file: Option<fs::File>,
}

impl Fifo {
    fn start(path: &str) -> Result<Fifo> {
        let file = fs::OpenOptions::new().write(true).open(path)?;
        Ok(Fifo {
            path: path.to_string(),
            file: Some(file),
        })
    }

    fn write(&mut self, s: &str) {
        if let Some(f) = self.file.as_mut() {
            let _ = writeln!(f, "{}", s);
        }
    }
}

pub fn run(runner: Runner) -> Result<Option<String>> {
    let cli = runner.cli.clone();
    let bin = std::env::current_exe()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|_| "xplr".to_string());

    // ---- config loading
    let mut load_errors: Vec<String> = Vec::new();
    let mut config = Config::builtin();
    let mut hooks = Hooks::default();
    let mut lua = Runtime::new().ok();
    let mut config_files: Vec<PathBuf> = Vec::new();
    if let Some(c) = config_file(&cli) {
        config_files.push(c);
    }
    config_files.extend(cli.extra_config.iter().cloned());
    for file in &config_files {
        match lua.as_mut() {
            Some(rt) => match rt.load_config(file, config.clone()) {
                Ok((c, h)) => {
                    config = c;
                    hooks = hooks.extend(h);
                }
                Err(e) => load_errors.push(e.to_string()),
            },
            None => load_errors.push(format!("could not load {}", file.to_string_lossy())),
        }
    }
    if cli.read_only {
        config.general.read_only = true;
    }

    let mut app = App::create(bin, runner.pwd.clone(), config, hooks, cli.vroot.clone())?;
    app.print_pwd_as_result = cli.print_pwd_as_result;
    let lscolors = LsColors::from_env();

    // ---- initial tasks
    let mut pending: VecDeque<Task> = VecDeque::new();
    let pwd = app.pwd.clone();
    app.change_directory(&pwd, true)?;
    // sync explore so that the first frame is complete
    if let Err(e) = app.explore_pwd() {
        app.log_error(e.to_string());
    }
    // the async explore queued by change_directory is harmless; drop it
    app.msg_out.retain(|m| !matches!(m, MsgOut::ExplorePwdAsync));

    if let Some(fp) = &runner.focused_path {
        pending.push_back(Task::new(
            MsgIn::External(ExternalMsg::FocusPath(fp.to_string_lossy().to_string())),
            None,
        ));
    }
    for s in &runner.selection {
        pending.push_back(Task::new(
            MsgIn::External(ExternalMsg::SelectPath(s.to_string_lossy().to_string())),
            None,
        ));
    }
    pending.push_back(Task::new(
        MsgIn::External(ExternalMsg::ExploreParentsAsync),
        None,
    ));

    let had_errors = !load_errors.is_empty();
    for e in load_errors {
        app.log_error(e);
    }
    if had_errors && !app.config.general.disable_debug_error_mode {
        pending.push_back(Task::new(
            MsgIn::External(ExternalMsg::SwitchModeBuiltin("debug_error".to_string())),
            None,
        ));
    }
    for m in app.hooks.on_load.clone() {
        pending.push_back(Task::new(MsgIn::External(m), None));
    }
    for raw in &cli.on_load {
        match serde_yaml::from_str::<ExternalMsg>(raw) {
            Ok(m) => pending.push_back(Task::new(MsgIn::External(m), None)),
            Err(e) => bail!("{}", e),
        }
    }
    if let Some(fifo) = app.config.general.start_fifo.clone() {
        pending.push_back(Task::new(
            MsgIn::External(ExternalMsg::StartFifo(fifo)),
            None,
        ));
    }

    init_pipes(&app)?;

    // ---- terminal
    let mouse = app.config.general.enable_mouse;
    let guard = TerminalGuard::enter(mouse)?;
    let backend = CrosstermBackend::new(io::stdout());
    let mut terminal = Terminal::new(backend)?;
    terminal.clear()?;

    let (tx, rx): (Sender<Task>, Receiver<Task>) = mpsc::channel();
    let stop = Arc::new(AtomicBool::new(false));
    spawn_key_reader(tx.clone(), stop.clone());
    spawn_pipe_reader(tx.clone(), app.pipe.msg_in.clone(), stop.clone());

    let mut fifo: Option<Fifo> = None;
    let mut mouse_enabled = mouse;
    let mut last_fifo_focus: Option<String> = None;

    let result: Result<Option<String>> = (|| {
        let mut need_draw = true;
        loop {
            // Drain pending tasks before waiting for new events.
            let task = match pending.pop_front() {
                Some(t) => t,
                None => {
                    if need_draw {
                        let mut ctx = RenderCtx {
                            app: &mut app,
                            lua: lua.as_ref(),
                            lscolors: &lscolors,
                        };
                        terminal.draw(|f| ui::draw(f, &mut ctx))?;
                        need_draw = false;
                        // fifo
                        if let Some(fifo) = fifo.as_mut() {
                            let focus = app.focused_node_str();
                            if last_fifo_focus.as_ref() != Some(&focus) {
                                fifo.write(&focus);
                                last_fifo_focus = Some(focus);
                            }
                        }
                    }
                    match rx.recv() {
                        Ok(t) => t,
                        Err(_) => bail!("event channel closed"),
                    }
                }
            };

            app.handle_task(task)?;
            need_draw = true;

            while let Some(out) = app.msg_out.pop_front() {
                match out {
                    MsgOut::Enqueue(t) => pending.push_back(t),
                    MsgOut::Refresh => need_draw = true,
                    MsgOut::ClearScreen => {
                        terminal.clear()?;
                        need_draw = true;
                    }
                    MsgOut::ExplorePwdAsync => {
                        explore_async(
                            tx.clone(),
                            app.pwd.clone(),
                            app.explorer_config.clone(),
                            false,
                        );
                    }
                    MsgOut::ExploreParentsAsync => {
                        explore_async(
                            tx.clone(),
                            app.pwd.clone(),
                            app.explorer_config.clone(),
                            true,
                        );
                    }
                    MsgOut::Quit => return Ok(None),
                    MsgOut::Terminate => bail!("terminated"),
                    MsgOut::PrintPwdAndQuit => {
                        return Ok(Some(format!("{}\n", app.pwd)));
                    }
                    MsgOut::PrintFocusPathAndQuit => {
                        let d = if cli.write0 { '\0' } else { '\n' };
                        let out = app
                            .focused_node()
                            .map(|n| format!("{}{}", n.absolute_path, d))
                            .unwrap_or_default();
                        return Ok(Some(out));
                    }
                    MsgOut::PrintSelectionAndQuit => {
                        let d = if cli.write0 { '\0' } else { '\n' };
                        return Ok(Some(app.selection_str(d)));
                    }
                    MsgOut::PrintResultAndQuit => {
                        let d = if cli.write0 { '\0' } else { '\n' };
                        return Ok(Some(app.result_str(d)));
                    }
                    MsgOut::PrintAppStateAndQuit => {
                        return Ok(Some(app.to_yaml()));
                    }
                    MsgOut::Debug(path) => {
                        if let Err(e) = fs::write(&path, app.to_yaml()) {
                            app.log_error(format!("could not write {:?}: {}", path, e));
                        }
                    }
                    MsgOut::Call(cmd) => {
                        call(&mut app, &cmd, '\n', false, &guard, &mut terminal)?;
                        pending.extend(drain_msg_in(&app));
                    }
                    MsgOut::Call0(cmd) => {
                        call(&mut app, &cmd, '\0', false, &guard, &mut terminal)?;
                        pending.extend(drain_msg_in(&app));
                    }
                    MsgOut::CallSilently(cmd) => {
                        call(&mut app, &cmd, '\n', true, &guard, &mut terminal)?;
                        pending.extend(drain_msg_in(&app));
                    }
                    MsgOut::CallSilently0(cmd) => {
                        call(&mut app, &cmd, '\0', true, &guard, &mut terminal)?;
                        pending.extend(drain_msg_in(&app));
                    }
                    MsgOut::CallLua(func) => {
                        guard.leave()?;
                        let res = match lua.as_ref() {
                            Some(l) => l.call(&func, &app),
                            None => Err(anyhow::anyhow!("lua scripting is not available")),
                        };
                        TerminalGuard::enter(mouse_enabled)?;
                        terminal.clear()?;
                        handle_lua_result(&mut app, res, &mut pending);
                    }
                    MsgOut::CallLuaSilently(func) => {
                        let res = match lua.as_ref() {
                            Some(l) => l.call(&func, &app),
                            None => Err(anyhow::anyhow!("lua scripting is not available")),
                        };
                        handle_lua_result(&mut app, res, &mut pending);
                    }
                    MsgOut::LuaEval(code) => {
                        guard.leave()?;
                        let res = match lua.as_ref() {
                            Some(l) => l.eval(&code, &app),
                            None => Err(anyhow::anyhow!("lua scripting is not available")),
                        };
                        TerminalGuard::enter(mouse_enabled)?;
                        terminal.clear()?;
                        handle_lua_result(&mut app, res, &mut pending);
                    }
                    MsgOut::LuaEvalSilently(code) => {
                        let res = match lua.as_ref() {
                            Some(l) => l.eval(&code, &app),
                            None => Err(anyhow::anyhow!("lua scripting is not available")),
                        };
                        handle_lua_result(&mut app, res, &mut pending);
                    }
                    MsgOut::EnableMouse => {
                        if !mouse_enabled {
                            execute!(io::stdout(), EnableMouseCapture)?;
                            mouse_enabled = true;
                            app.log_success("mouse enabled".to_string());
                        }
                    }
                    MsgOut::DisableMouse => {
                        if mouse_enabled {
                            execute!(io::stdout(), DisableMouseCapture)?;
                            mouse_enabled = false;
                            app.log_success("mouse disabled".to_string());
                        }
                    }
                    MsgOut::ToggleMouse => {
                        if mouse_enabled {
                            execute!(io::stdout(), DisableMouseCapture)?;
                            mouse_enabled = false;
                            app.log_success("mouse disabled".to_string());
                        } else {
                            execute!(io::stdout(), EnableMouseCapture)?;
                            mouse_enabled = true;
                            app.log_success("mouse enabled".to_string());
                        }
                    }
                    MsgOut::StartFifo(path) => match Fifo::start(&path) {
                        Ok(f) => {
                            fifo = Some(f);
                            last_fifo_focus = None;
                            app.log_success(format!("fifo started: {}", path));
                        }
                        Err(e) => app.log_error(format!("could not start fifo: {}", e)),
                    },
                    MsgOut::StopFifo => {
                        if let Some(f) = fifo.take() {
                            app.log_success(format!("fifo stopped: {}", f.path));
                        }
                    }
                    MsgOut::ToggleFifo(path) => {
                        if let Some(f) = fifo.take() {
                            app.log_success(format!("fifo stopped: {}", f.path));
                        } else {
                            match Fifo::start(&path) {
                                Ok(f) => {
                                    fifo = Some(f);
                                    last_fifo_focus = None;
                                    app.log_success(format!("fifo started: {}", path));
                                }
                                Err(e) => app.log_error(format!("could not start fifo: {}", e)),
                            }
                        }
                    }
                }
            }
        }
    })();

    stop.store(true, Ordering::Relaxed);
    guard.leave()?;
    let _ = fs::remove_dir_all(&app.session_path);
    result
}

fn handle_lua_result(app: &mut App, res: Result<Vec<ExternalMsg>>, pending: &mut VecDeque<Task>) {
    match res {
        Ok(msgs) => {
            for m in msgs {
                pending.push_back(Task::new(MsgIn::External(m), None));
            }
        }
        Err(e) => app.log_error(e.to_string()),
    }
}

fn drain_msg_in(app: &App) -> Vec<Task> {
    read_msg_in(&app.pipe.msg_in)
        .unwrap_or_default()
        .into_iter()
        .map(|m| Task::new(MsgIn::External(m), None))
        .collect()
}

fn call(
    app: &mut App,
    cmd: &Command,
    delimiter: char,
    silent: bool,
    guard: &TerminalGuard,
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
) -> Result<()> {
    write_pipes(app, delimiter)?;
    let focus_index = app
        .directory_buffer
        .as_ref()
        .map(|d| d.focus)
        .unwrap_or(0)
        .to_string();
    let input_buffer = app
        .input
        .buffer
        .as_ref()
        .map(|b| b.value())
        .unwrap_or_default();

    let mut command = std::process::Command::new(&cmd.command);
    command
        .args(&cmd.args)
        .current_dir(&app.pwd)
        .env("XPLR", &app.bin)
        .env("XPLR_APP_VERSION", &app.version)
        .env("XPLR_PID", app.pid.to_string())
        .env("XPLR_INPUT_BUFFER", input_buffer)
        .env("XPLR_INITIAL_PWD", &app.initial_pwd)
        .env("XPLR_FOCUS_PATH", app.focused_node_str())
        .env("XPLR_FOCUS_INDEX", focus_index)
        .env("XPLR_SESSION_PATH", &app.session_path)
        .env("XPLR_PIPE_MSG_IN", &app.pipe.msg_in)
        .env("XPLR_PIPE_SELECTION_OUT", &app.pipe.selection_out)
        .env("XPLR_PIPE_HISTORY_OUT", &app.pipe.history_out)
        .env("XPLR_PIPE_RESULT_OUT", &app.pipe.result_out)
        .env("XPLR_PIPE_LOGS_OUT", &app.pipe.logs_out)
        .env("XPLR_PIPE_DIRECTORY_NODES_OUT", &app.pipe.directory_nodes_out)
        .env("XPLR_PIPE_GLOBAL_HELP_MENU_OUT", &app.pipe.global_help_menu_out)
        .env("XPLR_MODE", &app.mode.name)
        .env("XPLR_VROOT", app.vroot.clone().unwrap_or_default());

    if silent {
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let status = command.status();
        if let Err(e) = status {
            app.log_error(format!("could not execute {:?}: {}", cmd.command, e));
        }
    } else {
        guard.leave()?;
        let status = command.status();
        TerminalGuard::enter(guard.mouse)?;
        terminal.clear()?;
        if let Err(e) = status {
            app.log_error(format!("could not execute {:?}: {}", cmd.command, e));
        }
    }
    Ok(())
}
