use std::io::Write;

fn real_main() -> anyhow::Result<i32> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let cli = cli::Cli::parse(args)?;

    if cli.help {
        print!("{}", cli::HELP);
        return Ok(0);
    }
    if cli.version {
        println!("xplr {}", app::VERSION);
        return Ok(0);
    }
    if !cli.print_msg_in.is_empty() {
        let (fmt, rest) = cli.print_msg_in.split_first().unwrap();
        let json = jf::format(fmt, rest)?;
        serde_json::from_str::<msg::ExternalMsg>(&json)?;
        print!("{}", json);
        return Ok(0);
    }
    if !cli.pipe_msg_in.is_empty() {
        let (fmt, rest) = cli.pipe_msg_in.split_first().unwrap();
        let json = jf::format(fmt, rest)?;
        serde_json::from_str::<msg::ExternalMsg>(&json)?;
        match std::env::var("XPLR_PIPE_MSG_IN").ok().filter(|p| !p.is_empty()) {
            Some(pipe) => {
                let content = std::fs::read(&pipe)?;
                let delimiter = match content.first() {
                    Some(d) => *d,
                    None => anyhow::bail!("failed to detect delimmiter"),
                };
                let mut f = std::fs::OpenOptions::new().append(true).open(&pipe)?;
                f.write_all(json.as_bytes())?;
                f.write_all(&[delimiter])?;
            }
            None => print!("{}", json),
        }
        return Ok(0);
    }

    let runner = runner::Runner::from_cli(cli)?;
    match runner::run(runner) {
        Ok(Some(out)) => {
            let mut stdout = std::io::stdout();
            stdout.write_all(out.as_bytes())?;
            stdout.flush()?;
            Ok(0)
        }
        Ok(None) => Ok(0),
        Err(e) => {
            if e.to_string() == "terminated" {
                Ok(1)
            } else {
                Err(e)
            }
        }
    }
}

fn main() {
    match real_main() {
        Ok(code) => std::process::exit(code),
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }
}
