    pub year: i64,
    pub month: u32,
    pub day: u32,
    pub ordinal: u32,
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
    pub nanos: u32,
}

impl DateTime {
    pub fn now_local() -> Self {
        let d = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default();
        DateTime {
            unix_nanos: d.as_nanos() as i128,
            offset: local_offset_secs(),
        }
    }

    pub fn parts(&self) -> Parts {
        let total_secs = self.unix_nanos.div_euclid(1_000_000_000) as i64 + self.offset as i64;
        let nanos = self.unix_nanos.rem_euclid(1_000_000_000) as u32;
        let days = total_secs.div_euclid(86400);
        let sod = total_secs.rem_euclid(86400);
        let (year, month, day) = days_to_civil(days);
        Parts {
            year,
            month,
            day,
            ordinal: ordinal(year, month, day),
            hour: (sod / 3600) as u32,
            minute: ((sod % 3600) / 60) as u32,
            second: (sod % 60) as u32,
            nanos,
        }
    }

    pub fn hms(&self) -> String {
        let p = self.parts();
        format!("{:02}:{:02}:{:02}", p.hour, p.minute, p.second)
    }

    /// Full representation, e.g. `2026-10-08 4:43:20.565290443 +00:00:00`.
    pub fn full(&self) -> String {
        let p = self.parts();
        let mut s = format!(
            "{:04}-{:02}-{:02} {}:{:02}:{:02}",
