fn compare_right(a: &[char], b: &[char]) -> std::cmp::Ordering {
    use std::cmp::Ordering::*;
    let mut bias = Equal;
    let mut k = 0;
    loop {
        let da = a.get(k).map(|c| c.is_ascii_digit()).unwrap_or(false);
