#[derive(Debug, Clone)]
pub struct Token {
    pub tok: Tok,
    pub line: u32,
}

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    line: u32,
    pub chunkname: String,
}

fn is_name_start(c: u8) -> bool {
    c.is_ascii_alphabetic() || c == b'_'
}

fn is_name_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_'
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8], chunkname: &str) -> Self {
        let mut pos = 0;
        // skip shebang
        if src.starts_with(b"#") {
            while pos < src.len() && src[pos] != b'\n' {
                pos += 1;
            }
        }
        Lexer {
            src,
            pos,
            line: 1,
            chunkname: chunkname.to_string(),
        }
    }

    fn err(&self, msg: &str, near: &str) -> String {
        if near.is_empty() {
            format!("{}:{}: {}", self.chunkname, self.line, msg)
        } else {
            format!("{}:{}: {} near '{}'", self.chunkname, self.line, msg, near)
        }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    fn peek_at(&self, n: usize) -> Option<u8> {
        self.src.get(self.pos + n).copied()
    }

    fn bump(&mut self) -> Option<u8> {
        let c = self.src.get(self.pos).copied();
        if let Some(c) = c {
            self.pos += 1;
            if c == b'\n' {
                self.line += 1;
            }
        }
        c
    }

    /// Try to read a long bracket opener `[=*[` at the current position;
    /// returns the level if present.
    fn long_bracket_level(&self) -> Option<usize> {
        if self.peek() != Some(b'[') {
            return None;
        }
        let mut n = 1;
        let mut level = 0;
        while self.peek_at(n) == Some(b'=') {
            level += 1;
            n += 1;
        }
        if self.peek_at(n) == Some(b'[') {
            Some(level)
        } else {
            None
        }
    }

    fn read_long_string(&mut self, level: usize) -> Result<Vec<u8>, String> {
        // skip opener
        self.pos += level + 2;
        // skip first newline
        if self.peek() == Some(b'\r') {
            self.bump();
            if self.peek() == Some(b'\n') {
                self.bump();
            }
        } else if self.peek() == Some(b'\n') {
            self.bump();
            if self.peek() == Some(b'\r') {
                self.bump();
            }
        }
        let mut out = Vec::new();
        loop {
            match self.peek() {
                None => return Err(self.err("unfinished long string", "<eof>")),
                Some(b']') => {
                    let mut n = 1;
                    let mut l = 0;
                    while self.peek_at(n) == Some(b'=') {
                        l += 1;
                        n += 1;
                    }
                    if l == level && self.peek_at(n) == Some(b']') {
                        self.pos += n + 1;
                        return Ok(out);
                    }
                    out.push(b']');
                    self.bump();
                }
                Some(c) => {
                    out.push(c);
                    self.bump();
                }
            }
        }
    }

    fn skip_whitespace_and_comments(&mut self) -> Result<(), String> {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\r') | Some(b'\n') | Some(0x0b) | Some(0x0c) => {
                    self.bump();
                }
                Some(b'-') if self.peek_at(1) == Some(b'-') => {
                    self.pos += 2;
                    if let Some(level) = self.long_bracket_level() {
                        self.read_long_string(level)?;
                    } else {
                        while let Some(c) = self.peek() {
                            if c == b'\n' {
                                break;
                            }
                            self.bump();
                        }
                    }
                }
                _ => return Ok(()),
            }
        }
    }

    fn read_number(&mut self) -> Result<f64, String> {
        let start = self.pos;
        if self.peek() == Some(b'0') && matches!(self.peek_at(1), Some(b'x') | Some(b'X')) {
            self.pos += 2;
            let hstart = self.pos;
            while let Some(c) = self.peek() {
                if c.is_ascii_hexdigit() || c == b'.' || c == b'p' || c == b'P'
                    || ((c == b'+' || c == b'-') && matches!(self.src.get(self.pos - 1), Some(b'p') | Some(b'P')))
                {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            let text = std::str::from_utf8(&self.src[hstart..self.pos]).unwrap_or("");
            return parse_hex_float(text)
                .ok_or_else(|| self.err("malformed number", std::str::from_utf8(&self.src[start..self.pos]).unwrap_or("")));
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == b'.' {
                self.pos += 1;
            } else if (c == b'e' || c == b'E') {
                self.pos += 1;
                if matches!(self.peek(), Some(b'+') | Some(b'-')) {
                    self.pos += 1;
                }
            } else if is_name_char(c) {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.src[start..self.pos]).unwrap_or("");
        text.parse::<f64>()
            .map_err(|_| self.err("malformed number", text))
    }

    fn read_string(&mut self, quote: u8) -> Result<Vec<u8>, String> {
        self.bump();
        let mut out = Vec::new();
        loop {
            match self.bump() {
                None => return Err(self.err("unfinished string", "<eof>")),
                Some(b'\n') => return Err(self.err("unfinished string", "")),
                Some(c) if c == quote => return Ok(out),
                Some(b'\\') => match self.bump() {
                    None => return Err(self.err("unfinished string", "<eof>")),
                    Some(b'n') => out.push(b'\n'),
                    Some(b't') => out.push(b'\t'),
                    Some(b'r') => out.push(b'\r'),
                    Some(b'a') => out.push(0x07),
                    Some(b'b') => out.push(0x08),
                    Some(b'f') => out.push(0x0c),
                    Some(b'v') => out.push(0x0b),
                    Some(b'\\') => out.push(b'\\'),
                    Some(b'"') => out.push(b'"'),
                    Some(b'\'') => out.push(b'\''),
                    Some(b'\n') => out.push(b'\n'),
                    Some(b'x') => {
                        let mut v = 0u32;
                        for _ in 0..2 {
                            match self.bump() {
                                Some(h) if h.is_ascii_hexdigit() => {
                                    v = v * 16 + (h as char).to_digit(16).unwrap();
                                }
                                _ => return Err(self.err("hexadecimal digit expected", "")),
                            }
                        }
                        out.push(v as u8);
                    }
                    Some(b'z') => {
                        while let Some(c) = self.peek() {
                            if c.is_ascii_whitespace() {
                                self.bump();
                            } else {
                                break;
                            }
                        }
                    }
                    Some(c) if c.is_ascii_digit() => {
                        let mut v = (c - b'0') as u32;
                        for _ in 0..2 {
                            match self.peek() {
                                Some(d) if d.is_ascii_digit() => {
                                    v = v * 10 + (d - b'0') as u32;
                                    self.bump();
                                }
                                _ => break,
                            }
                        }
                        if v > 255 {
                            return Err(self.err("decimal escape too large", ""));
                        }
                        out.push(v as u8);
                    }
                    Some(c) => return Err(self.err("invalid escape sequence", &format!("\\{}", c as char))),
                },
                Some(c) => out.push(c),
            }
        }
    }

    pub fn next_token(&mut self) -> Result<Token, String> {
        self.skip_whitespace_and_comments()?;
        let line = self.line;
        let c = match self.peek() {
            None => {
                return Ok(Token {
                    tok: Tok::Eof,
                    line,
                })
            }
            Some(c) => c,
        };
        let tok = if is_name_start(c) {
            let start = self.pos;
            while let Some(c) = self.peek() {
                if is_name_char(c) {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            let name = std::str::from_utf8(&self.src[start..self.pos]).unwrap().to_string();
            match name.as_str() {
                "and" => Tok::And,
                "break" => Tok::Break,
                "do" => Tok::Do,
                "else" => Tok::Else,
                "elseif" => Tok::Elseif,
                "end" => Tok::End,
                "false" => Tok::False,
                "for" => Tok::For,
                "function" => Tok::Function,
                "if" => Tok::If,
                "in" => Tok::In,
                "local" => Tok::Local,
                "nil" => Tok::Nil,
                "not" => Tok::Not,
                "or" => Tok::Or,
                "repeat" => Tok::Repeat,
                "return" => Tok::Return,
                "then" => Tok::Then,
                "true" => Tok::True,
                "until" => Tok::Until,
                "while" => Tok::While,
                "goto" => Tok::Goto,
                _ => Tok::Name(name),
            }
        } else if c.is_ascii_digit() || (c == b'.' && self.peek_at(1).map(|d| d.is_ascii_digit()).unwrap_or(false)) {
            Tok::Num(self.read_number()?)
        } else if c == b'"' || c == b'\'' {
            Tok::Str(self.read_string(c)?)
        } else if let Some(level) = self.long_bracket_level() {
            Tok::Str(self.read_long_string(level)?)
        } else {
            self.pos += 1;
            match c {
                b'+' => Tok::Plus,
                b'-' => Tok::Minus,
                b'*' => Tok::Star,
                b'/' => Tok::Slash,
                b'%' => Tok::Percent,
                b'^' => Tok::Caret,
                b'#' => Tok::Hash,
                b'(' => Tok::LParen,
                b')' => Tok::RParen,
                b'{' => Tok::LBrace,
                b'}' => Tok::RBrace,
                b'[' => Tok::LBracket,
                b']' => Tok::RBracket,
                b';' => Tok::Semi,
                b',' => Tok::Comma,
                b':' => {
                    if self.peek() == Some(b':') {
                        self.pos += 1;
                        Tok::DoubleColon
                    } else {
                        Tok::Colon
                    }
                }
                b'=' => {
                    if self.peek() == Some(b'=') {
                        self.pos += 1;
                        Tok::Eq
                    } else {
                        Tok::Assign
                    }
                }
                b'~' => {
                    if self.peek() == Some(b'=') {
                        self.pos += 1;
                        Tok::Ne
                    } else {
                        return Err(self.err("unexpected symbol", "~"));
                    }
                }
                b'<' => {
                    if self.peek() == Some(b'=') {
                        self.pos += 1;
                        Tok::Le
                    } else {
                        Tok::Lt
                    }
                }
                b'>' => {
                    if self.peek() == Some(b'=') {
                        self.pos += 1;
                        Tok::Ge
                    } else {
                        Tok::Gt
                    }
                }
                b'.' => {
                    if self.peek() == Some(b'.') {
                        self.pos += 1;
                        if self.peek() == Some(b'.') {
                            self.pos += 1;
                            Tok::Ellipsis
                        } else {
                            Tok::Concat
                        }
                    } else {
                        Tok::Dot
                    }
                }
                other => {
                    return Err(self.err(
                        "unexpected symbol",
                        &String::from_utf8_lossy(&[other]),
                    ))
                }
            }
        };
        Ok(Token { tok, line })
    }

    pub fn tokenize(mut self) -> Result<Vec<Token>, String> {
        let mut out = Vec::new();
        loop {
            let t = self.next_token()?;
            let eof = t.tok == Tok::Eof;
            out.push(t);
            if eof {
                return Ok(out);
            }
        }
    }
}

fn parse_hex_float(text: &str) -> Option<f64> {
    let (mant, exp) = match text.find(|c| c == 'p' || c == 'P') {
        Some(i) => (&text[..i], text[i + 1..].parse::<i32>().ok()?),
        None => (text, 0),
    };
    let (int_part, frac_part) = match mant.find('.') {
        Some(i) => (&mant[..i], &mant[i + 1..]),
        None => (mant, ""),
    };
    if int_part.is_empty() && frac_part.is_empty() {
        return None;
    }
    let mut v = 0f64;
    for c in int_part.chars() {
        v = v * 16.0 + c.to_digit(16)? as f64;
    }
    let mut scale = 1.0 / 16.0;
    for c in frac_part.chars() {
        v += c.to_digit(16)? as f64 * scale;
        scale /= 16.0;
    }
    Some(v * 2f64.powi(exp))
}

pub fn tok_name(t: &Tok) -> String {
    match t {
        Tok::Name(n) => n.clone(),
        Tok::Str(s) => String::from_utf8_lossy(s).to_string(),
        Tok::Num(n) => format_num(*n),
        Tok::Eof => "<eof>".to_string(),
        Tok::And => "and".into(),
        Tok::Break => "break".into(),
        Tok::Do => "do".into(),
        Tok::Else => "else".into(),
        Tok::Elseif => "elseif".into(),
        Tok::End => "end".into(),
        Tok::False => "false".into(),
        Tok::For => "for".into(),
        Tok::Function => "function".into(),
        Tok::If => "if".into(),
        Tok::In => "in".into(),
        Tok::Local => "local".into(),
        Tok::Nil => "nil".into(),
        Tok::Not => "not".into(),
        Tok::Or => "or".into(),
        Tok::Repeat => "repeat".into(),
        Tok::Return => "return".into(),
        Tok::Then => "then".into(),
        Tok::True => "true".into(),
        Tok::Until => "until".into(),
        Tok::While => "while".into(),
        Tok::Goto => "goto".into(),
        Tok::Plus => "+".into(),
        Tok::Minus => "-".into(),
        Tok::Star => "*".into(),
        Tok::Slash => "/".into(),
        Tok::Percent => "%".into(),
        Tok::Caret => "^".into(),
        Tok::Hash => "#".into(),
        Tok::Eq => "==".into(),
        Tok::Ne => "~=".into(),
        Tok::Le => "<=".into(),
        Tok::Ge => ">=".into(),
        Tok::Lt => "<".into(),
        Tok::Gt => ">".into(),
        Tok::Assign => "=".into(),
        Tok::LParen => "(".into(),
        Tok::RParen => ")".into(),
        Tok::LBrace => "{".into(),
        Tok::RBrace => "}".into(),
        Tok::LBracket => "[".into(),
        Tok::RBracket => "]".into(),
        Tok::Semi => ";".into(),
        Tok::Colon => ":".into(),
        Tok::DoubleColon => "::".into(),
        Tok::Comma => ",".into(),
        Tok::Dot => ".".into(),
        Tok::Concat => "..".into(),
        Tok::Ellipsis => "...".into(),
    }
}

/// Format a number the way Lua's `tostring` does (`%.14g`).
pub fn format_num(n: f64) -> String {
    if n.is_nan() {
        return if n.is_sign_negative() { "-nan".into() } else { "nan".into() };
    }
    if n.is_infinite() {
        return if n > 0.0 { "inf".into() } else { "-inf".into() };
    }
    if n == n.trunc() && n.abs() < 1e15 {
        return format!("{}", n as i64);
    }
    format_g(n, 14)
}

/// C-style `%.{prec}g` formatting.
pub fn format_g(n: f64, prec: usize) -> String {
    if n == 0.0 {
        return if n.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    let prec = prec.max(1);
    let exp = n.abs().log10().floor() as i32;
    // decide between %e and %f styles
    let sci = format!("{:.*e}", prec - 1, n);
    // parse exponent from sci repr to be exact
    let e_val: i32 = sci
        .rsplit('e')
        .next()
        .and_then(|e| e.parse().ok())
        .unwrap_or(exp);
    if e_val < -4 || e_val >= prec as i32 {
        // scientific
        let (mant, _) = sci.split_once('e').unwrap();
        let mant = strip_trailing_zeros(mant);
        let sign = if e_val < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", mant, sign, e_val.abs())
    } else {
        let decimals = (prec as i32 - 1 - e_val).max(0) as usize;
        let f = format!("{:.*}", decimals, n);
        strip_trailing_zeros(&f)
    }
}

fn strip_trailing_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        t.trim_end_matches('.').to_string()
    } else {
        s.to_string()
    }
}
