//! Recursive descent parser producing a resolved AST.

use super::ast::*;
use super::lexer::{tok_name, Tok, Token};
use std::rc::Rc;

struct FuncState {
    scopes: Vec<Vec<(String, usize)>>,
    nslots: usize,
    upvals: Vec<(String, UpvalDesc)>,
    is_vararg: bool,
}

impl FuncState {
    fn new(is_vararg: bool) -> Self {
        FuncState {
            scopes: vec![vec![]],
            nslots: 0,
            upvals: vec![],
            is_vararg,
        }
    }

    fn declare(&mut self, name: &str) -> usize {
        let slot = self.nslots;
        self.nslots += 1;
        self.scopes.last_mut().unwrap().push((name.to_string(), slot));
        slot
    }

    fn find_local(&self, name: &str) -> Option<usize> {
        for scope in self.scopes.iter().rev() {
            for (n, slot) in scope.iter().rev() {
                if n == name {
                    return Some(*slot);
                }
            }
        }
        None
    }
}

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
    funcs: Vec<FuncState>,
    chunkname: Rc<str>,
}

type PResult<T> = Result<T, String>;

impl Parser {
    pub fn new(toks: Vec<Token>, chunkname: &str) -> Self {
        Parser {
            toks,
            pos: 0,
            funcs: vec![],
            chunkname: Rc::from(chunkname),
        }
    }

    fn peek(&self) -> &Tok {
        &self.toks[self.pos].tok
    }

    fn peek_at(&self, n: usize) -> &Tok {
        let i = (self.pos + n).min(self.toks.len() - 1);
        &self.toks[i].tok
    }

    fn line(&self) -> u32 {
        self.toks[self.pos].line
    }

    fn advance(&mut self) -> Token {
        let t = self.toks[self.pos].clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }

    fn err_near(&self, msg: &str) -> String {
        let t = &self.toks[self.pos];
        let near = match &t.tok {
            Tok::Eof => "<eof>".to_string(),
            Tok::Str(s) => format!("'{}'", String::from_utf8_lossy(s)),
            other => format!("'{}'", tok_name(other)),
        };
        if near == "<eof>" {
            format!("{}:{}: {} near {}", self.chunkname, t.line, msg, near)
        } else {
            format!("{}:{}: {} near {}", self.chunkname, t.line, msg, near)
        }
    }

    fn expect(&mut self, tok: Tok, what: &str) -> PResult<Token> {
        if self.peek() == &tok {
            Ok(self.advance())
        } else {
            Err(self.err_near(&format!("'{}' expected", what)))
        }
    }

    fn expect_match(&mut self, tok: Tok, what: &str, opener: &str, line: u32) -> PResult<Token> {
        if self.peek() == &tok {
            Ok(self.advance())
        } else if line == self.line() {
            Err(self.err_near(&format!("'{}' expected", what)))
        } else {
            Err(self.err_near(&format!(
                "'{}' expected (to close '{}' at line {})",
                what, opener, line
            )))
        }
    }

    fn check(&mut self, tok: &Tok) -> bool {
        if self.peek() == tok {
            self.advance();
            true
        } else {
            false
        }
    }

    fn expect_name(&mut self) -> PResult<String> {
        match self.peek().clone() {
            Tok::Name(n) => {
                self.advance();
                Ok(n)
            }
            _ => Err(self.err_near("<name> expected")),
        }
    }

    fn fs(&mut self) -> &mut FuncState {
        self.funcs.last_mut().unwrap()
    }

    fn open_scope(&mut self) {
        self.fs().scopes.push(vec![]);
    }

    fn close_scope(&mut self) {
        self.fs().scopes.pop();
    }

    /// Resolve a name to a local, upvalue or global expression.
    fn resolve(&mut self, name: &str) -> Expr {
        let depth = self.funcs.len() - 1;
        match self.resolve_in(depth, name) {
            Some((true, slot)) => Expr::Local(slot),
            Some((false, idx)) => Expr::Upval(idx),
            None => Expr::Global(Rc::from(name)),
        }
    }

    /// Returns (is_local, index) relative to function at `depth`.
    fn resolve_in(&mut self, depth: usize, name: &str) -> Option<(bool, usize)> {
        if let Some(slot) = self.funcs[depth].find_local(name) {
            return Some((true, slot));
        }
        if let Some(i) = self.funcs[depth]
            .upvals
            .iter()
            .position(|(n, _)| n == name)
        {
            return Some((false, i));
        }
        if depth == 0 {
            return None;
        }
        match self.resolve_in(depth - 1, name) {
            Some((from_local, index)) => {
                let fs = &mut self.funcs[depth];
                fs.upvals.push((
                    name.to_string(),
                    UpvalDesc {
                        from_parent_local: from_local,
                        index,
                    },
                ));
                Some((false, fs.upvals.len() - 1))
            }
            None => None,
        }
    }

    // ------------------------------------------------------------ entry

    pub fn parse_chunk(mut self) -> PResult<Rc<FuncProto>> {
        self.funcs.push(FuncState::new(true));
        let body = self.parse_block()?;
        if self.peek() != &Tok::Eof {
            return Err(self.err_near("'<eof>' expected"));
        }
        let fs = self.funcs.pop().unwrap();
        Ok(Rc::new(FuncProto {
            nparams: 0,
            is_vararg: true,
            nslots: fs.nslots,
            upvals: fs.upvals.iter().map(|(_, d)| *d).collect(),
            body,
            name: "main chunk".to_string(),
            line: 0,
            chunkname: self.chunkname.clone(),
        }))
    }

    fn block_follow(&self) -> bool {
        matches!(
            self.peek(),
            Tok::Else | Tok::Elseif | Tok::End | Tok::Until | Tok::Eof
        )
    }

    fn parse_block(&mut self) -> PResult<Block> {
        let mut stats = Vec::new();
        loop {
            if self.block_follow() {
                break;
            }
            if self.peek() == &Tok::Return {
                let line = self.line();
                self.advance();
                let exprs = if self.block_follow() || self.peek() == &Tok::Semi {
                    vec![]
                } else {
                    self.parse_exprlist()?
                };
                self.check(&Tok::Semi);
                stats.push(Stat::Return(exprs, line));
                if !self.block_follow() {
                    return Err(self.err_near("'<eof>' expected"));
                }
                break;
            }
            if self.peek() == &Tok::Break {
                self.advance();
                self.check(&Tok::Semi);
                stats.push(Stat::Break);
                continue;
            }
            let s = self.parse_statement()?;
            if let Some(s) = s {
                stats.push(s);
            }
        }
        Ok(stats)
    }

    fn parse_statement(&mut self) -> PResult<Option<Stat>> {
        let line = self.line();
        match self.peek().clone() {
            Tok::Semi => {
                self.advance();
                Ok(None)
            }
            Tok::If => self.parse_if().map(Some),
            Tok::While => {
                self.advance();
                let cond = self.parse_expr()?;
                self.expect(Tok::Do, "do")?;
                self.open_scope();
                let body = self.parse_block()?;
                self.close_scope();
                self.expect_match(Tok::End, "end", "while", line)?;
                Ok(Some(Stat::While(cond, body)))
            }
            Tok::Do => {
                self.advance();
                self.open_scope();
                let body = self.parse_block()?;
                self.close_scope();
                self.expect_match(Tok::End, "end", "do", line)?;
                Ok(Some(Stat::Do(body)))
            }
            Tok::For => self.parse_for().map(Some),
            Tok::Repeat => {
                self.advance();
                self.open_scope();
                let body = self.parse_block()?;
                self.expect_match(Tok::Until, "until", "repeat", line)?;
                let cond = self.parse_expr()?;
                self.close_scope();
                Ok(Some(Stat::Repeat(body, cond)))
            }
            Tok::Function => {
                self.advance();
                // funcname: Name {'.' Name} [':' Name]
                let n1 = self.expect_name()?;
                let mut target = self.resolve(&n1);
                let mut fullname = n1.clone();
                let mut is_method = false;
                loop {
                    match self.peek().clone() {
                        Tok::Dot => {
                            self.advance();
                            let n = self.expect_name()?;
                            fullname.push('.');
                            fullname.push_str(&n);
                            target = Expr::Index(
                                Box::new(target),
                                Box::new(Expr::Str(Rc::from(n.as_bytes()))),
                                line,
                            );
                        }
                        Tok::Colon => {
                            self.advance();
                            let n = self.expect_name()?;
                            fullname.push(':');
                            fullname.push_str(&n);
                            target = Expr::Index(
                                Box::new(target),
                                Box::new(Expr::Str(Rc::from(n.as_bytes()))),
                                line,
                            );
                            is_method = true;
                            break;
                        }
                        _ => break,
                    }
                }
                let f = self.parse_funcbody(is_method, &fullname, line)?;
                Ok(Some(Stat::Assign(vec![target], vec![Expr::Function(f)], line)))
            }
            Tok::Local => {
                self.advance();
                if self.check(&Tok::Function) {
                    let name = self.expect_name()?;
                    let slot = self.fs().declare(&name);
                    let f = self.parse_funcbody(false, &name, line)?;
                    Ok(Some(Stat::LocalFunction(slot, f)))
                } else {
                    let mut names = vec![self.expect_name()?];
                    while self.check(&Tok::Comma) {
                        names.push(self.expect_name()?);
                    }
                    let exprs = if self.check(&Tok::Assign) {
                        self.parse_exprlist()?
                    } else {
                        vec![]
                    };
                    // declare after evaluating expressions
                    let slots: Vec<usize> = names.iter().map(|n| self.fs().declare(n)).collect();
                    Ok(Some(Stat::Local(slots, exprs, line)))
                }
            }
            Tok::Return => unreachable!(),
            Tok::DoubleColon => {
                // label: ignore
                self.advance();
                self.expect_name()?;
                self.expect(Tok::DoubleColon, "::")?;
                Ok(None)
            }
            Tok::Goto => Err(self.err_near("goto is not supported")),
            _ => {
                // exprstat: either a call or an assignment
                let e = self.parse_suffixedexp()?;
                if self.peek() == &Tok::Assign || self.peek() == &Tok::Comma {
                    let mut targets = vec![e];
                    while self.check(&Tok::Comma) {
                        targets.push(self.parse_suffixedexp()?);
                    }
                    self.expect(Tok::Assign, "=")?;
                    let exprs = self.parse_exprlist()?;
                    for t in &targets {
                        match t {
                            Expr::Local(_) | Expr::Upval(_) | Expr::Global(_) | Expr::Index(..) => {}
                            _ => return Err(self.err_near("syntax error")),
                        }
                    }
                    Ok(Some(Stat::Assign(targets, exprs, line)))
                } else {
                    match e {
                        Expr::Call(..) | Expr::Method(..) => Ok(Some(Stat::Call(e, line))),
                        _ => Err(self.err_near("syntax error")),
                    }
                }
            }
        }
    }

    fn parse_if(&mut self) -> PResult<Stat> {
        let line = self.line();
        self.advance(); // if
        let mut clauses = Vec::new();
        let cond = self.parse_expr()?;
        self.expect(Tok::Then, "then")?;
        self.open_scope();
        let body = self.parse_block()?;
        self.close_scope();
        clauses.push((cond, body));
        let mut else_block = None;
        loop {
            match self.peek() {
                Tok::Elseif => {
                    self.advance();
                    let cond = self.parse_expr()?;
                    self.expect(Tok::Then, "then")?;
                    self.open_scope();
                    let body = self.parse_block()?;
                    self.close_scope();
                    clauses.push((cond, body));
                }
                Tok::Else => {
                    self.advance();
                    self.open_scope();
                    let body = self.parse_block()?;
                    self.close_scope();
                    else_block = Some(body);
                    self.expect_match(Tok::End, "end", "if", line)?;
                    break;
                }
                _ => {
                    self.expect_match(Tok::End, "end", "if", line)?;
                    break;
                }
            }
        }
        Ok(Stat::If(clauses, else_block))
    }

    fn parse_for(&mut self) -> PResult<Stat> {
        let line = self.line();
        self.advance(); // for
        let n1 = self.expect_name()?;
        if self.peek() == &Tok::Assign {
            self.advance();
            let start = self.parse_expr()?;
            self.expect(Tok::Comma, ",")?;
            let limit = self.parse_expr()?;
            let step = if self.check(&Tok::Comma) {
                Some(self.parse_expr()?)
            } else {
                None
            };
            self.expect(Tok::Do, "do")?;
            self.open_scope();
            let var = self.fs().declare(&n1);
            let body = self.parse_block()?;
            self.close_scope();
            self.expect_match(Tok::End, "end", "for", line)?;
            Ok(Stat::NumFor {
                var,
                start,
                limit,
                step,
                body,
                line,
            })
        } else {
            let mut names = vec![n1];
            while self.check(&Tok::Comma) {
                names.push(self.expect_name()?);
            }
            self.expect(Tok::In, "in")?;
            let exprs = self.parse_exprlist()?;
            self.expect(Tok::Do, "do")?;
            self.open_scope();
            let vars: Vec<usize> = names.iter().map(|n| self.fs().declare(n)).collect();
            let body = self.parse_block()?;
            self.close_scope();
            self.expect_match(Tok::End, "end", "for", line)?;
            Ok(Stat::GenFor {
                vars,
                exprs,
                body,
                line,
            })
        }
    }

    fn parse_funcbody(&mut self, is_method: bool, name: &str, line: u32) -> PResult<Rc<FuncProto>> {
        self.expect(Tok::LParen, "(")?;
        let mut fs = FuncState::new(false);
        let mut nparams = 0;
        if is_method {
            fs.declare("self");
            nparams += 1;
        }
        self.funcs.push(fs);
        if self.peek() != &Tok::RParen {
            loop {
                match self.peek().clone() {
                    Tok::Name(n) => {
                        self.advance();
                        self.fs().declare(&n);
                        nparams += 1;
                    }
                    Tok::Ellipsis => {
                        self.advance();
                        self.fs().is_vararg = true;
                        break;
                    }
                    _ => return Err(self.err_near("<name> expected")),
                }
                if !self.check(&Tok::Comma) {
                    break;
                }
            }
        }
        self.expect(Tok::RParen, ")")?;
        let body = self.parse_block()?;
        self.expect_match(Tok::End, "end", "function", line)?;
        let fs = self.funcs.pop().unwrap();
        Ok(Rc::new(FuncProto {
            nparams,
            is_vararg: fs.is_vararg,
            nslots: fs.nslots,
            upvals: fs.upvals.iter().map(|(_, d)| *d).collect(),
            body,
            name: name.to_string(),
            line,
            chunkname: self.chunkname.clone(),
        }))
    }

    fn parse_exprlist(&mut self) -> PResult<Vec<Expr>> {
        let mut v = vec![self.parse_expr()?];
        while self.check(&Tok::Comma) {
            v.push(self.parse_expr()?);
        }
        Ok(v)
    }

    // ------------------------------------------------------------ expressions

    fn parse_primaryexp(&mut self) -> PResult<Expr> {
        match self.peek().clone() {
            Tok::Name(n) => {
                self.advance();
                Ok(self.resolve(&n))
            }
            Tok::LParen => {
                let line = self.line();
                self.advance();
                let e = self.parse_expr()?;
                self.expect_match(Tok::RParen, ")", "(", line)?;
                Ok(Expr::Paren(Box::new(e)))
            }
            _ => Err(self.err_near("unexpected symbol")),
        }
    }

    fn parse_suffixedexp(&mut self) -> PResult<Expr> {
        let mut e = self.parse_primaryexp()?;
        loop {
            let line = self.line();
            match self.peek().clone() {
                Tok::Dot => {
                    self.advance();
                    let n = self.expect_name()?;
                    e = Expr::Index(Box::new(e), Box::new(Expr::Str(Rc::from(n.as_bytes()))), line);
                }
                Tok::LBracket => {
                    self.advance();
                    let k = self.parse_expr()?;
                    self.expect(Tok::RBracket, "]")?;
                    e = Expr::Index(Box::new(e), Box::new(k), line);
                }
                Tok::Colon => {
                    self.advance();
                    let n = self.expect_name()?;
                    let args = self.parse_callargs()?;
                    e = Expr::Method(Box::new(e), Rc::from(n.as_str()), args, line);
                }
                Tok::LParen | Tok::Str(_) | Tok::LBrace => {
                    let args = self.parse_callargs()?;
                    e = Expr::Call(Box::new(e), args, line);
                }
                _ => return Ok(e),
            }
        }
    }

    fn parse_callargs(&mut self) -> PResult<Vec<Expr>> {
        match self.peek().clone() {
            Tok::Str(s) => {
                self.advance();
                Ok(vec![Expr::Str(Rc::from(s.as_slice()))])
            }
            Tok::LBrace => Ok(vec![self.parse_table()?]),
            Tok::LParen => {
                let line = self.line();
                self.advance();
                if self.check(&Tok::RParen) {
                    return Ok(vec![]);
                }
                let args = self.parse_exprlist()?;
                self.expect_match(Tok::RParen, ")", "(", line)?;
                Ok(args)
            }
            _ => Err(self.err_near("function arguments expected")),
        }
    }

    fn parse_table(&mut self) -> PResult<Expr> {
        let line = self.line();
        self.expect(Tok::LBrace, "{")?;
        let mut items = Vec::new();
        loop {
            if self.peek() == &Tok::RBrace {
                break;
            }
            match self.peek().clone() {
                Tok::LBracket => {
                    self.advance();
                    let k = self.parse_expr()?;
                    self.expect(Tok::RBracket, "]")?;
                    self.expect(Tok::Assign, "=")?;
                    let v = self.parse_expr()?;
                    items.push(TableItem::Named(k, v));
                }
                Tok::Name(n) if self.peek_at(1) == &Tok::Assign => {
                    self.advance();
                    self.advance();
                    let v = self.parse_expr()?;
                    items.push(TableItem::Named(Expr::Str(Rc::from(n.as_bytes())), v));
                }
                _ => {
                    let v = self.parse_expr()?;
                    items.push(TableItem::Pos(v));
                }
            }
            if !(self.check(&Tok::Comma) || self.check(&Tok::Semi)) {
                break;
            }
        }
        self.expect_match(Tok::RBrace, "}", "{", line)?;
        Ok(Expr::Table(items, line))
    }

    fn parse_simpleexp(&mut self) -> PResult<Expr> {
        match self.peek().clone() {
            Tok::Num(n) => {
                self.advance();
                Ok(Expr::Num(n))
            }
            Tok::Str(s) => {
                self.advance();
                Ok(Expr::Str(Rc::from(s.as_slice())))
            }
            Tok::Nil => {
                self.advance();
                Ok(Expr::Nil)
            }
            Tok::True => {
                self.advance();
                Ok(Expr::True)
            }
            Tok::False => {
                self.advance();
                Ok(Expr::False)
            }
            Tok::Ellipsis => {
                if !self.fs().is_vararg {
                    return Err(self.err_near("cannot use '...' outside a vararg function"));
                }
                self.advance();
                Ok(Expr::Vararg)
            }
            Tok::LBrace => self.parse_table(),
            Tok::Function => {
                let line = self.line();
                self.advance();
                let f = self.parse_funcbody(false, "anonymous", line)?;
                Ok(Expr::Function(f))
            }
            _ => self.parse_suffixedexp(),
        }
    }

    fn binop_of(t: &Tok) -> Option<(BinOp, u8, u8)> {
        // (op, left priority, right priority)
        Some(match t {
            Tok::Or => return Some((BinOp::Eq, 1, 1)), // placeholder, handled separately
            Tok::And => return Some((BinOp::Eq, 2, 2)),
            Tok::Lt => (BinOp::Lt, 3, 3),
            Tok::Gt => (BinOp::Gt, 3, 3),
            Tok::Le => (BinOp::Le, 3, 3),
            Tok::Ge => (BinOp::Ge, 3, 3),
            Tok::Ne => (BinOp::Ne, 3, 3),
            Tok::Eq => (BinOp::Eq, 3, 3),
            Tok::Concat => (BinOp::Concat, 5, 4),
            Tok::Plus => (BinOp::Add, 6, 6),
            Tok::Minus => (BinOp::Sub, 6, 6),
            Tok::Star => (BinOp::Mul, 7, 7),
            Tok::Slash => (BinOp::Div, 7, 7),
            Tok::Percent => (BinOp::Mod, 7, 7),
            Tok::Caret => (BinOp::Pow, 10, 9),
            _ => return None,
        })
    }

    const UNARY_PRIORITY: u8 = 8;

    fn parse_subexpr(&mut self, limit: u8) -> PResult<Expr> {
        let line = self.line();
        let mut left = match self.peek() {
            Tok::Not => {
                self.advance();
                let e = self.parse_subexpr(Self::UNARY_PRIORITY)?;
                Expr::Un(UnOp::Not, Box::new(e), line)
            }
            Tok::Minus => {
                self.advance();
                let e = self.parse_subexpr(Self::UNARY_PRIORITY)?;
                match e {
                    Expr::Num(n) => Expr::Num(-n),
                    e => Expr::Un(UnOp::Neg, Box::new(e), line),
                }
            }
            Tok::Hash => {
                self.advance();
                let e = self.parse_subexpr(Self::UNARY_PRIORITY)?;
                Expr::Un(UnOp::Len, Box::new(e), line)
            }
            _ => self.parse_simpleexp()?,
        };
        loop {
            let tok = self.peek().clone();
            let (op, lp, rp) = match Self::binop_of(&tok) {
                Some(x) => x,
                None => break,
            };
            if lp <= limit {
                break;
            }
            let line = self.line();
            self.advance();
            let right = self.parse_subexpr(rp)?;
            left = match tok {
                Tok::Or => Expr::Or(Box::new(left), Box::new(right)),
                Tok::And => Expr::And(Box::new(left), Box::new(right)),
                _ => Expr::Bin(op, Box::new(left), Box::new(right), line),
            };
        }
        Ok(left)
    }

    pub fn parse_expr(&mut self) -> PResult<Expr> {
        self.parse_subexpr(0)
    }
}
EOF
echo ok"}

