//! Lua AST with resolved local slots.

use std::rc::Rc;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Pow,
    Concat,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum UnOp {
    Neg,
    Not,
    Len,
}

#[derive(Debug, Clone)]
pub enum TableItem {
    Pos(Expr),
    Named(Expr, Expr),
}

#[derive(Debug, Clone)]
pub enum Expr {
    Nil,
    True,
    False,
    Num(f64),
    Str(Rc<[u8]>),
    Vararg,
    Local(usize),
    Upval(usize),
    Global(Rc<str>),
    Index(Box<Expr>, Box<Expr>, u32),
    Call(Box<Expr>, Vec<Expr>, u32),
    Method(Box<Expr>, Rc<str>, Vec<Expr>, u32),
    Function(Rc<FuncProto>),
    Bin(BinOp, Box<Expr>, Box<Expr>, u32),
    Un(UnOp, Box<Expr>, u32),
    And(Box<Expr>, Box<Expr>),
    Or(Box<Expr>, Box<Expr>),
    Table(Vec<TableItem>, u32),
    Paren(Box<Expr>),
}

#[derive(Debug, Clone)]
pub enum Stat {
    Call(Expr, u32),
    Local(Vec<usize>, Vec<Expr>, u32),
    Assign(Vec<Expr>, Vec<Expr>, u32),
    Do(Block),
    While(Expr, Block),
    Repeat(Block, Expr),
    If(Vec<(Expr, Block)>, Option<Block>),
    NumFor {
        var: usize,
        start: Expr,
        limit: Expr,
        step: Option<Expr>,
        body: Block,
        line: u32,
    },
    GenFor {
        vars: Vec<usize>,
        exprs: Vec<Expr>,
        body: Block,
        line: u32,
    },
    LocalFunction(usize, Rc<FuncProto>),
    Return(Vec<Expr>, u32),
    Break,
}

pub type Block = Vec<Stat>;

#[derive(Debug, Clone, Copy)]
pub struct UpvalDesc {
    /// `true` when the upvalue refers to a local slot of the enclosing
    /// function, `false` when it refers to one of its upvalues.
    pub from_parent_local: bool,
    pub index: usize,
}

#[derive(Debug)]
pub struct FuncProto {
    pub nparams: usize,
    pub is_vararg: bool,
    pub nslots: usize,
    pub upvals: Vec<UpvalDesc>,
    pub body: Block,
    pub name: String,
    pub line: u32,
    pub chunkname: Rc<str>,
}
