//! Lua runtime values.

use super::ast::FuncProto;
use super::interp::Interp;
use indexmap::IndexMap;
use std::cell::RefCell;
use std::fmt;
use std::hash::{Hash, Hasher};
use std::rc::Rc;

pub type LStr = Rc<[u8]>;

pub type NativeFn = Rc<dyn Fn(&mut Interp, Vec<Value>) -> Result<Vec<Value>, LuaError>>;

pub struct Closure {
    pub proto: Rc<FuncProto>,
    pub upvals: Vec<Rc<RefCell<Value>>>,
}

pub enum Function {
    Lua(Closure),
    Native(String, NativeFn),
}

#[derive(Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Num(f64),
    Str(LStr),
    Table(TableRef),
    Func(Rc<Function>),
}

impl Default for Value {
    fn default() -> Self {
        Value::Nil
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::Nil => write!(f, "nil"),
            Value::Bool(b) => write!(f, "{}", b),
            Value::Num(n) => write!(f, "{}", n),
            Value::Str(s) => write!(f, "{:?}", String::from_utf8_lossy(s)),
            Value::Table(t) => write!(f, "table: {:p}", Rc::as_ptr(&t.0)),
            Value::Func(func) => write!(f, "function: {:p}", Rc::as_ptr(func)),
        }
    }
}

impl Value {
    pub fn str(s: &str) -> Value {
        Value::Str(Rc::from(s.as_bytes()))
    }

    pub fn bytes(b: &[u8]) -> Value {
        Value::Str(Rc::from(b))
    }

    pub fn truthy(&self) -> bool {
        !matches!(self, Value::Nil | Value::Bool(false))
    }

    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "boolean",
            Value::Num(_) => "number",
            Value::Str(_) => "string",
            Value::Table(_) => "table",
            Value::Func(_) => "function",
        }
    }

    pub fn as_str_lossy(&self) -> Option<String> {
        match self {
            Value::Str(s) => Some(String::from_utf8_lossy(s).to_string()),
            _ => None,
        }
    }

    pub fn as_num(&self) -> Option<f64> {
        match self {
            Value::Num(n) => Some(*n),
            Value::Str(s) => parse_number(&String::from_utf8_lossy(s)),
            _ => None,
        }
    }

    pub fn raw_eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Num(a), Value::Num(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Table(a), Value::Table(b)) => Rc::ptr_eq(&a.0, &b.0),
            (Value::Func(a), Value::Func(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

pub fn parse_number(s: &str) -> Option<f64> {
    let t = s.trim();
    if t.is_empty() {
        return None;
    }
    let (neg, body) = if let Some(r) = t.strip_prefix('-') {
        (true, r)
    } else if let Some(r) = t.strip_prefix('+') {
        (false, r)
    } else {
        (false, t)
    };
    let v = if body.starts_with("0x") || body.starts_with("0X") {
        i64::from_str_radix(&body[2..], 16).ok().map(|v| v as f64)
    } else {
        if body.chars().any(|c| c.is_alphabetic() && c != 'e' && c != 'E') {
            // reject things like "inf", "nan"
            if body.eq_ignore_ascii_case("inf") || body.eq_ignore_ascii_case("nan") || body.eq_ignore_ascii_case("infinity") {
                return None;
            }
        }
        body.parse::<f64>().ok()
    }?;
    Some(if neg { -v } else { v })
}

// ---------------------------------------------------------------- keys

#[derive(Clone)]
pub enum Key {
    Bool(bool),
    Int(i64),
    Float(u64),
    Str(LStr),
    Table(TableRef),
    Func(Rc<Function>),
}

impl PartialEq for Key {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Key::Bool(a), Key::Bool(b)) => a == b,
            (Key::Int(a), Key::Int(b)) => a == b,
            (Key::Float(a), Key::Float(b)) => a == b,
            (Key::Str(a), Key::Str(b)) => a == b,
            (Key::Table(a), Key::Table(b)) => Rc::ptr_eq(&a.0, &b.0),
            (Key::Func(a), Key::Func(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}
impl Eq for Key {}
impl Hash for Key {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            Key::Bool(b) => {
                0u8.hash(state);
                b.hash(state)
            }
            Key::Int(i) => {
                1u8.hash(state);
                i.hash(state)
            }
            Key::Float(f) => {
                2u8.hash(state);
                f.hash(state)
            }
            Key::Str(s) => {
                3u8.hash(state);
                s.hash(state)
            }
            Key::Table(t) => {
                4u8.hash(state);
                (Rc::as_ptr(&t.0) as usize).hash(state)
            }
            Key::Func(f) => {
                5u8.hash(state);
                (Rc::as_ptr(f) as *const u8 as usize).hash(state)
            }
        }
    }
}

impl Key {
    pub fn from_value(v: &Value) -> Option<Key> {
        match v {
            Value::Nil => None,
            Value::Bool(b) => Some(Key::Bool(*b)),
            Value::Num(n) => {
                if n.is_nan() {
                    None
                } else if n.fract() == 0.0 && n.abs() < 9.0e15 {
                    Some(Key::Int(*n as i64))
                } else {
                    Some(Key::Float(n.to_bits()))
                }
            }
            Value::Str(s) => Some(Key::Str(s.clone())),
            Value::Table(t) => Some(Key::Table(t.clone())),
            Value::Func(f) => Some(Key::Func(f.clone())),
        }
    }

    pub fn to_value(&self) -> Value {
        match self {
            Key::Bool(b) => Value::Bool(*b),
            Key::Int(i) => Value::Num(*i as f64),
            Key::Float(f) => Value::Num(f64::from_bits(*f)),
            Key::Str(s) => Value::Str(s.clone()),
            Key::Table(t) => Value::Table(t.clone()),
            Key::Func(f) => Value::Func(f.clone()),
        }
    }
}

// ---------------------------------------------------------------- tables

#[derive(Default)]
pub struct TableData {
    pub arr: Vec<Value>,
    pub hash: IndexMap<Key, Value>,
    pub meta: Option<TableRef>,
}

#[derive(Clone)]
pub struct TableRef(pub Rc<RefCell<TableData>>);

impl TableRef {
    pub fn new() -> Self {
        TableRef(Rc::new(RefCell::new(TableData::default())))
    }

    pub fn get(&self, key: &Value) -> Value {
        let t = self.0.borrow();
        if let Value::Num(n) = key {
            if n.fract() == 0.0 && *n >= 1.0 && (*n as usize) <= t.arr.len() {
                return t.arr[*n as usize - 1].clone();
            }
        }
        match Key::from_value(key) {
            Some(k) => t.hash.get(&k).cloned().unwrap_or(Value::Nil),
            None => Value::Nil,
        }
    }

    pub fn get_str(&self, key: &str) -> Value {
        self.get(&Value::str(key))
    }

    pub fn set(&self, key: Value, val: Value) -> Result<(), LuaError> {
        let mut t = self.0.borrow_mut();
        if let Value::Num(n) = &key {
            if n.is_nan() {
                return Err(LuaError::msg("table index is NaN"));
            }
            if n.fract() == 0.0 && *n >= 1.0 {
                let idx = *n as usize;
                if idx <= t.arr.len() {
                    if idx == t.arr.len() && matches!(val, Value::Nil) {
                        t.arr.pop();
                        // shrink trailing nils
                        while matches!(t.arr.last(), Some(Value::Nil)) {
                            t.arr.pop();
                        }
                    } else {
                        t.arr[idx - 1] = val;
                    }
                    return Ok(());
                }
                if idx == t.arr.len() + 1 {
                    if matches!(val, Value::Nil) {
                        t.hash.shift_remove(&Key::Int(idx as i64));
                        return Ok(());
                    }
                    t.arr.push(val);
                    // migrate following keys from hash
                    let mut next = idx + 1;
                    while let Some(v) = t.hash.shift_remove(&Key::Int(next as i64)) {
                        t.arr.push(v);
                        next += 1;
                    }
                    return Ok(());
                }
            }
        }
        let k = match Key::from_value(&key) {
            Some(k) => k,
            None => return Err(LuaError::msg("table index is nil")),
        };
        if matches!(val, Value::Nil) {
            t.hash.shift_remove(&k);
        } else {
            t.hash.insert(k, val);
        }
        Ok(())
    }

    pub fn set_str(&self, key: &str, val: Value) {
        let _ = self.set(Value::str(key), val);
    }

    pub fn len(&self) -> usize {
        let t = self.0.borrow();
        let mut n = t.arr.len();
        // border may continue into hash
        while t.hash.contains_key(&Key::Int(n as i64 + 1)) {
            n += 1;
        }
        n
    }

    pub fn push(&self, val: Value) {
        let n = self.len();
        let _ = self.set(Value::Num((n + 1) as f64), val);
    }

    /// Iteration: returns the next (key, value) after `key`.
    pub fn next(&self, key: &Value) -> Result<Option<(Value, Value)>, LuaError> {
        let t = self.0.borrow();
        let mut start_hash_idx = 0usize;
        match key {
            Value::Nil => {
                if let Some(v) = t.arr.first() {
                    return Ok(Some((Value::Num(1.0), v.clone())));
                }
            }
            Value::Num(n) if n.fract() == 0.0 && *n >= 1.0 && (*n as usize) <= t.arr.len() => {
                let idx = *n as usize;
                if idx < t.arr.len() {
                    return Ok(Some((Value::Num((idx + 1) as f64), t.arr[idx].clone())));
                }
            }
            other => {
                let k = Key::from_value(other).ok_or_else(|| LuaError::msg("invalid key to 'next'"))?;
                match t.hash.get_index_of(&k) {
                    Some(i) => start_hash_idx = i + 1,
                    None => return Err(LuaError::msg("invalid key to 'next'")),
                }
            }
        }
        for (k, v) in t.hash.iter().skip(start_hash_idx) {
            if !matches!(v, Value::Nil) {
                return Ok(Some((k.to_value(), v.clone())));
            }
        }
        Ok(None)
    }

    pub fn metatable(&self) -> Option<TableRef> {
        self.0.borrow().meta.clone()
    }

    pub fn set_metatable(&self, m: Option<TableRef>) {
        self.0.borrow_mut().meta = m;
    }
}

// ---------------------------------------------------------------- errors

#[derive(Clone, Debug)]
pub struct LuaError {
    pub value: Value,
    pub traceback: Option<String>,
}

impl LuaError {
    pub fn msg(s: &str) -> Self {
        LuaError {
            value: Value::str(s),
            traceback: None,
        }
    }

    pub fn from_value(v: Value) -> Self {
        LuaError {
            value: v,
            traceback: None,
        }
    }

    pub fn message(&self) -> String {
        match &self.value {
            Value::Str(s) => String::from_utf8_lossy(s).to_string(),
            Value::Nil => "nil".to_string(),
            Value::Num(n) => super::lexer::format_num(*n),
            Value::Bool(b) => b.to_string(),
            Value::Table(_) => "(error object is a table value)".to_string(),
            Value::Func(_) => "(error object is a function value)".to_string(),
        }
    }
}

impl fmt::Display for LuaError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message())
    }
}

impl std::error::Error for LuaError {}
