//! Tree-walking Lua interpreter.

use super::ast::*;
use super::lexer::{format_num, Lexer};
use super::parser::Parser;
use super::value::*;
use std::cell::RefCell;
use std::rc::Rc;

pub struct Interp {
    pub globals: TableRef,
    pub string_meta: TableRef,
    pub depth: usize,
    /// Stack of (chunkname, current line) for error messages.
    pub call_lines: Vec<u32>,
}

enum Flow {
    Normal,
    Break,
    Return(Vec<Value>),
}

struct Frame {
    slots: Vec<Rc<RefCell<Value>>>,
    varargs: Vec<Value>,
    upvals: Vec<Rc<RefCell<Value>>>,
    chunkname: Rc<str>,
}

type LResult<T> = Result<T, LuaError>;

fn rt_err(chunk: &str, line: u32, msg: &str) -> LuaError {
    LuaError::msg(&format!("{}:{}: {}", chunk, line, msg))
}

impl Interp {
    pub fn new() -> Self {
        Interp {
            globals: TableRef::new(),
            string_meta: TableRef::new(),
            depth: 0,
            call_lines: vec![],
        }
    }

    pub fn compile(&self, src: &[u8], chunkname: &str) -> LResult<Rc<FuncProto>> {
        let toks = Lexer::new(src, chunkname).tokenize().map_err(|e| LuaError::msg(&e))?;
        Parser::new(toks, chunkname)
            .parse_chunk()
            .map_err(|e| LuaError::msg(&e))
    }

    pub fn load(&self, src: &[u8], chunkname: &str) -> LResult<Value> {
        let proto = self.compile(src, chunkname)?;
        Ok(Value::Func(Rc::new(Function::Lua(Closure {
            proto,
            upvals: vec![],
        }))))
    }

    pub fn exec(&mut self, src: &[u8], chunkname: &str) -> LResult<Vec<Value>> {
        let f = self.load(src, chunkname)?;
        self.call(&f, vec![])
    }

    pub fn register(&mut self, name: &str, f: impl Fn(&mut Interp, Vec<Value>) -> LResult<Vec<Value>> + 'static) {
        let v = native(name, f);
        self.globals.set_str(name, v);
    }

    // ------------------------------------------------------------ metatables

    pub fn get_metatable(&self, v: &Value) -> Option<TableRef> {
        match v {
            Value::Table(t) => t.metatable(),
            Value::Str(_) => Some(self.string_meta.clone()),
            _ => None,
        }
    }

    fn metamethod(&self, v: &Value, name: &str) -> Option<Value> {
        let mt = self.get_metatable(v)?;
        let m = mt.get_str(name);
        if matches!(m, Value::Nil) {
            None
        } else {
            Some(m)
        }
    }

    pub fn index(&mut self, obj: &Value, key: &Value, line: u32, chunk: &str) -> LResult<Value> {
        let mut obj = obj.clone();
        for _ in 0..100 {
            match &obj {
                Value::Table(t) => {
                    let v = t.get(key);
                    if !matches!(v, Value::Nil) {
                        return Ok(v);
                    }
                    match self.metamethod(&obj, "__index") {
                        None => return Ok(Value::Nil),
                        Some(Value::Func(_)) => {
                            let h = self.metamethod(&obj, "__index").unwrap();
                            let r = self.call(&h, vec![obj.clone(), key.clone()])?;
                            return Ok(r.into_iter().next().unwrap_or(Value::Nil));
                        }
                        Some(h) => obj = h,
                    }
                }
                Value::Str(_) => {
                    let v = self.string_meta.get_str("__index");
                    match v {
                        Value::Table(t) => return Ok(t.get(key)),
                        Value::Func(_) => {
                            let r = self.call(&v, vec![obj.clone(), key.clone()])?;
                            return Ok(r.into_iter().next().unwrap_or(Value::Nil));
                        }
                        _ => return Ok(Value::Nil),
                    }
                }
                other => {
                    let keydesc = match key {
                        Value::Str(s) => format!(" (field '{}')", String::from_utf8_lossy(s)),
                        _ => String::new(),
                    };
                    return Err(rt_err(
                        chunk,
                        line,
                        &format!("attempt to index a {} value{}", other.type_name(), keydesc),
                    ));
                }
            }
        }
        Err(rt_err(chunk, line, "'__index' chain too long; possible loop"))
    }

    pub fn set_index(&mut self, obj: &Value, key: Value, val: Value, line: u32, chunk: &str) -> LResult<()> {
        match obj {
            Value::Table(t) => {
                let existing = t.get(&key);
                if matches!(existing, Value::Nil) {
                    if let Some(h) = self.metamethod(obj, "__newindex") {
                        return match h {
                            Value::Func(_) => {
                                self.call(&h, vec![obj.clone(), key, val])?;
                                Ok(())
                            }
                            other => self.set_index(&other, key, val, line, chunk),
                        };
                    }
                }
                t.set(key, val).map_err(|e| rt_err(chunk, line, &e.message()))
            }
            other => Err(rt_err(
                chunk,
                line,
                &format!("attempt to index a {} value", other.type_name()),
            )),
        }
    }

    // ------------------------------------------------------------ calls

    pub fn call(&mut self, f: &Value, args: Vec<Value>) -> LResult<Vec<Value>> {
        match f {
            Value::Func(func) => {
                if self.depth > 190 {
                    return Err(LuaError::msg("stack overflow"));
                }
                self.depth += 1;
                let r = match func.as_ref() {
                    Function::Native(_, nf) => nf(self, args),
                    Function::Lua(cl) => self.call_closure(cl, args),
                };
                self.depth -= 1;
                r
            }
            other => match self.metamethod(other, "__call") {
                Some(h) => {
                    let mut a = vec![other.clone()];
                    a.extend(args);
                    self.call(&h, a)
                }
                None => Err(LuaError::msg(&format!(
                    "attempt to call a {} value",
                    other.type_name()
                ))),
            },
        }
    }

    fn call_closure(&mut self, cl: &Closure, mut args: Vec<Value>) -> LResult<Vec<Value>> {
        let proto = &cl.proto;
        let mut slots = Vec::with_capacity(proto.nslots);
        for _ in 0..proto.nslots {
            slots.push(Rc::new(RefCell::new(Value::Nil)));
        }
        let varargs = if args.len() > proto.nparams {
            args.split_off(proto.nparams)
        } else {
            vec![]
        };
        for (i, a) in args.into_iter().enumerate() {
            if i < proto.nslots {
                *slots[i].borrow_mut() = a;
            }
        }
        let mut frame = Frame {
            slots,
            varargs: if proto.is_vararg { varargs } else { vec![] },
            upvals: cl.upvals.clone(),
            chunkname: proto.chunkname.clone(),
        };
        match self.exec_block(&proto.body, &mut frame)? {
            Flow::Return(v) => Ok(v),
            _ => Ok(vec![]),
        }
    }

    // ------------------------------------------------------------ statements

    fn exec_block(&mut self, block: &Block, frame: &mut Frame) -> LResult<Flow> {
        for stat in block {
            match self.exec_stat(stat, frame)? {
                Flow::Normal => {}
                other => return Ok(other),
            }
        }
        Ok(Flow::Normal)
    }

    fn exec_stat(&mut self, stat: &Stat, frame: &mut Frame) -> LResult<Flow> {
        match stat {
            Stat::Call(e, _) => {
                self.eval_multi(e, frame)?;
                Ok(Flow::Normal)
            }
            Stat::Local(slots, exprs, _) => {
                let vals = self.eval_list(exprs, slots.len(), frame)?;
                for (slot, v) in slots.iter().zip(vals.into_iter()) {
                    frame.slots[*slot] = Rc::new(RefCell::new(v));
                }
                Ok(Flow::Normal)
            }
            Stat::LocalFunction(slot, proto) => {
                frame.slots[*slot] = Rc::new(RefCell::new(Value::Nil));
                let f = self.make_closure(proto, frame);
                *frame.slots[*slot].borrow_mut() = f;
                Ok(Flow::Normal)
            }
            Stat::Assign(targets, exprs, line) => {
                // evaluate table/key of targets first, then values
                let mut prepared: Vec<(Option<Value>, Option<Value>)> = Vec::new();
                for t in targets {
                    if let Expr::Index(obj, key, _) = t {
                        let o = self.eval(obj, frame)?;
                        let k = self.eval(key, frame)?;
                        prepared.push((Some(o), Some(k)));
                    } else {
                        prepared.push((None, None));
                    }
                }
                let vals = self.eval_list(exprs, targets.len(), frame)?;
                for ((t, v), (o, k)) in targets.iter().zip(vals.into_iter()).zip(prepared.into_iter()) {
                    match t {
                        Expr::Local(s) => *frame.slots[*s].borrow_mut() = v,
                        Expr::Upval(u) => *frame.upvals[*u].borrow_mut() = v,
                        Expr::Global(name) => {
                            let g = Value::Table(self.globals.clone());
                            self.set_index(&g, Value::str(name), v, *line, &frame.chunkname)?;
                        }
                        Expr::Index(..) => {
                            let chunk = frame.chunkname.clone();
                            self.set_index(&o.unwrap(), k.unwrap(), v, *line, &chunk)?;
                        }
                        _ => return Err(rt_err(&frame.chunkname, *line, "cannot assign")),
                    }
                }
                Ok(Flow::Normal)
            }
            Stat::Do(block) => self.exec_block(block, frame),
            Stat::While(cond, body) => {
                loop {
                    if !self.eval(cond, frame)?.truthy() {
                        break;
                    }
                    match self.exec_block(body, frame)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        r @ Flow::Return(_) => return Ok(r),
                    }
                }
                Ok(Flow::Normal)
            }
            Stat::Repeat(body, cond) => {
                loop {
                    match self.exec_block(body, frame)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        r @ Flow::Return(_) => return Ok(r),
                    }
                    if self.eval(cond, frame)?.truthy() {
                        break;
                    }
                }
                Ok(Flow::Normal)
            }
            Stat::If(clauses, else_block) => {
                for (cond, body) in clauses {
                    if self.eval(cond, frame)?.truthy() {
                        return self.exec_block(body, frame);
                    }
                }
                if let Some(b) = else_block {
                    return self.exec_block(b, frame);
                }
                Ok(Flow::Normal)
            }
            Stat::NumFor {
                var,
                start,
                limit,
                step,
                body,
                line,
            } => {
                let chunk = frame.chunkname.clone();
                let s = self.eval(start, frame)?;
                let l = self.eval(limit, frame)?;
                let st = match step {
                    Some(e) => self.eval(e, frame)?,
                    None => Value::Num(1.0),
                };
                let s = s.as_num().ok_or_else(|| rt_err(&chunk, *line, "'for' initial value must be a number"))?;
                let l = l.as_num().ok_or_else(|| rt_err(&chunk, *line, "'for' limit must be a number"))?;
                let st = st.as_num().ok_or_else(|| rt_err(&chunk, *line, "'for' step must be a number"))?;
                if st == 0.0 {
                    return Err(rt_err(&chunk, *line, "'for' step is zero"));
                }
                let mut i = s;
                loop {
                    if (st > 0.0 && i > l) || (st < 0.0 && i < l) {
                        break;
                    }
                    frame.slots[*var] = Rc::new(RefCell::new(Value::Num(i)));
                    match self.exec_block(body, frame)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        r @ Flow::Return(_) => return Ok(r),
                    }
                    i += st;
                }
                Ok(Flow::Normal)
            }
            Stat::GenFor {
                vars,
                exprs,
                body,
                line,
            } => {
                let chunk = frame.chunkname.clone();
                let init = self.eval_list(exprs, 3, frame)?;
                let f = init[0].clone();
                let s = init[1].clone();
                let mut ctrl = init[2].clone();
                loop {
                    let rets = self
                        .call(&f, vec![s.clone(), ctrl.clone()])
                        .map_err(|e| self.add_pos(e, &chunk, *line))?;
                    let first = rets.first().cloned().unwrap_or(Value::Nil);
                    if matches!(first, Value::Nil) {
                        break;
                    }
                    ctrl = first;
                    for (i, slot) in vars.iter().enumerate() {
                        frame.slots[*slot] =
                            Rc::new(RefCell::new(rets.get(i).cloned().unwrap_or(Value::Nil)));
                    }
                    match self.exec_block(body, frame)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        r @ Flow::Return(_) => return Ok(r),
                    }
                }
                Ok(Flow::Normal)
            }
            Stat::Return(exprs, _) => {
                let vals = self.eval_list_multi(exprs, frame)?;
                Ok(Flow::Return(vals))
            }
            Stat::Break => Ok(Flow::Break),
        }
    }

    fn add_pos(&self, e: LuaError, chunk: &str, line: u32) -> LuaError {
        // Only decorate plain string messages without position info.
        if let Value::Str(s) = &e.value {
            let m = String::from_utf8_lossy(s);
            if !m.contains(':') || e.traceback.is_some() {
                return LuaError {
                    value: Value::str(&format!("{}:{}: {}", chunk, line, m)),
                    traceback: e.traceback,
                };
            }
        }
        e
    }

    fn make_closure(&self, proto: &Rc<FuncProto>, frame: &Frame) -> Value {
        let upvals = proto
            .upvals
            .iter()
            .map(|d| {
                if d.from_parent_local {
                    frame.slots[d.index].clone()
                } else {
                    frame.upvals[d.index].clone()
                }
            })
            .collect();
        Value::Func(Rc::new(Function::Lua(Closure {
            proto: proto.clone(),
            upvals,
        })))
    }

    // ------------------------------------------------------------ expressions

    /// Evaluate a list of expressions, adjusting to exactly `n` values.
    fn eval_list(&mut self, exprs: &[Expr], n: usize, frame: &mut Frame) -> LResult<Vec<Value>> {
        let mut out = self.eval_list_multi(exprs, frame)?;
        out.resize(n, Value::Nil);
        Ok(out)
    }

    /// Evaluate a list of expressions keeping all values of the last one.
    fn eval_list_multi(&mut self, exprs: &[Expr], frame: &mut Frame) -> LResult<Vec<Value>> {
        let mut out = Vec::new();
        for (i, e) in exprs.iter().enumerate() {
            if i + 1 == exprs.len() {
                out.extend(self.eval_multi(e, frame)?);
            } else {
                out.push(self.eval(e, frame)?);
            }
        }
        Ok(out)
    }

    fn eval_multi(&mut self, e: &Expr, frame: &mut Frame) -> LResult<Vec<Value>> {
        match e {
            Expr::Call(fe, args, line) => {
                let f = self.eval(fe, frame)?;
                let a = self.eval_list_multi(args, frame)?;
                let chunk = frame.chunkname.clone();
                self.call(&f, a).map_err(|err| self.decorate_call_error(err, fe, &chunk, *line))
            }
            Expr::Method(obj, name, args, line) => {
                let o = self.eval(obj, frame)?;
                let chunk = frame.chunkname.clone();
                let f = self.index(&o, &Value::str(name), *line, &chunk)?;
                let mut a = vec![o];
                a.extend(self.eval_list_multi(args, frame)?);
                if matches!(f, Value::Nil) {
                    return Err(rt_err(
                        &chunk,
                        *line,
                        &format!("attempt to call method '{}' (a nil value)", name),
                    ));
                }
                self.call(&f, a).map_err(|err| self.add_pos(err, &chunk, *line))
            }
            Expr::Vararg => Ok(frame.varargs.clone()),
            other => Ok(vec![self.eval(other, frame)?]),
        }
    }

    fn decorate_call_error(&self, err: LuaError, fe: &Expr, chunk: &str, line: u32) -> LuaError {
        let msg = err.message();
        if msg.starts_with("attempt to call a ") && err.traceback.is_none() {
            let what = match fe {
                Expr::Global(n) => format!(" (global '{}')", n),
                Expr::Local(_) | Expr::Upval(_) => String::new(),
                Expr::Index(_, k, _) => match k.as_ref() {
                    Expr::Str(s) => format!(" (field '{}')", String::from_utf8_lossy(s)),
                    _ => String::new(),
                },
                _ => String::new(),
            };
            return LuaError {
                value: Value::str(&format!("{}:{}: {}{}", chunk, line, msg, what)),
                traceback: err.traceback,
            };
        }
        self.add_pos(err, chunk, line)
    }

    pub fn eval(&mut self, e: &Expr, frame: &mut Frame) -> LResult<Value> {
        match e {
            Expr::Nil => Ok(Value::Nil),
            Expr::True => Ok(Value::Bool(true)),
            Expr::False => Ok(Value::Bool(false)),
            Expr::Num(n) => Ok(Value::Num(*n)),
            Expr::Str(s) => Ok(Value::Str(s.clone())),
            Expr::Vararg => Ok(frame.varargs.first().cloned().unwrap_or(Value::Nil)),
            Expr::Local(s) => Ok(frame.slots[*s].borrow().clone()),
            Expr::Upval(u) => Ok(frame.upvals[*u].borrow().clone()),
            Expr::Global(name) => Ok(self.globals.get_str(name)),
            Expr::Index(obj, key, line) => {
                let o = self.eval(obj, frame)?;
                let k = self.eval(key, frame)?;
                let chunk = frame.chunkname.clone();
                self.index(&o, &k, *line, &chunk).map_err(|e| {
                    // add variable name context
                    if let Expr::Global(n) = obj.as_ref() {
                        let m = e.message();
                        if m.contains("attempt to index") && !m.contains("(global") {
                            return LuaError::msg(&format!("{} (global '{}')", m.trim_end_matches(|c| c != ')').trim_end_matches(')').trim_end_matches(|c: char| c == ' ' || c == '('), n));
                        }
                    }
                    e
                })
            }
            Expr::Call(..) | Expr::Method(..) => {
                Ok(self.eval_multi(e, frame)?.into_iter().next().unwrap_or(Value::Nil))
            }
            Expr::Function(proto) => Ok(self.make_closure(proto, frame)),
            Expr::Paren(inner) => self.eval(inner, frame),
            Expr::And(a, b) => {
                let l = self.eval(a, frame)?;
                if l.truthy() {
                    self.eval(b, frame)
                } else {
                    Ok(l)
                }
            }
            Expr::Or(a, b) => {
                let l = self.eval(a, frame)?;
                if l.truthy() {
                    Ok(l)
                } else {
                    self.eval(b, frame)
                }
            }
            Expr::Un(op, inner, line) => {
                let v = self.eval(inner, frame)?;
                let chunk = frame.chunkname.clone();
                match op {
                    UnOp::Not => Ok(Value::Bool(!v.truthy())),
                    UnOp::Neg => match v.as_num() {
                        Some(n) => Ok(Value::Num(-n)),
                        None => match self.metamethod(&v, "__unm") {
                            Some(h) => Ok(self.call(&h, vec![v.clone(), v])?.into_iter().next().unwrap_or(Value::Nil)),
                            None => Err(rt_err(
                                &chunk,
                                *line,
                                &format!("attempt to perform arithmetic on a {} value", v.type_name()),
                            )),
                        },
                    },
                    UnOp::Len => match &v {
                        Value::Str(s) => Ok(Value::Num(s.len() as f64)),
                        Value::Table(t) => {
                            if let Some(h) = self.metamethod(&v, "__len") {
                                Ok(self.call(&h, vec![v.clone()])?.into_iter().next().unwrap_or(Value::Nil))
                            } else {
                                Ok(Value::Num(t.len() as f64))
                            }
                        }
                        other => Err(rt_err(
                            &chunk,
                            *line,
                            &format!("attempt to get length of a {} value", other.type_name()),
                        )),
                    },
                }
            }
            Expr::Bin(op, a, b, line) => {
                let l = self.eval(a, frame)?;
                let r = self.eval(b, frame)?;
                let chunk = frame.chunkname.clone();
                self.binop(*op, l, r, *line, &chunk)
            }
            Expr::Table(items, line) => {
                let t = TableRef::new();
                let chunk = frame.chunkname.clone();
                let mut pos = 1usize;
                for (i, item) in items.iter().enumerate() {
                    match item {
                        TableItem::Pos(e) => {
                            if i + 1 == items.len() {
                                for v in self.eval_multi(e, frame)? {
                                    t.set(Value::Num(pos as f64), v)
                                        .map_err(|e| rt_err(&chunk, *line, &e.message()))?;
                                    pos += 1;
                                }
                            } else {
                                let v = self.eval(e, frame)?;
                                t.set(Value::Num(pos as f64), v)
                                    .map_err(|e| rt_err(&chunk, *line, &e.message()))?;
                                pos += 1;
                            }
                        }
                        TableItem::Named(k, v) => {
                            let kv = self.eval(k, frame)?;
                            let vv = self.eval(v, frame)?;
                            if matches!(kv, Value::Nil) {
                                return Err(rt_err(&chunk, *line, "table index is nil"));
                            }
                            t.set(kv, vv).map_err(|e| rt_err(&chunk, *line, &e.message()))?;
                        }
                    }
                }
                Ok(Value::Table(t))
            }
        }
    }

    fn arith_meta(&mut self, name: &str, l: &Value, r: &Value) -> Option<LResult<Value>> {
        let h = self.metamethod(l, name).or_else(|| self.metamethod(r, name))?;
        Some(
            self.call(&h, vec![l.clone(), r.clone()])
                .map(|v| v.into_iter().next().unwrap_or(Value::Nil)),
        )
    }

    pub fn binop(&mut self, op: BinOp, l: Value, r: Value, line: u32, chunk: &str) -> LResult<Value> {
        use BinOp::*;
        match op {
            Add | Sub | Mul | Div | Mod | Pow => {
                let (ln, rn) = (l.as_num(), r.as_num());
                match (ln, rn) {
                    (Some(a), Some(b)) => Ok(Value::Num(match op {
                        Add => a + b,
                        Sub => a - b,
                        Mul => a * b,
                        Div => a / b,
                        Mod => {
                            let m = a % b;
                            if m != 0.0 && (m < 0.0) != (b < 0.0) {
                                m + b
                            } else {
                                m
                            }
                        }
                        Pow => a.powf(b),
                        _ => unreachable!(),
                    })),
                    _ => {
                        let name = match op {
                            Add => "__add",
                            Sub => "__sub",
                            Mul => "__mul",
                            Div => "__div",
                            Mod => "__mod",
                            Pow => "__pow",
                            _ => unreachable!(),
                        };
                        match self.arith_meta(name, &l, &r) {
                            Some(v) => v,
                            None => {
                                let bad = if ln.is_none() { &l } else { &r };
                                Err(rt_err(
                                    chunk,
                                    line,
                                    &format!("attempt to perform arithmetic on a {} value", bad.type_name()),
                                ))
                            }
                        }
                    }
                }
            }
            Concat => match (&l, &r) {
                (Value::Str(_) | Value::Num(_), Value::Str(_) | Value::Num(_)) => {
                    let mut out = tostring_basic(&l);
                    out.extend_from_slice(&tostring_basic(&r));
                    Ok(Value::Str(Rc::from(out)))
                }
                _ => match self.arith_meta("__concat", &l, &r) {
                    Some(v) => v,
                    None => {
                        let bad = if matches!(l, Value::Str(_) | Value::Num(_)) { &r } else { &l };
                        Err(rt_err(
                            chunk,
                            line,
                            &format!("attempt to concatenate a {} value", bad.type_name()),
                        ))
                    }
                },
            },
            Eq => Ok(Value::Bool(self.values_equal(&l, &r)?)),
            Ne => Ok(Value::Bool(!self.values_equal(&l, &r)?)),
            Lt | Le | Gt | Ge => {
                let (a, b, flip) = match op {
                    Lt => (&l, &r, false),
                    Le => (&l, &r, false),
                    Gt => (&r, &l, false),
                    _ => (&r, &l, false),
                };
                let _ = flip;
                let le = matches!(op, Le | Ge);
                match (a, b) {
                    (Value::Num(x), Value::Num(y)) => Ok(Value::Bool(if le { x <= y } else { x < y })),
                    (Value::Str(x), Value::Str(y)) => Ok(Value::Bool(if le { x <= y } else { x < y })),
                    _ => {
                        let name = if le { "__le" } else { "__lt" };
                        match self.arith_meta(name, a, b) {
                            Some(v) => Ok(Value::Bool(v?.truthy())),
                            None => {
                                let (t1, t2) = (a.type_name(), b.type_name());
                                if t1 == t2 {
                                    Err(rt_err(chunk, line, &format!("attempt to compare two {} values", t1)))
                                } else {
                                    Err(rt_err(chunk, line, &format!("attempt to compare {} with {}", t1, t2)))
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    pub fn values_equal(&mut self, l: &Value, r: &Value) -> LResult<bool> {
        if l.raw_eq(r) {
            return Ok(true);
        }
        if let (Value::Table(_), Value::Table(_)) = (l, r) {
            if let Some(h) = self.metamethod(l, "__eq") {
                let v = self.call(&h, vec![l.clone(), r.clone()])?;
                return Ok(v.into_iter().next().unwrap_or(Value::Nil).truthy());
            }
        }
        Ok(false)
    }

    /// `tostring` honouring `__tostring`.
    pub fn tostring(&mut self, v: &Value) -> LResult<Vec<u8>> {
        if let Some(h) = self.metamethod(v, "__tostring") {
            let r = self.call(&h, vec![v.clone()])?;
            return Ok(tostring_basic(&r.into_iter().next().unwrap_or(Value::Nil)));
        }
        Ok(tostring_basic(v))
    }
}

pub fn tostring_basic(v: &Value) -> Vec<u8> {
    match v {
        Value::Nil => b"nil".to_vec(),
        Value::Bool(b) => b.to_string().into_bytes(),
        Value::Num(n) => format_num(*n).into_bytes(),
        Value::Str(s) => s.to_vec(),
        Value::Table(t) => format!("table: {:p}", Rc::as_ptr(&t.0)).into_bytes(),
        Value::Func(f) => format!("function: {:p}", Rc::as_ptr(f) as *const u8).into_bytes(),
    }
}

pub fn native(name: &str, f: impl Fn(&mut Interp, Vec<Value>) -> LResult<Vec<Value>> + 'static) -> Value {
    Value::Func(Rc::new(Function::Native(name.to_string(), Rc::new(f))))
}

/// Helper for argument access in native functions.
pub fn arg(args: &[Value], i: usize) -> Value {
    args.get(i).cloned().unwrap_or(Value::Nil)
}

pub fn arg_str(args: &[Value], i: usize, fname: &str) -> LResult<Vec<u8>> {
    match args.get(i) {
        Some(Value::Str(s)) => Ok(s.to_vec()),
        Some(Value::Num(n)) => Ok(format_num(*n).into_bytes()),
        Some(other) => Err(LuaError::msg(&format!(
            "bad argument #{} to '{}' (string expected, got {})",
            i + 1,
            fname,
            other.type_name()
        ))),
        None => Err(LuaError::msg(&format!(
            "bad argument #{} to '{}' (string expected, got no value)",
            i + 1,
            fname
        ))),
    }
}

pub fn arg_string(args: &[Value], i: usize, fname: &str) -> LResult<String> {
    arg_str(args, i, fname).map(|b| String::from_utf8_lossy(&b).to_string())
}

pub fn arg_num(args: &[Value], i: usize, fname: &str) -> LResult<f64> {
    match args.get(i) {
        Some(v) => v.as_num().ok_or_else(|| {
            LuaError::msg(&format!(
                "bad argument #{} to '{}' (number expected, got {})",
                i + 1,
                fname,
                v.type_name()
            ))
        }),
        None => Err(LuaError::msg(&format!(
            "bad argument #{} to '{}' (number expected, got no value)",
            i + 1,
            fname
        ))),
    }
}

pub fn arg_opt_num(args: &[Value], i: usize, fname: &str, default: f64) -> LResult<f64> {
    match args.get(i) {
        None | Some(Value::Nil) => Ok(default),
        _ => arg_num(args, i, fname),
    }
}

pub fn arg_table(args: &[Value], i: usize, fname: &str) -> LResult<TableRef> {
    match args.get(i) {
        Some(Value::Table(t)) => Ok(t.clone()),
        Some(other) => Err(LuaError::msg(&format!(
            "bad argument #{} to '{}' (table expected, got {})",
            i + 1,
            fname,
            other.type_name()
        ))),
        None => Err(LuaError::msg(&format!(
            "bad argument #{} to '{}' (table expected, got no value)",
            i + 1,
            fname
        ))),
    }
}
EOF
echo ok"}

