//! Lua pattern matching (port of the classic `lstrlib` matcher).

const MAXCAPTURES: usize = 32;
const CAP_UNFINISHED: isize = -1;
const CAP_POSITION: isize = -2;
const L_ESC: u8 = b'%';

#[derive(Clone, Copy)]
struct Capture {
