    len: isize,
}

pub struct MatchState<'a> {
    src: &'a [u8],
    pat: &'a [u8],
    level: usize,
    capture: [Capture; MAXCAPTURES],
    matchdepth: usize,
}

#[derive(Debug, Clone)]
pub enum Cap {
    Str(Vec<u8>),
    Pos(usize),
}

impl<'a> MatchState<'a> {
    pub fn new(src: &'a [u8], pat: &'a [u8]) -> Self {
        MatchState {
            src,
            pat,
            level: 0,
            capture: [Capture { init: 0, len: 0 }; MAXCAPTURES],
            matchdepth: 0,
        }
    }

    fn reset(&mut self) {
        self.level = 0;
        self.matchdepth = 0;
    }

    fn class_end(&self, mut p: usize) -> Result<usize, String> {
        let c = self.pat[p];
        p += 1;
        if c == L_ESC {
            if p >= self.pat.len() {
                return Err("malformed pattern (ends with '%')".into());
            }
            return Ok(p + 1);
        }
        if c == b'[' {
            if p < self.pat.len() && self.pat[p] == b'^' {
                p += 1;
            }
            loop {
                if p >= self.pat.len() {
                    return Err("malformed pattern (missing ']')".into());
                }
                let cc = self.pat[p];
                p += 1;
                if cc == L_ESC {
                    if p >= self.pat.len() {
                        return Err("malformed pattern (missing ']')".into());
                    }
                    p += 1;
                }
                if p < self.pat.len() && self.pat[p] == b']' {
                    return Ok(p + 1);
                }
                if p >= self.pat.len() {
                    return Err("malformed pattern (missing ']')".into());
                }
            }
        }
        Ok(p)
    }

    fn single_match(&self, s: usize, p: usize, ep: usize) -> bool {
        if s >= self.src.len() {
            return false;
        }
        let c = self.src[s];
        match self.pat[p] {
            b'.' => true,
            L_ESC => match_class(c, self.pat[p + 1]),
            b'[' => match_bracket_class(c, &self.pat[p..ep - 1]),
            pc => pc == c,
        }
    }

    fn match_balance(&self, s: usize, p: usize) -> Result<Option<usize>, String> {
        if p + 1 >= self.pat.len() {
            return Err("malformed pattern (missing arguments to '%b')".into());
        }
        if s >= self.src.len() || self.src[s] != self.pat[p] {
            return Ok(None);
        }
        let b = self.pat[p];
        let e = self.pat[p + 1];
        let mut cont = 1;
        let mut s = s + 1;
        while s < self.src.len() {
            let c = self.src[s];
            if c == e {
                cont -= 1;
                if cont == 0 {
                    return Ok(Some(s + 1));
                }
            } else if c == b {
                cont += 1;
            }
            s += 1;
        }
        Ok(None)
    }

    fn max_expand(&mut self, s: usize, p: usize, ep: usize) -> Result<Option<usize>, String> {
        let mut i = 0usize;
        while self.single_match(s + i, p, ep) {
            i += 1;
        }
        loop {
            if let Some(r) = self.do_match(s + i, ep + 1)? {
                return Ok(Some(r));
            }
            if i == 0 {
                return Ok(None);
            }
            i -= 1;
        }
    }

    fn min_expand(&mut self, mut s: usize, p: usize, ep: usize) -> Result<Option<usize>, String> {
        loop {
            if let Some(r) = self.do_match(s, ep + 1)? {
                return Ok(Some(r));
            }
            if self.single_match(s, p, ep) {
                s += 1;
            } else {
                return Ok(None);
            }
        }
    }

    fn start_capture(&mut self, s: usize, p: usize, what: isize) -> Result<Option<usize>, String> {
        if self.level >= MAXCAPTURES {
            return Err("too many captures".into());
        }
        self.capture[self.level] = Capture { init: s, len: what };
        self.level += 1;
        let r = self.do_match(s, p)?;
        if r.is_none() {
            self.level -= 1;
        }
        Ok(r)
    }

    fn end_capture(&mut self, s: usize, p: usize) -> Result<Option<usize>, String> {
        let l = self.capture_to_close()?;
        self.capture[l].len = (s - self.capture[l].init) as isize;
        let r = self.do_match(s, p)?;
        if r.is_none() {
            self.capture[l].len = CAP_UNFINISHED;
        }
        Ok(r)
    }

    fn capture_to_close(&self) -> Result<usize, String> {
        let mut level = self.level as isize - 1;
        while level >= 0 {
            if self.capture[level as usize].len == CAP_UNFINISHED {
                return Ok(level as usize);
            }
            level -= 1;
        }
        Err("invalid pattern capture".into())
    }

    fn check_capture(&self, l: u8) -> Result<usize, String> {
        let l = l as isize - b'1' as isize;
        if l < 0 || l as usize >= self.level || self.capture[l as usize].len == CAP_UNFINISHED {
            return Err(format!("invalid capture index %{}", l + 1));
        }
        Ok(l as usize)
    }

    fn match_capture(&self, s: usize, l: u8) -> Result<Option<usize>, String> {
        let l = self.check_capture(l)?;
        let len = self.capture[l].len as usize;
        let init = self.capture[l].init;
        if self.src.len() - s >= len && self.src[init..init + len] == self.src[s..s + len] {
            Ok(Some(s + len))
        } else {
            Ok(None)
        }
    }

    pub fn do_match(&mut self, mut s: usize, mut p: usize) -> Result<Option<usize>, String> {
        self.matchdepth += 1;
        if self.matchdepth > 200 {
            return Err("pattern too complex".into());
        }
        let result = loop {
            if p >= self.pat.len() {
                break Some(s);
            }
            match self.pat[p] {
                b'(' => {
                    break if p + 1 < self.pat.len() && self.pat[p + 1] == b')' {
                        self.start_capture(s, p + 2, CAP_POSITION)?
                    } else {
                        self.start_capture(s, p + 1, CAP_UNFINISHED)?
                    };
                }
                b')' => break self.end_capture(s, p + 1)?,
                b'$' if p + 1 == self.pat.len() => {
                    break if s == self.src.len() { Some(s) } else { None };
                }
                L_ESC if p + 1 < self.pat.len() && self.pat[p + 1] == b'b' => {
                    match self.match_balance(s, p + 2)? {
                        Some(ns) => {
                            s = ns;
                            p += 4;
                            continue;
                        }
                        None => break None,
                    }
                }
                L_ESC if p + 1 < self.pat.len() && self.pat[p + 1] == b'f' => {
                    p += 2;
                    if p >= self.pat.len() || self.pat[p] != b'[' {
                        return Err("missing '[' after '%f' in pattern".into());
                    }
                    let ep = self.class_end(p)?;
                    let previous = if s == 0 { 0 } else { self.src[s - 1] };
                    let current = if s < self.src.len() { self.src[s] } else { 0 };
                    if !match_bracket_class(previous, &self.pat[p..ep - 1])
                        && match_bracket_class(current, &self.pat[p..ep - 1])
                    {
                        p = ep;
                        continue;
                    }
                    break None;
                }
                L_ESC if p + 1 < self.pat.len() && self.pat[p + 1].is_ascii_digit() => {
                    match self.match_capture(s, self.pat[p + 1])? {
                        Some(ns) => {
                            s = ns;
                            p += 2;
                            continue;
                        }
                        None => break None,
                    }
                }
                _ => {
                    let ep = self.class_end(p)?;
                    let epc = if ep < self.pat.len() { self.pat[ep] } else { 0 };
                    if !self.single_match(s, p, ep) {
                        if epc == b'*' || epc == b'?' || epc == b'-' {
                            p = ep + 1;
                            continue;
                        }
                        break None;
                    }
                    match epc {
                        b'?' => {
                            if let Some(r) = self.do_match(s + 1, ep + 1)? {
                                break Some(r);
                            }
                            p = ep + 1;
                            continue;
                        }
                        b'+' => break self.max_expand(s + 1, p, ep)?,
                        b'*' => break self.max_expand(s, p, ep)?,
                        b'-' => break self.min_expand(s, p, ep)?,
                        _ => {
                            s += 1;
                            p = ep;
                            continue;
                        }
                    }
                }
            }
        };
        self.matchdepth -= 1;
        Ok(result)
    }

    pub fn get_capture(&self, i: usize, s: usize, e: usize) -> Result<Cap, String> {
        if i >= self.level {
            if i == 0 {
                return Ok(Cap::Str(self.src[s..e].to_vec()));
            }
            return Err(format!("invalid capture index %{}", i + 1));
        }
        let c = self.capture[i];
        if c.len == CAP_UNFINISHED {
            return Err("unfinished capture".into());
        }
        if c.len == CAP_POSITION {
            return Ok(Cap::Pos(c.init + 1));
        }
        Ok(Cap::Str(self.src[c.init..c.init + c.len as usize].to_vec()))
    }

    pub fn captures(&self, s: usize, e: usize, whole_if_none: bool) -> Result<Vec<Cap>, String> {
        let n = if self.level == 0 && whole_if_none { 1 } else { self.level };
        (0..n).map(|i| self.get_capture(i, s, e)).collect()
    }

    pub fn level(&self) -> usize {
        self.level
    }
}

fn match_class(c: u8, cl: u8) -> bool {
    let res = match cl.to_ascii_lowercase() {
        b'a' => c.is_ascii_alphabetic(),
        b'c' => c.is_ascii_control(),
        b'd' => c.is_ascii_digit(),
        b'g' => c.is_ascii_graphic(),
        b'l' => c.is_ascii_lowercase(),
        b'p' => c.is_ascii_punctuation(),
        b's' => c == b' ' || (0x09..=0x0d).contains(&c),
        b'u' => c.is_ascii_uppercase(),
        b'w' => c.is_ascii_alphanumeric(),
        b'x' => c.is_ascii_hexdigit(),
        _ => return cl == c,
    };
    if cl.is_ascii_uppercase() {
        !res
    } else {
        res
    }
}

fn match_bracket_class(c: u8, class: &[u8]) -> bool {
    // class includes the leading '[' and excludes the closing ']'
    let mut p = 1;
    let mut sig = true;
    if p < class.len() && class[p] == b'^' {
        sig = false;
        p += 1;
    }
    while p < class.len() {
        if class[p] == L_ESC {
            p += 1;
            if p < class.len() && match_class(c, class[p]) {
                return sig;
            }
            p += 1;
        } else if p + 2 < class.len() && class[p + 1] == b'-' {
            if class[p] <= c && c <= class[p + 2] {
                return sig;
            }
            p += 3;
        } else {
            if class[p] == c {
                return sig;
            }
            p += 1;
        }
    }
    !sig
}

/// Find the first match of `pat` in `src` starting at byte `init`.
/// Returns (start, end, captures).
pub fn find(src: &[u8], pat: &[u8], init: usize) -> Result<Option<(usize, usize, Vec<Cap>)>, String> {
    let anchor = pat.first() == Some(&b'^');
    let pstart = if anchor { 1 } else { 0 };
    let mut ms = MatchState::new(src, pat);
    let mut s = init;
    loop {
        ms.reset();
        if let Some(e) = ms.do_match(s, pstart)? {
            let caps = ms.captures(s, e, false)?;
            return Ok(Some((s, e, caps)));
        }
        s += 1;
        if anchor || s > src.len() {
            return Ok(None);
        }
    }
}

/// Iterate all matches (for gmatch/gsub).
pub struct Matches<'a> {
    src: &'a [u8],
    pat: &'a [u8],
    pos: usize,
    anchor: bool,
    done: bool,
}

impl<'a> Matches<'a> {
    pub fn new(src: &'a [u8], pat: &'a [u8]) -> Self {
        let anchor = pat.first() == Some(&b'^');
        Matches {
            src,
            pat,
            pos: 0,
            anchor,
            done: false,
        }
    }

    /// Next match: (start, end, captures(whole if none)).
    pub fn next_match(&mut self) -> Result<Option<(usize, usize, Vec<Cap>)>, String> {
        if self.done {
            return Ok(None);
        }
        let pstart = if self.anchor { 1 } else { 0 };
        while self.pos <= self.src.len() {
            let mut ms = MatchState::new(self.src, self.pat);
            if let Some(e) = ms.do_match(self.pos, pstart)? {
                let caps = ms.captures(self.pos, e, true)?;
                let start = self.pos;
                if e == self.pos {
                    self.pos += 1;
                } else {
                    self.pos = e;
                }
                if self.anchor {
                    self.done = true;
                }
                return Ok(Some((start, e, caps)));
            }
            if self.anchor {
                self.done = true;
                return Ok(None);
            }
            self.pos += 1;
        }
        self.done = true;
        Ok(None)
    }
}
