    let mut p = 1;
    let mut sig = true;
    if p < class.len() && class[p] == b'^' {
        sig = false;
        p += 1;
    }
    while p < class.len() {
        if class[p] == L_ESC {
            p += 1;
            if p < class.len() && match_class(c, class[p]) {
                return sig;
            }
            p += 1;
        } else if p + 2 < class.len() && class[p + 1] == b'-' {
            if class[p] <= c && c <= class[p + 2] {
                return sig;
            }
            p += 3;
        } else {
            if class[p] == c {
                return sig;
            }
            p += 1;
        }
    }
    !sig
}

/// Find the first match of `pat` in `src` starting at byte `init`.
/// Returns (start, end, captures).
pub fn find(src: &[u8], pat: &[u8], init: usize) -> Result<Option<(usize, usize, Vec<Cap>)>, String> {
    let anchor = pat.first() == Some(&b'^');
    let pstart = if anchor { 1 } else { 0 };
    let mut ms = MatchState::new(src, pat);
    let mut s = init;
    loop {
        ms.reset();
        if let Some(e) = ms.do_match(s, pstart)? {
            let caps = ms.captures(s, e, false)?;
            return Ok(Some((s, e, caps)));
        }
        s += 1;
        if anchor || s > src.len() {
            return Ok(None);
        }
    }
}

/// Iterate all matches (for gmatch/gsub).
pub struct Matches<'a> {
    src: &'a [u8],
    pat: &'a [u8],
    pos: usize,
    anchor: bool,
    done: bool,
}

impl<'a> Matches<'a> {
    pub fn new(src: &'a [u8], pat: &'a [u8]) -> Self {
        let anchor = pat.first() == Some(&b'^');
        Matches {
            src,
            pat,
            pos: 0,
            anchor,
            done: false,
        }
    }

    /// Next match: (start, end, captures(whole if none)).
    pub fn next_match(&mut self) -> Result<Option<(usize, usize, Vec<Cap>)>, String> {
        if self.done {
            return Ok(None);
        }
        let pstart = if self.anchor { 1 } else { 0 };
        while self.pos <= self.src.len() {
            let mut ms = MatchState::new(self.src, self.pat);
            if let Some(e) = ms.do_match(self.pos, pstart)? {
                let caps = ms.captures(self.pos, e, true)?;
                let start = self.pos;
                if e == self.pos {
                    self.pos += 1;
                } else {
                    self.pos = e;
                }
                if self.anchor {
                    self.done = true;
                }
                return Ok(Some((start, e, caps)));
            }
            if self.anchor {
                self.done = true;
                return Ok(None);
            }
            self.pos += 1;
        }
        self.done = true;
        Ok(None)
    }
}
