//! Lua standard library subset.

use super::interp::*;
use super::lexer::{format_g, format_num};
use super::lpattern::{self, Cap};
use super::value::*;
use std::cell::RefCell;
use std::rc::Rc;

type LResult<T> = Result<T, LuaError>;

fn ok1(v: Value) -> LResult<Vec<Value>> {
    Ok(vec![v])
}

pub fn open_libs(it: &mut Interp) {
    open_base(it);
    open_string(it);
    open_table(it);
    open_math(it);
    open_os(it);
    open_io(it);
