// ---------------------------------------------------------------- base

fn open_base(it: &mut Interp) {
    it.register("print", |it, args| {
        let mut parts: Vec<Vec<u8>> = Vec::new();
        for a in &args {
            parts.push(it.tostring(a)?);
        }
        let mut out = Vec::new();
        for (i, p) in parts.iter().enumerate() {
            if i > 0 {
                out.push(b'\t');
            }
            out.extend_from_slice(p);
        }
        out.push(b'\n');
        use std::io::Write;
        let _ = std::io::stdout().write_all(&out);
        let _ = std::io::stdout().flush();
        Ok(vec![])
    });
    it.register("type", |_, args| {
        if args.is_empty() {
            return Err(LuaError::msg("bad argument #1 to 'type' (value expected)"));
        }
        ok1(Value::str(args[0].type_name()))
    });
    it.register("tostring", |it, args| {
        let v = arg(&args, 0);
        ok1(Value::Str(Rc::from(it.tostring(&v)?)))
    });
    it.register("tonumber", |_, args| {
        let v = arg(&args, 0);
        let base = arg(&args, 1);
        match base {
            Value::Nil => ok1(match v.as_num() {
                Some(n) => Value::Num(n),
                None => Value::Nil,
            }),
            b => {
                let b = b.as_num().unwrap_or(10.0) as u32;
                let s = match &v {
                    Value::Str(s) => String::from_utf8_lossy(s).trim().to_lowercase(),
                    Value::Num(n) => format_num(*n),
                    _ => return ok1(Value::Nil),
                };
                ok1(match i64::from_str_radix(&s, b) {
                    Ok(n) => Value::Num(n as f64),
                    Err(_) => Value::Nil,
                })
            }
        }
    });
    it.register("ipairs", |_, args| {
        let t = arg_table(&args, 0, "ipairs")?;
        let iter = native("ipairs_iter", |_, a| {
            let t = arg_table(&a, 0, "ipairs")?;
            let i = arg_num(&a, 1, "ipairs")? + 1.0;
            let v = t.get(&Value::Num(i));
            if matches!(v, Value::Nil) {
                Ok(vec![Value::Nil])
            } else {
                Ok(vec![Value::Num(i), v])
            }
        });
        Ok(vec![iter, Value::Table(t), Value::Num(0.0)])
    });
    it.register("next", |_, args| {
        let t = arg_table(&args, 0, "next")?;
        match t.next(&arg(&args, 1))? {
            Some((k, v)) => Ok(vec![k, v]),
            None => Ok(vec![Value::Nil]),
        }
    });
    it.register("pairs", |it, args| {
        let v = arg(&args, 0);
        if let Some(h) = it.get_metatable(&v).map(|m| m.get_str("__pairs")) {
            if !matches!(h, Value::Nil) {
                let mut r = it.call(&h, vec![v])?;
                r.resize(3, Value::Nil);
                return Ok(r);
            }
        }
        let t = arg_table(&args, 0, "pairs")?;
        let next = it.globals.get_str("next");
        Ok(vec![next, Value::Table(t), Value::Nil])
    });
    it.register("rawget", |_, args| {
        let t = arg_table(&args, 0, "rawget")?;
        ok1(t.get(&arg(&args, 1)))
    });
    it.register("rawset", |_, args| {
        let t = arg_table(&args, 0, "rawset")?;
        t.set(arg(&args, 1), arg(&args, 2))?;
        ok1(Value::Table(t))
    });
    it.register("rawequal", |_, args| ok1(Value::Bool(arg(&args, 0).raw_eq(&arg(&args, 1)))));
    it.register("rawlen", |_, args| match arg(&args, 0) {
        Value::Table(t) => ok1(Value::Num(t.len() as f64)),
        Value::Str(s) => ok1(Value::Num(s.len() as f64)),
        _ => Err(LuaError::msg("table or string expected")),
    });
    it.register("setmetatable", |_, args| {
        let t = arg_table(&args, 0, "setmetatable")?;
        match arg(&args, 1) {
            Value::Nil => t.set_metatable(None),
            Value::Table(m) => t.set_metatable(Some(m)),
            _ => return Err(LuaError::msg("bad argument #2 to 'setmetatable' (nil or table expected)")),
        }
        ok1(Value::Table(t))
    });
    it.register("getmetatable", |it, args| {
        let v = arg(&args, 0);
        match it.get_metatable(&v) {
            Some(m) => {
                let protected = m.get_str("__metatable");
                if !matches!(protected, Value::Nil) {
                    return ok1(protected);
                }
                ok1(Value::Table(m))
            }
            None => ok1(Value::Nil),
        }
    });
    it.register("assert", |_, args| {
        if arg(&args, 0).truthy() {
            Ok(args)
        } else {
            let msg = match args.get(1) {
                Some(Value::Nil) | None => Value::str("assertion failed!"),
                Some(v) => v.clone(),
            };
            Err(LuaError::from_value(msg))
        }
    });
    it.register("error", |it, args| {
        let v = arg(&args, 0);
        let level = arg_opt_num(&args, 1, "error", 1.0)?;
        let mut err = LuaError::from_value(v.clone());
        if level > 0.0 {
            if let Value::Str(s) = &v {
                let line = it.call_lines.last().copied().unwrap_or(0);
                let _ = line;
                err.value = Value::Str(s.clone());
                err.traceback = Some(String::new());
            }
        }
        Err(err)
    });
    it.register("pcall", |it, args| {
        if args.is_empty() {
            return Err(LuaError::msg("bad argument #1 to 'pcall' (value expected)"));
        }
        let f = args[0].clone();
        let rest = args[1..].to_vec();
        let depth = it.depth;
        match it.call(&f, rest) {
            Ok(mut r) => {
                r.insert(0, Value::Bool(true));
                Ok(r)
            }
            Err(e) => {
                it.depth = depth;
                Ok(vec![Value::Bool(false), e.value])
            }
        }
    });
    it.register("xpcall", |it, args| {
        let f = arg(&args, 0);
        let handler = arg(&args, 1);
        let rest = if args.len() > 2 { args[2..].to_vec() } else { vec![] };
        let depth = it.depth;
        match it.call(&f, rest) {
            Ok(mut r) => {
                r.insert(0, Value::Bool(true));
                Ok(r)
            }
            Err(e) => {
                it.depth = depth;
                let mut r = it.call(&handler, vec![e.value])?;
                r.insert(0, Value::Bool(false));
                Ok(r)
            }
        }
    });
    it.register("select", |_, args| {
        let n = arg(&args, 0);
        if let Value::Str(s) = &n {
            if s.as_ref() == b"#" {
                return ok1(Value::Num((args.len() as f64 - 1.0).max(0.0)));
            }
        }
        let i = n.as_num().ok_or_else(|| LuaError::msg("bad argument #1 to 'select' (number expected)"))?;
        let rest = &args[1..];
        if i < 0.0 {
            let idx = rest.len() as i64 + i as i64;
            if idx < 0 {
                return Err(LuaError::msg("bad argument #1 to 'select' (index out of range)"));
            }
            Ok(rest[idx as usize..].to_vec())
        } else if i == 0.0 {
            Err(LuaError::msg("bad argument #1 to 'select' (index out of range)"))
        } else {
            let idx = (i as usize - 1).min(rest.len());
            Ok(rest[idx..].to_vec())
        }
    });
    it.register("unpack", lua_unpack);
    it.register("collectgarbage", |_, _| ok1(Value::Num(0.0)));
    it.register("loadstring", |it, args| {
        let src = arg_str(&args, 0, "loadstring")?;
        let name = match args.get(1) {
            Some(Value::Str(s)) => String::from_utf8_lossy(s).to_string(),
            _ => {
                let text = String::from_utf8_lossy(&src);
                let first = text.lines().next().unwrap_or("");
                let short = if first.chars().count() > 60 || text.contains('\n') {
                    format!("[string \"{}...\"]", first.chars().take(57).collect::<String>())
                } else {
                    format!("[string \"{}\"]", first)
                };
                short
            }
        };
        match it.load(&src, &name) {
            Ok(f) => ok1(f),
            Err(e) => Ok(vec![Value::Nil, e.value]),
        }
    });
    let ls = it.globals.get_str("loadstring");
    it.globals.set_str("load", ls);
    it.register("dofile", |it, args| {
        let path = arg_string(&args, 0, "dofile")?;
        let src = std::fs::read(&path)
            .map_err(|e| LuaError::msg(&format!("cannot open {}: {}", path, e)))?;
        let f = it.load(&src, &path)?;
        it.call(&f, vec![])
    });
    it.register("require", |it, args| {
        let name = arg_string(&args, 0, "require")?;
        let package = it.globals.get_str("package");
        let loaded = match &package {
            Value::Table(p) => p.get_str("loaded"),
            _ => Value::Nil,
        };
        if let Value::Table(l) = &loaded {
            let v = l.get_str(&name);
            if !matches!(v, Value::Nil) {
                return ok1(v);
            }
        }
        let path_spec = match &package {
            Value::Table(p) => p.get_str("path").as_str_lossy().unwrap_or_default(),
            _ => String::new(),
        };
        let fname = name.replace('.', "/");
        let mut tried = Vec::new();
        for templ in path_spec.split(';') {
            let candidate = templ.replace('?', &fname);
            if std::path::Path::new(&candidate).is_file() {
                let src = std::fs::read(&candidate)
                    .map_err(|e| LuaError::msg(&format!("cannot read {}: {}", candidate, e)))?;
                let f = it.load(&src, &candidate)?;
                let r = it.call(&f, vec![Value::str(&name)])?;
                let v = match r.into_iter().next() {
                    Some(Value::Nil) | None => Value::Bool(true),
                    Some(v) => v,
                };
                if let Value::Table(l) = &loaded {
                    l.set_str(&name, v.clone());
                }
                return ok1(v);
            }
            tried.push(format!("\n\tno file '{}'", candidate));
        }
        Err(LuaError::msg(&format!(
            "module '{}' not found:\n\tno field package.preload['{}']{}",
            name,
            name,
            tried.join("")
        )))
    });
    let package = TableRef::new();
    package.set_str("loaded", Value::Table(TableRef::new()));
    package.set_str("preload", Value::Table(TableRef::new()));
    let home = std::env::var("HOME").unwrap_or_default();
    let config_home = std::env::var("XDG_CONFIG_HOME")
        .ok()
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| format!("{}/.config", home));
    package.set_str(
        "path",
        Value::str(&format!(
            "{cfg}/xplr/plugins/?/init.lua;{cfg}/xplr/plugins/?.lua;./?.lua;./?/init.lua",
            cfg = config_home
        )),
    );
    it.globals.set_str("package", Value::Table(package));
}

fn lua_unpack(_: &mut Interp, args: Vec<Value>) -> LResult<Vec<Value>> {
    let t = arg_table(&args, 0, "unpack")?;
    let i = arg_opt_num(&args, 1, "unpack", 1.0)? as i64;
    let j = match args.get(2) {
        None | Some(Value::Nil) => t.len() as i64,
        Some(v) => v.as_num().unwrap_or(0.0) as i64,
    };
    let mut out = Vec::new();
    if j >= i {
        if j - i > 1_000_000 {
            return Err(LuaError::msg("too many results to unpack"));
        }
        for k in i..=j {
            out.push(t.get(&Value::Num(k as f64)));
        }
    }
    Ok(out)
}

// ---------------------------------------------------------------- string

fn str_index(i: i64, len: usize) -> usize {
    // translate a relative index to absolute 1-based position (clamped later)
    if i >= 0 {
        i as usize
    } else if (-i) as usize > len {
        0
    } else {
        len - ((-i) as usize) + 1
    }
}

fn open_string(it: &mut Interp) {
    let string = TableRef::new();
    let reg = |t: &TableRef, name: &str, f: fn(&mut Interp, Vec<Value>) -> LResult<Vec<Value>>| {
        t.set_str(name, native(name, f));
    };
    reg(&string, "len", |_, a| {
        let s = arg_str(&a, 0, "len")?;
        ok1(Value::Num(s.len() as f64))
    });
    reg(&string, "sub", |_, a| {
        let s = arg_str(&a, 0, "sub")?;
        let l = s.len();
        let i = arg_opt_num(&a, 1, "sub", 1.0)? as i64;
        let j = arg_opt_num(&a, 2, "sub", -1.0)? as i64;
        let mut start = str_index(i, l);
        let mut end = str_index(j, l);
        if start < 1 {
            start = 1;
        }
        if end > l {
            end = l;
        }
        if start > end {
            return ok1(Value::str(""));
        }
        ok1(Value::bytes(&s[start - 1..end]))
    });
    reg(&string, "upper", |_, a| {
        let s = arg_str(&a, 0, "upper")?;
        ok1(Value::bytes(&s.to_ascii_uppercase()))
    });
    reg(&string, "lower", |_, a| {
        let s = arg_str(&a, 0, "lower")?;
        ok1(Value::bytes(&s.to_ascii_lowercase()))
    });
    reg(&string, "rep", |_, a| {
        let s = arg_str(&a, 0, "rep")?;
        let n = arg_num(&a, 1, "rep")?;
        let sep = match a.get(2) {
            Some(Value::Str(x)) => x.to_vec(),
            _ => vec![],
        };
        let mut out = Vec::new();
        let n = if n < 0.0 { 0 } else { n as usize };
        for i in 0..n {
            if i > 0 {
                out.extend_from_slice(&sep);
            }
            out.extend_from_slice(&s);
        }
        ok1(Value::Str(Rc::from(out)))
    });
    reg(&string, "reverse", |_, a| {
        let mut s = arg_str(&a, 0, "reverse")?;
        s.reverse();
        ok1(Value::Str(Rc::from(s)))
    });
    reg(&string, "byte", |_, a| {
        let s = arg_str(&a, 0, "byte")?;
        let l = s.len();
        let i = arg_opt_num(&a, 1, "byte", 1.0)? as i64;
        let j = match a.get(2) {
            None | Some(Value::Nil) => i,
            Some(v) => v.as_num().unwrap_or(i as f64) as i64,
        };
        let start = str_index(i, l).max(1);
        let end = str_index(j, l).min(l);
        let mut out = Vec::new();
        if start <= end {
            for k in start..=end {
                out.push(Value::Num(s[k - 1] as f64));
            }
        }
        Ok(out)
    });
    reg(&string, "char", |_, a| {
        let mut out = Vec::new();
        for (i, v) in a.iter().enumerate() {
            let n = v.as_num().ok_or_else(|| {
                LuaError::msg(&format!("bad argument #{} to 'char' (number expected, got {})", i + 1, v.type_name()))
            })?;
            if !(0.0..=255.0).contains(&n) {
                return Err(LuaError::msg(&format!("bad argument #{} to 'char' (value out of range)", i + 1)));
            }
            out.push(n as u8);
        }
        ok1(Value::Str(Rc::from(out)))
    });
    reg(&string, "format", str_format);
    reg(&string, "find", |it, a| str_find(it, a, true));
    reg(&string, "match", |it, a| str_find(it, a, false));
    reg(&string, "gmatch", |_, a| {
        let s = arg_str(&a, 0, "gmatch")?;
        let p = arg_str(&a, 1, "gmatch")?;
        let state = Rc::new(RefCell::new(0usize));
        let s = Rc::new(s);
        let p = Rc::new(p);
        let iter = native("gmatch_iter", move |_, _| {
            let mut pos = state.borrow_mut();
            let anchor = p.first() == Some(&b'^');
            let pstart = if anchor { 1 } else { 0 };
            while *pos <= s.len() {
                let mut ms = lpattern::MatchState::new(&s, &p);
                match ms.do_match(*pos, pstart).map_err(|e| LuaError::msg(&e))? {
                    Some(e) => {
                        let caps = ms.captures(*pos, e, true).map_err(|e| LuaError::msg(&e))?;
                        if e == *pos {
                            *pos += 1;
                        } else {
                            *pos = e;
                        }
                        return Ok(caps_to_values(caps));
                    }
                    None => {
                        if anchor {
                            *pos = s.len() + 1;
                            break;
                        }
                        *pos += 1;
                    }
                }
            }
            Ok(vec![Value::Nil])
        });
        ok1(iter)
    });
    reg(&string, "gsub", str_gsub);
    it.globals.set_str("string", Value::Table(string.clone()));
    it.string_meta.set_str("__index", Value::Table(string));
}

fn caps_to_values(caps: Vec<Cap>) -> Vec<Value> {
    caps.into_iter()
        .map(|c| match c {
            Cap::Str(s) => Value::Str(Rc::from(s)),
            Cap::Pos(p) => Value::Num(p as f64),
        })
        .collect()
}

fn str_find(_: &mut Interp, a: Vec<Value>, find: bool) -> LResult<Vec<Value>> {
    let fname = if find { "find" } else { "match" };
    let s = arg_str(&a, 0, fname)?;
    let p = arg_str(&a, 1, fname)?;
    let l = s.len();
    let init = arg_opt_num(&a, 2, fname, 1.0)? as i64;
    let mut init = str_index(init, l);
    if init < 1 {
        init = 1;
    }
    if init > l + 1 {
        return ok1(Value::Nil);
    }
    let plain = find && arg(&a, 3).truthy();
    let has_specials = p.iter().any(|c| b"^$*+?.([%-".contains(c));
    if find && (plain || !has_specials) {
        // plain search
        if p.is_empty() {
            return Ok(vec![Value::Num(init as f64), Value::Num((init - 1) as f64)]);
        }
        let hay = &s[init - 1..];
        if let Some(pos) = hay.windows(p.len()).position(|w| w == p.as_slice()) {
            let start = init + pos;
            return Ok(vec![Value::Num(start as f64), Value::Num((start + p.len() - 1) as f64)]);
        }
        return ok1(Value::Nil);
    }
    match lpattern::find(&s, &p, init - 1).map_err(|e| LuaError::msg(&e))? {
        Some((st, e, caps)) => {
            if find {
                let mut out = vec![Value::Num((st + 1) as f64), Value::Num(e as f64)];
                out.extend(caps_to_values(caps));
                Ok(out)
            } else {
                let caps = if caps.is_empty() {
                    vec![Cap::Str(s[st..e].to_vec())]
                } else {
                    caps
                };
                Ok(caps_to_values(caps))
            }
        }
        None => ok1(Value::Nil),
    }
}

fn str_gsub(it: &mut Interp, a: Vec<Value>) -> LResult<Vec<Value>> {
    let s = arg_str(&a, 0, "gsub")?;
    let p = arg_str(&a, 1, "gsub")?;
    let repl = arg(&a, 2);
    let max_n = match a.get(3) {
        None | Some(Value::Nil) => usize::MAX,
        Some(v) => v.as_num().unwrap_or(0.0).max(0.0) as usize,
    };
    match &repl {
        Value::Str(_) | Value::Num(_) | Value::Table(_) | Value::Func(_) => {}
        other => {
            return Err(LuaError::msg(&format!(
                "bad argument #3 to 'gsub' (string/function/table expected, got {})",
                other.type_name()
            )))
        }
    }
    let mut out: Vec<u8> = Vec::new();
    let mut matches = lpattern::Matches::new(&s, &p);
    let mut last = 0usize;
    let mut count = 0usize;
    while count < max_n {
        let (st, e, caps) = match matches.next_match().map_err(|e| LuaError::msg(&e))? {
            Some(m) => m,
            None => break,
        };
        count += 1;
        out.extend_from_slice(&s[last..st]);
        let whole = Value::bytes(&s[st..e]);
        let capvals = caps_to_values(caps.clone());
        let replacement: Value = match &repl {
            Value::Str(r) => {
                // handle %0-%9 and %%
                let mut buf = Vec::new();
                let mut i = 0;
                while i < r.len() {
                    let c = r[i];
                    if c == b'%' {
                        i += 1;
                        if i >= r.len() {
                            return Err(LuaError::msg("invalid use of '%' in replacement string"));
                        }
                        let d = r[i];
                        if d == b'%' {
                            buf.push(b'%');
                        } else if d.is_ascii_digit() {
                            let idx = (d - b'0') as usize;
                            if idx == 0 {
                                buf.extend_from_slice(&s[st..e]);
                            } else {
                                match capvals.get(idx - 1) {
                                    Some(v) => buf.extend_from_slice(&tostring_basic(v)),
                                    None => {
                                        if idx == 1 && capvals.is_empty() {
                                            buf.extend_from_slice(&s[st..e]);
                                        } else {
                                            return Err(LuaError::msg(&format!("invalid capture index %{} in replacement string", idx)));
                                        }
                                    }
                                }
                            }
                        } else {
                            return Err(LuaError::msg("invalid use of '%' in replacement string"));
                        }
                        i += 1;
                    } else {
                        buf.push(c);
                        i += 1;
                    }
                }
                Value::Str(Rc::from(buf))
            }
            Value::Num(n) => Value::str(&format_num(*n)),
            Value::Table(t) => t.get(capvals.first().unwrap_or(&whole)),
            Value::Func(_) => {
                let args = if capvals.is_empty() { vec![whole.clone()] } else { capvals.clone() };
                it.call(&repl, args)?.into_iter().next().unwrap_or(Value::Nil)
            }
            _ => Value::Nil,
        };
        match replacement {
            Value::Nil | Value::Bool(false) => out.extend_from_slice(&s[st..e]),
            Value::Str(r) => out.extend_from_slice(&r),
            Value::Num(n) => out.extend_from_slice(format_num(n).as_bytes()),
            other => {
                return Err(LuaError::msg(&format!(
                    "invalid replacement value (a {})",
                    other.type_name()
                )))
            }
        }
        if e == st {
            if st < s.len() {
                out.push(s[st]);
            }
            last = st + 1;
        } else {
            last = e;
        }
    }
    if last < s.len() {
        out.extend_from_slice(&s[last..]);
    }
    Ok(vec![Value::Str(Rc::from(out)), Value::Num(count as f64)])
}

fn str_format(it: &mut Interp, a: Vec<Value>) -> LResult<Vec<Value>> {
    let fmt = arg_str(&a, 0, "format")?;
    let mut out: Vec<u8> = Vec::new();
    let mut argi = 1usize;
    let mut i = 0usize;
    while i < fmt.len() {
        let c = fmt[i];
        if c != b'%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= fmt.len() {
            return Err(LuaError::msg("invalid option '%' to 'format'"));
        }
        if fmt[i] == b'%' {
            out.push(b'%');
            i += 1;
            continue;
        }
        // parse flags/width/precision
        let mut flags = String::new();
        while i < fmt.len() && b"-+ #0".contains(&fmt[i]) {
            flags.push(fmt[i] as char);
            i += 1;
        }
        let mut width = String::new();
        while i < fmt.len() && fmt[i].is_ascii_digit() {
            width.push(fmt[i] as char);
            i += 1;
        }
        let mut precision: Option<usize> = None;
        if i < fmt.len() && fmt[i] == b'.' {
            i += 1;
            let mut p = String::new();
            while i < fmt.len() && fmt[i].is_ascii_digit() {
                p.push(fmt[i] as char);
                i += 1;
            }
            precision = Some(p.parse().unwrap_or(0));
        }
        if i >= fmt.len() {
            return Err(LuaError::msg("invalid option to 'format'"));
        }
        let conv = fmt[i];
        i += 1;
        let width: usize = width.parse().unwrap_or(0);
        let left = flags.contains('-');
        let zero = flags.contains('0') && !left;
        let plus = flags.contains('+');
        let space = flags.contains(' ');
        let alt = flags.contains('#');
        let argv = a.get(argi).cloned();
        let argno = argi + 1;
        let pad = |s: Vec<u8>, numeric: bool| -> Vec<u8> {
            if s.len() >= width {
                return s;
            }
            let n = width - s.len();
            if left {
                let mut v = s;
                v.extend(std::iter::repeat(b' ').take(n));
                v
            } else if zero && numeric {
                // insert zeros after sign
                let (sign, rest) = if s.first().map(|c| *c == b'-' || *c == b'+' || *c == b' ').unwrap_or(false) {
                    (vec![s[0]], s[1..].to_vec())
                } else {
                    (vec![], s)
                };
                let mut v = sign;
                v.extend(std::iter::repeat(b'0').take(n));
                v.extend(rest);
                v
            } else {
                let mut v: Vec<u8> = std::iter::repeat(b' ').take(n).collect();
                v.extend(s);
                v
            }
        };
        match conv {
            b'd' | b'i' => {
                let n = argv.as_ref().and_then(|v| v.as_num()).ok_or_else(|| {
                    LuaError::msg(&format!("bad argument #{} to 'format' (number expected, got {})", argno, argv.as_ref().map(|v| v.type_name()).unwrap_or("no value")))
                })?;
                let v = n.trunc() as i64;
                let mut s = v.abs().to_string();
                if let Some(p) = precision {
                    while s.len() < p {
                        s.insert(0, '0');
                    }
                }
                if v < 0 {
                    s.insert(0, '-');
                } else if plus {
                    s.insert(0, '+');
                } else if space {
                    s.insert(0, ' ');
                }
                out.extend(pad(s.into_bytes(), true));
                argi += 1;
            }
            b'u' => {
                let n = argv.as_ref().and_then(|v| v.as_num()).ok_or_else(|| LuaError::msg(&format!("bad argument #{} to 'format' (number expected)", argno)))?;
                let s = (n.trunc() as i64 as u64).to_string();
                out.extend(pad(s.into_bytes(), true));
                argi += 1;
            }
            b'c' => {
                let n = argv.as_ref().and_then(|v| v.as_num()).ok_or_else(|| LuaError::msg(&format!("bad argument #{} to 'format' (number expected)", argno)))?;
                out.extend(pad(vec![n as u8], false));
                argi += 1;
            }
            b'x' | b'X' | b'o' => {
                let n = argv.as_ref().and_then(|v| v.as_num()).ok_or_else(|| LuaError::msg(&format!("bad argument #{} to 'format' (number expected)", argno)))?;
                let v = n.trunc() as i64 as u64;
                let mut s = match conv {
                    b'x' => format!("{:x}", v),
                    b'X' => format!("{:X}", v),
                    _ => format!("{:o}", v),
                };
                if let Some(p) = precision {
                    while s.len() < p {
                        s.insert(0, '0');
                    }
                }
                if alt && v != 0 {
                    s = match conv {
                        b'x' => format!("0x{}", s),
                        b'X' => format!("0X{}", s),
                        _ => format!("0{}", s),
                    };
                }
                out.extend(pad(s.into_bytes(), true));
                argi += 1;
            }
            b'e' | b'E' | b'f' | b'F' | b'g' | b'G' => {
                let n = argv.as_ref().and_then(|v| v.as_num()).ok_or_else(|| {
                    LuaError::msg(&format!("bad argument #{} to 'format' (number expected, got {})", argno, argv.as_ref().map(|v| v.type_name()).unwrap_or("no value")))
                })?;
                let prec = precision.unwrap_or(6);
                let mut s = match conv {
                    b'f' | b'F' => format!("{:.*}", prec, n),
                    b'e' | b'E' => {
                        let t = format!("{:.*e}", prec, n);
                        // rust: 1.5e2 -> C: 1.5e+02
                        let (m, e) = t.split_once('e').unwrap_or((&t, "0"));
                        let ev: i32 = e.parse().unwrap_or(0);
                        let sign = if ev < 0 { '-' } else { '+' };
                        let r = format!("{}e{}{:02}", m, sign, ev.abs());
                        if conv == b'E' { r.to_uppercase() } else { r }
                    }
                    _ => {
                        let r = if alt {
                            format_g_alt(n, prec)
                        } else {
                            format_g(n, prec)
                        };
                        if conv == b'G' { r.to_uppercase() } else { r }
                    }
                };
                if n >= 0.0 && !n.is_nan() {
                    if plus {
                        s.insert(0, '+');
                    } else if space {
                        s.insert(0, ' ');
                    }
                }
                out.extend(pad(s.into_bytes(), true));
                argi += 1;
            }
            b's' => {
                let v = argv.clone().ok_or_else(|| LuaError::msg(&format!("bad argument #{} to 'format' (no value)", argno)))?;
                let mut s = it.tostring(&v)?;
                if let Some(p) = precision {
                    s.truncate(p);
                }
                out.extend(pad(s, false));
                argi += 1;
            }
            b'q' => {
                let v = argv.clone().ok_or_else(|| LuaError::msg(&format!("bad argument #{} to 'format' (no value)", argno)))?;
                let s = match &v {
                    Value::Str(s) => s.to_vec(),
                    other => tostring_basic(other),
                };
                out.push(b'"');
                for &b in &s {
                    match b {
                        b'"' => out.extend_from_slice(b"\\\""),
                        b'\\' => out.extend_from_slice(b"\\\\"),
                        b'\n' => out.extend_from_slice(b"\\\n"),
                        b'\r' => out.extend_from_slice(b"\\r"),
                        0 => out.extend_from_slice(b"\\0"),
                        _ => out.push(b),
                    }
                }
                out.push(b'"');
                argi += 1;
            }
            other => {
                return Err(LuaError::msg(&format!(
                    "invalid option '%{}' to 'format'",
                    other as char
                )))
            }
        }
    }
    ok1(Value::Str(Rc::from(out)))
}

fn format_g_alt(n: f64, prec: usize) -> String {
    // %#g keeps trailing zeros
    let prec = prec.max(1);
    let sci = format!("{:.*e}", prec - 1, n);
    let e_val: i32 = sci.rsplit('e').next().and_then(|e| e.parse().ok()).unwrap_or(0);
    if e_val < -4 || e_val >= prec as i32 {
        let (mant, _) = sci.split_once('e').unwrap();
        let sign = if e_val < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", mant, sign, e_val.abs())
    } else {
        let decimals = (prec as i32 - 1 - e_val).max(0) as usize;
        format!("{:.*}", decimals, n)
    }
}

// ---------------------------------------------------------------- table

fn open_table(it: &mut Interp) {
    let table = TableRef::new();
    table.set_str(
        "insert",
        native("insert", |_, a| {
            let t = arg_table(&a, 0, "insert")?;
            match a.len() {
                2 => {
                    t.push(a[1].clone());
                }
                3 => {
                    let n = t.len();
                    let pos = arg_num(&a, 1, "insert")? as i64;
                    if pos < 1 || pos as usize > n + 1 {
                        return Err(LuaError::msg("bad argument #2 to 'insert' (position out of bounds)"));
                    }
                    let pos = pos as usize;
                    let mut i = n;
                    while i >= pos {
                        let v = t.get(&Value::Num(i as f64));
                        t.set(Value::Num((i + 1) as f64), v)?;
                        if i == 0 {
                            break;
                        }
                        i -= 1;
                    }
                    t.set(Value::Num(pos as f64), a[2].clone())?;
                }
                _ => return Err(LuaError::msg("wrong number of arguments to 'insert'")),
            }
            Ok(vec![])
        }),
    );
    table.set_str(
        "remove",
        native("remove", |_, a| {
            let t = arg_table(&a, 0, "remove")?;
            let n = t.len();
            let pos = match a.get(1) {
                None | Some(Value::Nil) => n,
                Some(v) => v.as_num().unwrap_or(0.0) as usize,
            };
            if n == 0 && a.len() < 2 {
                return Ok(vec![]);
            }
            if n > 0 && (pos < 1 || pos > n + 1) {
                return Err(LuaError::msg("bad argument #2 to 'remove' (position out of bounds)"));
            }
            let v = t.get(&Value::Num(pos as f64));
            let mut i = pos;
            while i < n {
                let nv = t.get(&Value::Num((i + 1) as f64));
                t.set(Value::Num(i as f64), nv)?;
                i += 1;
            }
            if pos <= n {
                t.set(Value::Num(n as f64), Value::Nil)?;
            }
            ok1(v)
        }),
    );
    table.set_str(
        "concat",
        native("concat", |_, a| {
            let t = arg_table(&a, 0, "concat")?;
            let sep = match a.get(1) {
                Some(Value::Str(s)) => s.to_vec(),
                Some(Value::Num(n)) => format_num(*n).into_bytes(),
                _ => vec![],
            };
            let i = arg_opt_num(&a, 2, "concat", 1.0)? as i64;
            let j = match a.get(3) {
                None | Some(Value::Nil) => t.len() as i64,
                Some(v) => v.as_num().unwrap_or(0.0) as i64,
            };
            let mut out = Vec::new();
            let mut k = i;
            while k <= j {
                let v = t.get(&Value::Num(k as f64));
                match v {
                    Value::Str(s) => out.extend_from_slice(&s),
                    Value::Num(n) => out.extend_from_slice(format_num(n).as_bytes()),
                    other => {
                        return Err(LuaError::msg(&format!(
                            "invalid value (at index {}) in table for 'concat'",
                            k
                        )))
                        .map(|_: ()| vec![])
                        .or_else(|e| {
                            let _ = other;
                            Err(e)
                        })
                    }
                }
                if k < j {
                    out.extend_from_slice(&sep);
                }
                k += 1;
            }
            ok1(Value::Str(Rc::from(out)))
        }),
    );
    table.set_str("unpack", native("unpack", lua_unpack));
    table.set_str(
        "maxn",
        native("maxn", |_, a| {
            let t = arg_table(&a, 0, "maxn")?;
            let mut max = 0f64;
            let mut k = Value::Nil;
            while let Some((nk, _)) = t.next(&k)? {
                if let Value::Num(n) = nk {
                    if n > max {
                        max = n;
                    }
                }
                k = nk;
            }
            ok1(Value::Num(max))
        }),
    );
    table.set_str(
        "sort",
        native("sort", |it, a| {
            let t = arg_table(&a, 0, "sort")?;
            let cmp = arg(&a, 1);
            let n = t.len();
            let mut items: Vec<Value> = (1..=n).map(|i| t.get(&Value::Num(i as f64))).collect();
            // insertion-friendly merge sort with fallible comparator
            let mut err: Option<LuaError> = None;
            merge_sort(&mut items, &mut |x, y| {
                if err.is_some() {
                    return false;
                }
                let r = if matches!(cmp, Value::Nil) {
                    match (x, y) {
                        (Value::Num(p), Value::Num(q)) => Ok(p < q),
                        (Value::Str(p), Value::Str(q)) => Ok(p < q),
                        _ => it.binop(super::ast::BinOp::Lt, x.clone(), y.clone(), 0, "?").map(|v| v.truthy()),
                    }
                } else {
                    it.call(&cmp, vec![x.clone(), y.clone()])
                        .map(|v| v.into_iter().next().unwrap_or(Value::Nil).truthy())
                };
                match r {
                    Ok(b) => b,
                    Err(e) => {
                        err = Some(e);
                        false
                    }
                }
            });
            if let Some(e) = err {
                let m = e.message();
                return Err(LuaError::msg(&m.replace("attempt to compare", "attempt to compare")));
            }
            for (i, v) in items.into_iter().enumerate() {
                t.set(Value::Num((i + 1) as f64), v)?;
            }
            Ok(vec![])
        }),
    );
    it.globals.set_str("table", Value::Table(table));
}

fn merge_sort(items: &mut Vec<Value>, less: &mut dyn FnMut(&Value, &Value) -> bool) {
    if items.len() <= 1 {
        return;
    }
    let mid = items.len() / 2;
    let mut right = items.split_off(mid);
    merge_sort(items, less);
    merge_sort(&mut right, less);
    let left = std::mem::take(items);
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if less(&right[j], &left[i]) {
            items.push(right[j].clone());
            j += 1;
        } else {
            items.push(left[i].clone());
            i += 1;
        }
    }
    items.extend_from_slice(&left[i..]);
    items.extend_from_slice(&right[j..]);
}

// ---------------------------------------------------------------- math

fn open_math(it: &mut Interp) {
    let math = TableRef::new();
    let f1 = |t: &TableRef, name: &'static str, f: fn(f64) -> f64| {
        t.set_str(name, native(name, move |_, a| ok1(Value::Num(f(arg_num(&a, 0, name)?)))));
    };
    f1(&math, "abs", f64::abs);
    f1(&math, "ceil", f64::ceil);
    f1(&math, "floor", f64::floor);
    f1(&math, "sqrt", f64::sqrt);
    f1(&math, "exp", f64::exp);
    f1(&math, "sin", f64::sin);
    f1(&math, "cos", f64::cos);
    f1(&math, "tan", f64::tan);
    f1(&math, "asin", f64::asin);
    f1(&math, "acos", f64::acos);
    f1(&math, "atan", f64::atan);
    f1(&math, "sinh", f64::sinh);
    f1(&math, "cosh", f64::cosh);
    f1(&math, "tanh", f64::tanh);
    f1(&math, "log10", f64::log10);
    f1(&math, "deg", f64::to_degrees);
    f1(&math, "rad", f64::to_radians);
    math.set_str(
        "log",
        native("log", |_, a| {
            let x = arg_num(&a, 0, "log")?;
            match a.get(1) {
                None | Some(Value::Nil) => ok1(Value::Num(x.ln())),
                _ => {
                    let b = arg_num(&a, 1, "log")?;
                    ok1(Value::Num(x.ln() / b.ln()))
                }
            }
        }),
    );
    math.set_str(
        "pow",
        native("pow", |_, a| ok1(Value::Num(arg_num(&a, 0, "pow")?.powf(arg_num(&a, 1, "pow")?)))),
    );
    math.set_str(
        "fmod",
        native("fmod", |_, a| ok1(Value::Num(arg_num(&a, 0, "fmod")? % arg_num(&a, 1, "fmod")?))),
    );
    math.set_str(
        "atan2",
        native("atan2", |_, a| ok1(Value::Num(arg_num(&a, 0, "atan2")?.atan2(arg_num(&a, 1, "atan2")?)))),
    );
    math.set_str(
        "modf",
        native("modf", |_, a| {
            let x = arg_num(&a, 0, "modf")?;
            Ok(vec![Value::Num(x.trunc()), Value::Num(x.fract())])
        }),
    );
    math.set_str(
        "frexp",
        native("frexp", |_, a| {
            let x = arg_num(&a, 0, "frexp")?;
            if x == 0.0 {
                return Ok(vec![Value::Num(0.0), Value::Num(0.0)]);
            }
            let e = x.abs().log2().floor() as i32 + 1;
            Ok(vec![Value::Num(x / 2f64.powi(e)), Value::Num(e as f64)])
        }),
    );
    math.set_str(
        "ldexp",
        native("ldexp", |_, a| ok1(Value::Num(arg_num(&a, 0, "ldexp")? * 2f64.powi(arg_num(&a, 1, "ldexp")? as i32)))),
    );
    math.set_str(
        "max",
        native("max", |_, a| {
            let mut m = arg_num(&a, 0, "max")?;
            for i in 1..a.len() {
                let v = arg_num(&a, i, "max")?;
                if v > m {
                    m = v;
                }
            }
            ok1(Value::Num(m))
        }),
    );
    math.set_str(
        "min",
        native("min", |_, a| {
            let mut m = arg_num(&a, 0, "min")?;
            for i in 1..a.len() {
                let v = arg_num(&a, i, "min")?;
                if v < m {
                    m = v;
                }
            }
            ok1(Value::Num(m))
        }),
    );
    let seed = Rc::new(RefCell::new(0x2545F4914F6CDD1Du64));
    let seed2 = seed.clone();
    math.set_str(
        "random",
        native("random", move |_, a| {
            let mut s = seed.borrow_mut();
            // xorshift64*
            let mut x = *s;
            x ^= x >> 12;
            x ^= x << 25;
            x ^= x >> 27;
            *s = x;
            let r = (x.wrapping_mul(0x2545F4914F6CDD1D) >> 11) as f64 / (1u64 << 53) as f64;
            match a.len() {
                0 => ok1(Value::Num(r)),
                1 => {
                    let m = arg_num(&a, 0, "random")?;
                    if m < 1.0 {
                        return Err(LuaError::msg("bad argument #1 to 'random' (interval is empty)"));
                    }
                    ok1(Value::Num((r * m).floor() + 1.0))
                }
                _ => {
                    let lo = arg_num(&a, 0, "random")?;
                    let hi = arg_num(&a, 1, "random")?;
                    if lo > hi {
                        return Err(LuaError::msg("bad argument #2 to 'random' (interval is empty)"));
                    }
                    ok1(Value::Num((r * (hi - lo + 1.0)).floor() + lo))
                }
            }
        }),
    );
    math.set_str(
        "randomseed",
        native("randomseed", move |_, a| {
            let n = arg_num(&a, 0, "randomseed")?;
            *seed2.borrow_mut() = (n as i64 as u64) ^ 0x9E3779B97F4A7C15;
            if *seed2.borrow() == 0 {
                *seed2.borrow_mut() = 1;
            }
            Ok(vec![])
        }),
    );
    math.set_str("huge", Value::Num(f64::INFINITY));
    math.set_str("pi", Value::Num(std::f64::consts::PI));
    it.globals.set_str("math", Value::Table(math));
}

// ---------------------------------------------------------------- os

fn open_os(it: &mut Interp) {
    let os = TableRef::new();
    os.set_str(
        "getenv",
        native("getenv", |_, a| {
            let k = arg_string(&a, 0, "getenv")?;
            ok1(match std::env::var(&k) {
                Ok(v) => Value::str(&v),
                Err(_) => Value::Nil,
            })
        }),
    );
    os.set_str(
        "time",
        native("time", |_, a| {
            match a.first() {
                Some(Value::Table(t)) => {
                    let get = |k: &str, d: f64| t.get_str(k).as_num().unwrap_or(d);
                    let year = get("year", 1970.0) as i32;
                    let month = get("month", 1.0) as i32;
                    let day = get("day", 1.0) as i32;
                    let hour = get("hour", 12.0) as i32;
                    let min = get("min", 0.0) as i32;
                    let sec = get("sec", 0.0) as i32;
                    let ts = unsafe {
                        let mut tm: libc::tm = std::mem::zeroed();
                        tm.tm_year = year - 1900;
                        tm.tm_mon = month - 1;
                        tm.tm_mday = day;
                        tm.tm_hour = hour;
                        tm.tm_min = min;
                        tm.tm_sec = sec;
                        tm.tm_isdst = -1;
                        libc::mktime(&mut tm)
                    };
                    ok1(Value::Num(ts as f64))
                }
                _ => {
                    let now = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|d| d.as_secs() as f64)
                        .unwrap_or(0.0);
                    ok1(Value::Num(now))
                }
            }
        }),
    );
    os.set_str(
        "clock",
        native("clock", |_, _| {
            let c = unsafe { libc::clock() };
            ok1(Value::Num(c as f64 / libc::CLOCKS_PER_SEC as f64))
        }),
    );
    os.set_str(
        "date",
        native("date", |_, a| {
            let fmt = match a.first() {
                Some(Value::Str(s)) => String::from_utf8_lossy(s).to_string(),
                _ => "%c".to_string(),
            };
            let t = match a.get(1) {
                Some(v) if !matches!(v, Value::Nil) => v.as_num().unwrap_or(0.0) as libc::time_t,
                _ => unsafe { libc::time(std::ptr::null_mut()) },
            };
            let (utc, fmt) = match fmt.strip_prefix('!') {
                Some(r) => (true, r.to_string()),
                None => (false, fmt),
            };
            let tm = unsafe {
                let mut tm: libc::tm = std::mem::zeroed();
                if utc {
                    libc::gmtime_r(&t, &mut tm);
                } else {
                    libc::localtime_r(&t, &mut tm);
                }
                tm
            };
            if fmt.starts_with("*t") {
                let tbl = TableRef::new();
                tbl.set_str("year", Value::Num((tm.tm_year + 1900) as f64));
                tbl.set_str("month", Value::Num((tm.tm_mon + 1) as f64));
                tbl.set_str("day", Value::Num(tm.tm_mday as f64));
                tbl.set_str("hour", Value::Num(tm.tm_hour as f64));
                tbl.set_str("min", Value::Num(tm.tm_min as f64));
                tbl.set_str("sec", Value::Num(tm.tm_sec as f64));
                tbl.set_str("wday", Value::Num((tm.tm_wday + 1) as f64));
                tbl.set_str("yday", Value::Num((tm.tm_yday + 1) as f64));
                tbl.set_str("isdst", Value::Bool(tm.tm_isdst > 0));
                return ok1(Value::Table(tbl));
            }
            let cfmt = std::ffi::CString::new(fmt).unwrap_or_default();
            let mut buf = vec![0u8; 512];
            let n = unsafe {
                libc::strftime(
                    buf.as_mut_ptr() as *mut libc::c_char,
                    buf.len(),
                    cfmt.as_ptr(),
                    &tm,
                )
            };
            ok1(Value::bytes(&buf[..n]))
        }),
    );
    os.set_str(
        "remove",
        native("remove", |_, a| {
            let p = arg_string(&a, 0, "remove")?;
            let path = std::path::Path::new(&p);
            let r = if path.is_dir() {
                std::fs::remove_dir(path)
            } else {
                std::fs::remove_file(path)
            };
            match r {
                Ok(()) => ok1(Value::Bool(true)),
                Err(e) => Ok(vec![Value::Nil, Value::str(&format!("{}: {}", p, e))]),
            }
        }),
    );
    os.set_str(
        "rename",
        native("rename", |_, a| {
            let from = arg_string(&a, 0, "rename")?;
            let to = arg_string(&a, 1, "rename")?;
            match std::fs::rename(&from, &to) {
                Ok(()) => ok1(Value::Bool(true)),
                Err(e) => Ok(vec![Value::Nil, Value::str(&format!("{}: {}", from, e))]),
            }
        }),
    );
    os.set_str(
        "tmpname",
        native("tmpname", |_, _| {
            let p = std::env::temp_dir().join(format!("lua_{}", std::process::id()));
            ok1(Value::str(&p.to_string_lossy()))
        }),
    );
    os.set_str(
        "execute",
        native("execute", |_, a| match a.first() {
            None | Some(Value::Nil) => ok1(Value::Num(1.0)),
            Some(_) => {
                let cmd = arg_string(&a, 0, "execute")?;
                let status = std::process::Command::new("sh").arg("-c").arg(&cmd).status();
                ok1(Value::Num(status.ok().and_then(|s| s.code()).unwrap_or(-1) as f64))
            }
        }),
    );
    os.set_str(
        "exit",
        native("exit", |_, a| {
            let code = match a.first() {
                Some(Value::Bool(false)) => 1,
                Some(Value::Num(n)) => *n as i32,
                _ => 0,
            };
            std::process::exit(code)
        }),
    );
    it.globals.set_str("os", Value::Table(os));
}

// ---------------------------------------------------------------- io

struct FileHandle {
    file: Option<std::fs::File>,
    kind: u8, // 0 file, 1 stdout, 2 stderr, 3 stdin
}

fn file_meta(it: &mut Interp) -> TableRef {
    let meta = it.globals.get_str("__file_meta");
    if let Value::Table(t) = meta {
        return t;
    }
    let meta = TableRef::new();
    let methods = TableRef::new();
    methods.set_str(
        "write",
        native("write", |_, a| {
            let h = arg_table(&a, 0, "write")?;
            let data: Vec<Vec<u8>> = a[1..].iter().map(tostring_basic).collect();
            file_write(&h, &data)?;
            ok1(Value::Table(h))
        }),
    );
    methods.set_str(
        "close",
        native("close", |_, a| {
            let h = arg_table(&a, 0, "close")?;
            with_handle(&h, |fh| {
                fh.file = None;
                Ok(())
            })?;
            ok1(Value::Bool(true))
        }),
    );
    methods.set_str(
        "read",
        native("read", |_, a| {
            let h = arg_table(&a, 0, "read")?;
            let fmt = match a.get(1) {
                Some(Value::Str(s)) => String::from_utf8_lossy(s).to_string(),
                Some(Value::Num(n)) => format!("{}", n),
                _ => "*l".to_string(),
            };
            file_read(&h, &fmt)
        }),
    );
    methods.set_str(
        "lines",
        native("lines", |_, a| {
            let h = arg_table(&a, 0, "lines")?;
            let iter = native("lines_iter", move |_, _| file_read(&h, "*l"));
            ok1(iter)
        }),
    );
    methods.set_str("flush", native("flush", |_, a| ok1(arg(&a, 0))));
    methods.set_str("setvbuf", native("setvbuf", |_, _| ok1(Value::Bool(true))));
    meta.set_str("__index", Value::Table(methods));
    meta.set_str("__name", Value::str("FILE*"));
    it.globals.set_str("__file_meta", Value::Table(meta.clone()));
    meta
}

thread_local! {
    static HANDLES: RefCell<Vec<FileHandle>> = RefCell::new(Vec::new());
}

fn new_handle(it: &mut Interp, fh: FileHandle) -> Value {
    let id = HANDLES.with(|h| {
        let mut h = h.borrow_mut();
        h.push(fh);
        h.len() - 1
    });
    let t = TableRef::new();
    t.set_str("__id", Value::Num(id as f64));
    t.set_metatable(Some(file_meta(it)));
    Value::Table(t)
}

fn with_handle<R>(h: &TableRef, f: impl FnOnce(&mut FileHandle) -> LResult<R>) -> LResult<R> {
    let id = h.get_str("__id").as_num().ok_or_else(|| LuaError::msg("bad file handle"))? as usize;
    HANDLES.with(|hs| {
        let mut hs = hs.borrow_mut();
        let fh = hs.get_mut(id).ok_or_else(|| LuaError::msg("bad file handle"))?;
        f(fh)
    })
}

fn file_write(h: &TableRef, data: &[Vec<u8>]) -> LResult<()> {
    use std::io::Write;
    with_handle(h, |fh| {
        match fh.kind {
            1 => {
                let mut o = std::io::stdout();
                for d in data {
                    let _ = o.write_all(d);
                }
                let _ = o.flush();
            }
            2 => {
                let mut o = std::io::stderr();
                for d in data {
                    let _ = o.write_all(d);
                }
            }
            _ => {
                let f = fh.file.as_mut().ok_or_else(|| LuaError::msg("attempt to use a closed file"))?;
                for d in data {
                    f.write_all(d).map_err(|e| LuaError::msg(&e.to_string()))?;
                }
            }
        }
        Ok(())
    })
}

fn read_all_from(r: &mut dyn std::io::Read) -> Vec<u8> {
    let mut buf = Vec::new();
    let _ = r.read_to_end(&mut buf);
    buf
}

fn read_line_from(r: &mut dyn std::io::Read, keep_nl: bool) -> Option<Vec<u8>> {
    let mut buf = Vec::new();
    let mut byte = [0u8; 1];
    loop {
        match r.read(&mut byte) {
            Ok(0) => break,
            Ok(_) => {
                if byte[0] == b'\n' {
                    if keep_nl {
                        buf.push(b'\n');
                    }
                    return Some(buf);
                }
                buf.push(byte[0]);
            }
            Err(_) => break,
        }
    }
    if buf.is_empty() {
        None
    } else {
        Some(buf)
    }
}

fn file_read(h: &TableRef, fmt: &str) -> LResult<Vec<Value>> {
    with_handle(h, |fh| {
        let mut stdin = std::io::stdin();
        let reader: &mut dyn std::io::Read = match fh.kind {
            3 => &mut stdin,
            _ => match fh.file.as_mut() {
                Some(f) => f,
                None => return Err(LuaError::msg("attempt to use a closed file")),
            },
        };
        let fmt = fmt.trim_start_matches('*');
        let v = match fmt.chars().next() {
            Some('a') => Value::Str(Rc::from(read_all_from(reader))),
            Some('l') => match read_line_from(reader, false) {
                Some(l) => Value::Str(Rc::from(l)),
                None => Value::Nil,
            },
            Some('L') => match read_line_from(reader, true) {
                Some(l) => Value::Str(Rc::from(l)),
                None => Value::Nil,
            },
            Some('n') => match read_line_from(reader, false) {
                Some(l) => match parse_number(&String::from_utf8_lossy(&l)) {
                    Some(n) => Value::Num(n),
                    None => Value::Nil,
                },
                None => Value::Nil,
            },
            Some(c) if c.is_ascii_digit() => {
                let n: usize = fmt.parse().unwrap_or(0);
                let mut buf = vec![0u8; n];
                let mut got = 0;
                while got < n {
                    match reader.read(&mut buf[got..]) {
                        Ok(0) => break,
                        Ok(k) => got += k,
                        Err(_) => break,
                    }
                }
                if got == 0 && n > 0 {
                    Value::Nil
                } else {
                    Value::bytes(&buf[..got])
                }
            }
            _ => return Err(LuaError::msg("bad argument #1 to 'read' (invalid format)")),
        };
        Ok(vec![v])
    })
}

fn open_io(it: &mut Interp) {
    let io = TableRef::new();
    let stdout = new_handle(it, FileHandle { file: None, kind: 1 });
    let stderr = new_handle(it, FileHandle { file: None, kind: 2 });
    let stdin = new_handle(it, FileHandle { file: None, kind: 3 });
    io.set_str("stdout", stdout.clone());
    io.set_str("stderr", stderr);
    io.set_str("stdin", stdin.clone());
    io.set_str(
        "write",
        native("write", move |_, a| {
            let data: Vec<Vec<u8>> = a.iter().map(tostring_basic).collect();
            if let Value::Table(h) = &stdout {
                file_write(h, &data)?;
            }
            ok1(stdout.clone())
        }),
    );
    io.set_str(
        "read",
        native("read", move |_, a| {
            let fmt = match a.first() {
                Some(Value::Str(s)) => String::from_utf8_lossy(s).to_string(),
                Some(Value::Num(n)) => format!("{}", n),
                _ => "*l".to_string(),
            };
            if let Value::Table(h) = &stdin {
                return file_read(h, &fmt);
            }
            Ok(vec![Value::Nil])
        }),
    );
    io.set_str(
        "open",
        native("open", |it, a| {
            let path = arg_string(&a, 0, "open")?;
            let mode = match a.get(1) {
                Some(Value::Str(s)) => String::from_utf8_lossy(s).to_string(),
                _ => "r".to_string(),
            };
            let mut opts = std::fs::OpenOptions::new();
            match mode.trim_end_matches('b') {
                "r" => {
                    opts.read(true);
                }
                "w" => {
                    opts.write(true).create(true).truncate(true);
                }
                "a" => {
                    opts.append(true).create(true);
                }
                "r+" => {
                    opts.read(true).write(true);
                }
                "w+" => {
                    opts.read(true).write(true).create(true).truncate(true);
                }
                "a+" => {
                    opts.read(true).append(true).create(true);
                }
                _ => return Err(LuaError::msg("bad argument #2 to 'open' (invalid mode)")),
            }
            match opts.open(&path) {
                Ok(f) => ok1(new_handle(it, FileHandle { file: Some(f), kind: 0 })),
                Err(e) => Ok(vec![
                    Value::Nil,
                    Value::str(&format!("{}: {}", path, io_err_str(&e))),
                    Value::Num(e.raw_os_error().unwrap_or(0) as f64),
                ]),
            }
        }),
    );
    io.set_str(
        "lines",
        native("lines", |it, a| {
            let path = arg_string(&a, 0, "lines")?;
            let f = std::fs::File::open(&path)
                .map_err(|e| LuaError::msg(&format!("{}: {}", path, io_err_str(&e))))?;
            let h = new_handle(it, FileHandle { file: Some(f), kind: 0 });
            let ht = match h {
                Value::Table(t) => t,
                _ => unreachable!(),
            };
            let iter = native("lines_iter", move |_, _| file_read(&ht, "*l"));
            ok1(iter)
        }),
    );
    io.set_str(
        "close",
        native("close", |_, a| {
            if let Some(Value::Table(h)) = a.first() {
                with_handle(h, |fh| {
                    fh.file = None;
                    Ok(())
                })?;
            }
            ok1(Value::Bool(true))
        }),
    );
    it.globals.set_str("io", Value::Table(io));
}

fn io_err_str(e: &std::io::Error) -> String {
    // C-like message without the "(os error N)" suffix
    let s = e.to_string();
    match s.find(" (os error") {
        Some(i) => s[..i].to_string(),
        None => s,
    }
}
