// ---------------------------------------------------------------- deserialize

pub fn from_lua<T: de::DeserializeOwned>(v: Value) -> Result<T, BridgeError> {
    T::deserialize(LuaDeserializer { v })
}

pub struct LuaDeserializer {
    v: Value,
}

fn table_is_array(t: &TableRef) -> bool {
    let d = t.0.borrow();
    d.hash.is_empty()
}

fn table_entries(t: &TableRef) -> Vec<(Value, Value)> {
    let mut out = Vec::new();
    let mut k = Value::Nil;
    while let Ok(Some((nk, v))) = t.next(&k) {
        out.push((nk.clone(), v));
        k = nk;
    }
    out
}

fn table_array(t: &TableRef) -> Vec<Value> {
    let n = t.len();
    (1..=n).map(|i| t.get(&Value::Num(i as f64))).collect()
}

fn num_to_json_like<'de, V: Visitor<'de>>(n: f64, visitor: V) -> Result<V::Value, BridgeError> {
    if n.fract() == 0.0 && n.abs() < 9.0e15 {
        if n >= 0.0 {
            visitor.visit_u64(n as u64)
        } else {
            visitor.visit_i64(n as i64)
        }
    } else {
        visitor.visit_f64(n)
    }
}

impl<'de> de::Deserializer<'de> for LuaDeserializer {
    type Error = BridgeError;

    fn deserialize_any<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Nil => visitor.visit_unit(),
            Value::Bool(b) => visitor.visit_bool(b),
            Value::Num(n) => num_to_json_like(n, visitor),
            Value::Str(s) => visitor.visit_string(String::from_utf8_lossy(&s).to_string()),
            Value::Table(t) => {
                if table_is_array(&t) {
                    visitor.visit_seq(SeqAccess {
                        items: table_array(&t).into_iter(),
                    })
                } else {
                    visitor.visit_map(MapAccess {
                        entries: table_entries(&t).into_iter(),
                        value: None,
                    })
                }
            }
            Value::Func(_) => Err(BridgeError("cannot convert function to data".into())),
        }
    }

    fn deserialize_option<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Nil => visitor.visit_none(),
            _ => visitor.visit_some(self),
        }
    }

    fn deserialize_unit<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Nil => visitor.visit_unit(),
            other => Err(BridgeError(format!("invalid type: {}, expected unit", other.type_name()))),
        }
    }

    fn deserialize_seq<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Table(t) => visitor.visit_seq(SeqAccess {
                items: table_array(&t).into_iter(),
            }),
            other => Err(BridgeError(format!(
                "invalid type: {}, expected a sequence",
                describe(&other)
            ))),
        }
    }

    fn deserialize_tuple<V: Visitor<'de>>(self, _len: usize, visitor: V) -> Result<V::Value, BridgeError> {
        self.deserialize_seq(visitor)
    }

    fn deserialize_tuple_struct<V: Visitor<'de>>(self, _: &'static str, _len: usize, visitor: V) -> Result<V::Value, BridgeError> {
        self.deserialize_seq(visitor)
    }

    fn deserialize_map<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Table(t) => visitor.visit_map(MapAccess {
                entries: table_entries(&t).into_iter(),
                value: None,
            }),
            other => Err(BridgeError(format!("invalid type: {}, expected a map", describe(&other)))),
        }
    }

    fn deserialize_struct<V: Visitor<'de>>(
        self,
        _: &'static str,
        _: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, BridgeError> {
        self.deserialize_map(visitor)
    }

    fn deserialize_enum<V: Visitor<'de>>(
        self,
        _: &'static str,
        _: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Str(s) => visitor.visit_enum(EnumAccess {
                variant: String::from_utf8_lossy(&s).to_string(),
                value: None,
            }),
            Value::Table(t) => {
                let entries = table_entries(&t);
                if entries.len() != 1 {
                    return Err(BridgeError(format!(
                        "invalid value: map, expected map with a single key"
                    )));
                }
                let (k, v) = entries.into_iter().next().unwrap();
                let variant = match k {
                    Value::Str(s) => String::from_utf8_lossy(&s).to_string(),
                    other => return Err(BridgeError(format!("invalid type: {}, expected variant name", other.type_name()))),
                };
                visitor.visit_enum(EnumAccess {
                    variant,
                    value: Some(v),
                })
            }
            other => Err(BridgeError(format!("invalid type: {}, expected enum", describe(&other)))),
        }
    }

    fn deserialize_newtype_struct<V: Visitor<'de>>(self, _: &'static str, visitor: V) -> Result<V::Value, BridgeError> {
        visitor.visit_newtype_struct(self)
    }

    fn deserialize_ignored_any<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        visitor.visit_unit()
    }

    fn deserialize_bool<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Bool(b) => visitor.visit_bool(b),
            other => Err(BridgeError(format!("invalid type: {}, expected a boolean", describe(&other)))),
        }
    }

    fn deserialize_char<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match &self.v {
            Value::Str(s) => {
                let st = String::from_utf8_lossy(s);
                let mut it = st.chars();
                match (it.next(), it.next()) {
                    (Some(c), None) => visitor.visit_char(c),
                    _ => Err(BridgeError(format!("invalid value: string {:?}, expected a character", st))),
                }
            }
            other => Err(BridgeError(format!("invalid type: {}, expected a character", describe(other)))),
        }
    }

    fn deserialize_str<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Str(s) => visitor.visit_string(String::from_utf8_lossy(&s).to_string()),
            other => Err(BridgeError(format!("invalid type: {}, expected a string", describe(&other)))),
        }
    }

    fn deserialize_string<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        self.deserialize_str(visitor)
    }

    fn deserialize_bytes<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        match self.v {
            Value::Str(s) => visitor.visit_bytes(&s),
            other => Err(BridgeError(format!("invalid type: {}, expected bytes", describe(&other)))),
        }
    }

    fn deserialize_byte_buf<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        self.deserialize_bytes(visitor)
    }

    fn deserialize_identifier<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, BridgeError> {
        self.deserialize_str(visitor)
    }

    fn deserialize_unit_struct<V: Visitor<'de>>(self, _: &'static str, visitor: V) -> Result<V::Value, BridgeError> {
        self.deserialize_unit(visitor)
    }

    serde::forward_to_deserialize_any! {
        i8 i16 i32 i64 i128 u8 u16 u32 u64 u128 f32 f64
    }
}

fn describe(v: &Value) -> String {
    match v {
        Value::Nil => "null".to_string(),
        Value::Bool(b) => format!("boolean `{}`", b),
        Value::Num(n) => {
            if n.fract() == 0.0 {
                format!("integer `{}`", *n as i64)
            } else {
                format!("floating point `{}`", n)
            }
        }
        Value::Str(s) => format!("string {:?}", String::from_utf8_lossy(s)),
        Value::Table(t) => {
            if table_is_array(t) && t.len() > 0 {
                "sequence".to_string()
            } else {
                "map".to_string()
            }
        }
        Value::Func(_) => "function".to_string(),
    }
}

struct SeqAccess {
    items: std::vec::IntoIter<Value>,
}

impl<'de> de::SeqAccess<'de> for SeqAccess {
    type Error = BridgeError;
    fn next_element_seed<T: DeserializeSeed<'de>>(&mut self, seed: T) -> Result<Option<T::Value>, BridgeError> {
        match self.items.next() {
            Some(v) => seed.deserialize(LuaDeserializer { v }).map(Some),
            None => Ok(None),
        }
    }
}

struct MapAccess {
    entries: std::vec::IntoIter<(Value, Value)>,
    value: Option<Value>,
}

impl<'de> de::MapAccess<'de> for MapAccess {
    type Error = BridgeError;
    fn next_key_seed<K: DeserializeSeed<'de>>(&mut self, seed: K) -> Result<Option<K::Value>, BridgeError> {
        match self.entries.next() {
            Some((k, v)) => {
                self.value = Some(v);
                let key = match k {
                    Value::Num(n) => Value::str(&super::lexer::format_num(n)),
                    other => other,
                };
                seed.deserialize(LuaDeserializer { v: key }).map(Some)
            }
            None => Ok(None),
        }
    }
    fn next_value_seed<V: DeserializeSeed<'de>>(&mut self, seed: V) -> Result<V::Value, BridgeError> {
        let v = self.value.take().unwrap_or(Value::Nil);
        seed.deserialize(LuaDeserializer { v })
    }
}

struct EnumAccess {
    variant: String,
    value: Option<Value>,
}

impl<'de> de::EnumAccess<'de> for EnumAccess {
    type Error = BridgeError;
    type Variant = VariantAccess;
    fn variant_seed<V: DeserializeSeed<'de>>(self, seed: V) -> Result<(V::Value, VariantAccess), BridgeError> {
        let v = seed.deserialize(self.variant.clone().into_deserializer())?;
        Ok((v, VariantAccess { value: self.value }))
    }
}

struct VariantAccess {
    value: Option<Value>,
}

impl<'de> de::VariantAccess<'de> for VariantAccess {
    type Error = BridgeError;
    fn unit_variant(self) -> Result<(), BridgeError> {
        match self.value {
            None | Some(Value::Nil) => Ok(()),
            Some(other) => Err(BridgeError(format!("invalid type: {}, expected unit", describe(&other)))),
        }
    }
    fn newtype_variant_seed<T: DeserializeSeed<'de>>(self, seed: T) -> Result<T::Value, BridgeError> {
        seed.deserialize(LuaDeserializer {
            v: self.value.unwrap_or(Value::Nil),
        })
    }
    fn tuple_variant<V: Visitor<'de>>(self, _len: usize, visitor: V) -> Result<V::Value, BridgeError> {
        de::Deserializer::deserialize_seq(
            LuaDeserializer {
                v: self.value.unwrap_or(Value::Nil),
            },
            visitor,
        )
    }
    fn struct_variant<V: Visitor<'de>>(self, _: &'static [&'static str], visitor: V) -> Result<V::Value, BridgeError> {
        de::Deserializer::deserialize_map(
            LuaDeserializer {
                v: self.value.unwrap_or(Value::Nil),
            },
            visitor,
        )
    }
}

/// Convert a Lua value into a `serde_json::Value` (functions dropped).
pub fn lua_to_json(v: &Value) -> serde_json::Value {
    match v {
        Value::Nil => serde_json::Value::Null,
        Value::Bool(b) => serde_json::Value::Bool(*b),
        Value::Num(n) => {
            if n.fract() == 0.0 && n.abs() < 9.0e15 {
                serde_json::Value::Number((*n as i64).into())
            } else {
                serde_json::Number::from_f64(*n)
                    .map(serde_json::Value::Number)
                    .unwrap_or(serde_json::Value::Null)
            }
        }
        Value::Str(s) => serde_json::Value::String(String::from_utf8_lossy(s).to_string()),
        Value::Table(t) => {
            if table_is_array(t) {
                serde_json::Value::Array(table_array(t).iter().map(lua_to_json).collect())
            } else {
                let mut m = serde_json::Map::new();
                for (k, v) in table_entries(t) {
                    let key = match k {
                        Value::Str(s) => String::from_utf8_lossy(&s).to_string(),
                        Value::Num(n) => super::lexer::format_num(n),
                        Value::Bool(b) => b.to_string(),
                        _ => continue,
                    };
                    m.insert(key, lua_to_json(&v));
                }
                serde_json::Value::Object(m)
            }
        }
        Value::Func(_) => serde_json::Value::Null,
    }
}

pub fn json_to_lua(v: &serde_json::Value) -> Value {
    match v {
        serde_json::Value::Null => Value::Nil,
        serde_json::Value::Bool(b) => Value::Bool(*b),
        serde_json::Value::Number(n) => Value::Num(n.as_f64().unwrap_or(0.0)),
        serde_json::Value::String(s) => Value::str(s),
        serde_json::Value::Array(a) => {
            let t = TableRef::new();
            for (i, x) in a.iter().enumerate() {
                let _ = t.set(Value::Num((i + 1) as f64), json_to_lua(x));
            }
            Value::Table(t)
        }
        serde_json::Value::Object(o) => {
            let t = TableRef::new();
            for (k, x) in o {
                t.set_str(k, json_to_lua(x));
            }
            Value::Table(t)
        }
    }
}

pub fn yaml_to_lua(v: &serde_yaml::Value) -> Value {
    match v {
        serde_yaml::Value::Null => Value::Nil,
        serde_yaml::Value::Bool(b) => Value::Bool(*b),
        serde_yaml::Value::Number(n) => Value::Num(n.as_f64().unwrap_or(0.0)),
        serde_yaml::Value::String(s) => Value::str(s),
        serde_yaml::Value::Sequence(a) => {
            let t = TableRef::new();
            for (i, x) in a.iter().enumerate() {
                let _ = t.set(Value::Num((i + 1) as f64), yaml_to_lua(x));
            }
            Value::Table(t)
        }
        serde_yaml::Value::Mapping(m) => {
            let t = TableRef::new();
            for (k, x) in m {
                let key = yaml_to_lua(k);
                let _ = t.set(key, yaml_to_lua(x));
            }
            Value::Table(t)
        }
        serde_yaml::Value::Tagged(tg) => yaml_to_lua(&tg.value),
    }
}

pub fn lua_to_yaml(v: &Value) -> serde_yaml::Value {
    match v {
        Value::Nil => serde_yaml::Value::Null,
        Value::Bool(b) => serde_yaml::Value::Bool(*b),
        Value::Num(n) => {
            if n.fract() == 0.0 && n.abs() < 9.0e15 {
                serde_yaml::Value::Number((*n as i64).into())
            } else {
                serde_yaml::Value::Number((*n).into())
            }
        }
        Value::Str(s) => serde_yaml::Value::String(String::from_utf8_lossy(s).to_string()),
        Value::Table(t) => {
            if table_is_array(t) {
                serde_yaml::Value::Sequence(table_array(t).iter().map(lua_to_yaml).collect())
            } else {
                let mut m = serde_yaml::Mapping::new();
                for (k, v) in table_entries(t) {
                    m.insert(lua_to_yaml(&k), lua_to_yaml(&v));
                }
                serde_yaml::Value::Mapping(m)
            }
        }
        Value::Func(_) => serde_yaml::Value::Null,
    }
}

pub fn rc_str(s: &str) -> LStr {
    Rc::from(s.as_bytes())
}
