                serde_json::from_str(&s).map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![serde_bridge::json_to_lua(&v)])
        });
        reg("to_json", |_, args| {
            let v = serde_bridge::lua_to_json(&arg(&args, 0));
            let pretty = match args.get(1) {
                Some(Value::Table(t)) => t.get_str("pretty").truthy(),
                _ => false,
            };
            let s = if pretty {
                serde_json::to_string_pretty(&v)
            } else {
                serde_json::to_string(&v)
            }
            .map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![Value::str(&s)])
        });
        reg("from_yaml", |_, args| {
            let s = arg_string(&args, 0, "from_yaml")?;
            let v: serde_yaml::Value =
                serde_yaml::from_str(&s).map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![serde_bridge::yaml_to_lua(&v)])
        });
        reg("to_yaml", |_, args| {
            let v = serde_bridge::lua_to_yaml(&arg(&args, 0));
            let s = serde_yaml::to_string(&v).map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![Value::str(s.trim_end())])
        });
        let ls = self.lscolors.clone();
        util.set_str(
            "lscolor",
            native("lscolor", move |_, args| {
                let p = arg_string(&args, 0, "lscolor")?;
                let style = ls.style_for_path(Path::new(&p)).unwrap_or_default();
                let style = Style {
                    add_modifiers: Some(style.add_modifiers.unwrap_or_default()),
                    sub_modifiers: Some(style.sub_modifiers.unwrap_or_default()),
                    ..style
                };
                Ok(vec![to_lua(&style).map_err(lerr)?])
            }),
        );
        reg("paint", |_, args| {
            let s = arg_string(&args, 0, "paint")?;
            let style = style_from_lua(&arg(&args, 1))?;
            Ok(vec![Value::str(&paint(&s, &style))])
        });
        reg("style_mix", |_, args| {
            let t = arg_table(&args, 0, "style_mix")?;
            let mut style = Style::default();
            for i in 1..=t.len() {
                let s = style_from_lua(&t.get(&Value::Num(i as f64)))?;
                style = style.extend(&s);
            }
            let style = Style {
                add_modifiers: Some(style.add_modifiers.unwrap_or_default()),
                sub_modifiers: Some(style.sub_modifiers.unwrap_or_default()),
                ..style
            };
            Ok(vec![to_lua(&style).map_err(lerr)?])
        });
        reg("textwrap", |_, args| {
            let s = arg_string(&args, 0, "textwrap")?;
            let (width, initial, subsequent, break_words) = match args.get(1) {
                Some(Value::Table(t)) => (
                    t.get_str("width").as_num().unwrap_or(80.0) as usize,
                    t.get_str("initial_indent").as_str_lossy().unwrap_or_default(),
                    t.get_str("subsequent_indent").as_str_lossy().unwrap_or_default(),
                    match t.get_str("break_words") {
                        Value::Nil => true,
                        v => v.truthy(),
                    },
                ),
                Some(v) => (v.as_num().unwrap_or(80.0) as usize, String::new(), String::new(), true),
                None => (80, String::new(), String::new(), true),
            };
            let lines = textwrap(&s, width, &initial, &subsequent, break_words);
            let t = TableRef::new();
            for l in lines {
                t.push(Value::str(&l));
            }
            Ok(vec![Value::Table(t)])
        });
        reg("layout_replace", |_, args| {
            let layout: Layout = from_lua(arg(&args, 0)).map_err(lerr)?;
            let target: Layout = from_lua(arg(&args, 1)).map_err(lerr)?;
            let replacement: Layout = from_lua(arg(&args, 2)).map_err(lerr)?;
            let r = layout.replace(&target, &replacement);
            Ok(vec![to_lua(&r).map_err(lerr)?])
        });
        reg("permissions_rwx", |_, args| {
            let p: Permissions = from_lua(arg(&args, 0)).map_err(lerr)?;
            Ok(vec![Value::str(&p.rwx())])
        });
        reg("permissions_octal", |_, args| {
            let p: Permissions = from_lua(arg(&args, 0)).map_err(lerr)?;
            let t = TableRef::new();
            for d in p.octal() {
                t.push(Value::Num(d as f64));
            }
            Ok(vec![Value::Table(t)])
        });
    }

    // ------------------------------------------------------------ config loading

    /// Run a config file against the current `xplr.config`, returning the
    /// updated config and the hooks it returned.
    pub fn load_config(&mut self, path: &Path, config: Config) -> Result<(Config, Hooks)> {
        // refresh xplr.config from the given config
        let cfg = to_lua(&config).map_err(|e| anyhow!("{}", e))?;
        self.xplr_table().set_str("config", cfg);
        let src = std::fs::read(path).map_err(|e| anyhow!("{}: {}", path.to_string_lossy(), e))?;
        let chunkname = path.to_string_lossy().to_string();
        let rets = {
            let mut it = self.interp.borrow_mut();
            it.exec(&src, &chunkname).map_err(|e| anyhow!("{}", e.message()))?
        };
        // version check
        let version = {
            let it = self.interp.borrow();
            it.globals.get_str("version")
        };
        let version = match version {
            Value::Str(s) => String::from_utf8_lossy(&s).to_string(),
            _ => bail!("'version' must be defined globally in {}", chunkname),
        };
        check_version(&version, &chunkname)?;
        let new_cfg: Config = from_lua(self.xplr_table().get_str("config"))
            .map_err(|e| anyhow!("{}", e))?;
        let hooks: Hooks = match rets.into_iter().next() {
            Some(Value::Table(t)) => from_lua(Value::Table(t)).map_err(|e| anyhow!("{}", e))?,
            _ => Hooks::default(),
        };
        Ok((new_cfg, hooks))
    }

    /// Replace `xplr.config` with the final config (e.g. after CLI overrides).
    pub fn sync_config(&self, config: &Config) -> Result<()> {
        let cfg = to_lua(config).map_err(|e| anyhow!("{}", e))?;
        self.xplr_table().set_str("config", cfg);
        Ok(())
    }

    // ------------------------------------------------------------ calls

    fn resolve_fn(&self, func: &str) -> Result<Value> {
        let xplr = self.xplr_table();
        let mut cur = xplr.get_str("fn");
        for part in func.split('.') {
            cur = match &cur {
                Value::Table(t) => t.get_str(part),
                _ => Value::Nil,
            };
        }
        match cur {
            Value::Func(_) => Ok(cur),
            Value::Nil => bail!("function not found: {}", func),
            other => bail!("{} is not a function (a {} value)", func, other.type_name()),
        }
    }

    fn call_fn(&self, f: &Value, args: Vec<Value>) -> Result<Vec<Value>> {
        let mut it = self.interp.borrow_mut();
        it.depth = 0;
        it.call(f, args).map_err(|e| anyhow!("{}", e.message()))
    }

    pub fn call(&self, func: &str, app: &App) -> Result<Vec<ExternalMsg>> {
        let f = self.resolve_fn(func)?;
        let arg = to_lua(&CallLuaArg::from_app(app, false)).map_err(|e| anyhow!("{}", e))?;
        let rets = self.call_fn(&f, vec![arg])?;
        msgs_from(rets)
    }

    pub fn eval(&self, code: &str, app: &App) -> Result<Vec<ExternalMsg>> {
        let f = {
            let it = self.interp.borrow();
            it.load(code.as_bytes(), code)
                .map_err(|e| anyhow!("{}", e.message()))?
        };
        let rets = self.call_fn(&f, vec![])?;
        // if the result is callable, call it with the context
        if let Some(Value::Func(_)) = rets.first() {
            let f = rets[0].clone();
            let arg = to_lua(&CallLuaArg::from_app(app, false)).map_err(|e| anyhow!("{}", e))?;
            let rets = self.call_fn(&f, vec![arg])?;
            return msgs_from(rets);
        }
        msgs_from(rets)
    }

    fn renderer_arg(&self, app: &App, screen: Rect, area: Rect) -> Result<Value> {
        let arg = ContentRendererArg {
            layout_size: area.into(),
            screen_size: screen.into(),
            scrolltop: app.scroll_top,
            app: CallLuaArg::from_app(app, true),
        };
        to_lua(&arg).map_err(|e| anyhow!("{}", e))
    }

    pub fn render_dynamic(&self, func: &str, app: &App, screen: Rect, area: Rect) -> Result<CustomPanel> {
        let f = self.resolve_fn(func)?;
        let arg = self.renderer_arg(app, screen, area)?;
        let rets = self.call_fn(&f, vec![arg])?;
        let v = rets.into_iter().next().unwrap_or(Value::Nil);
        from_lua(v).map_err(|e| anyhow!("{}", e))
    }

    pub fn render_dynamic_string(&self, func: &str, app: &App, screen: Rect, area: Rect) -> Result<String> {
        let f = self.resolve_fn(func)?;
        let arg = self.renderer_arg(app, screen, area)?;
        let rets = self.call_fn(&f, vec![arg])?;
        Ok(rets
            .into_iter()
            .next()
            .map(|v| String::from_utf8_lossy(&tostring_basic(&v)).to_string())
            .unwrap_or_default())
    }

    pub fn render_dynamic_list(&self, func: &str, app: &App, screen: Rect, area: Rect) -> Result<Vec<String>> {
        let f = self.resolve_fn(func)?;
        let arg = self.renderer_arg(app, screen, area)?;
        let rets = self.call_fn(&f, vec![arg])?;
        let v = rets.into_iter().next().unwrap_or(Value::Nil);
        from_lua(v).map_err(|e| anyhow!("{}", e))
    }

    pub fn render_dynamic_table(&self, func: &str, app: &App, screen: Rect, area: Rect) -> Result<Vec<Vec<String>>> {
        let f = self.resolve_fn(func)?;
        let arg = self.renderer_arg(app, screen, area)?;
        let rets = self.call_fn(&f, vec![arg])?;
        let v = rets.into_iter().next().unwrap_or(Value::Nil);
        from_lua(v).map_err(|e| anyhow!("{}", e))
    }

    pub fn render_column(&self, func: &str, row: &RowInfo, _app: &App) -> Result<String> {
        let f = self.resolve_fn(func)?;
        let arg = to_lua(row).map_err(|e| anyhow!("{}", e))?;
        let rets = self.call_fn(&f, vec![arg])?;
        Ok(rets
            .into_iter()
            .next()
            .map(|v| String::from_utf8_lossy(&tostring_basic(&v)).to_string())
            .unwrap_or_default())
    }

    pub fn render_selection_item(&self, func: &str, node: &Node, _app: &App) -> Result<String> {
        let f = self.resolve_fn(func)?;
        let arg = to_lua(node).map_err(|e| anyhow!("{}", e))?;
        let rets = self.call_fn(&f, vec![arg])?;
        Ok(rets
            .into_iter()
            .next()
            .map(|v| String::from_utf8_lossy(&tostring_basic(&v)).to_string())
            .unwrap_or_default())
    }
}

fn msgs_from(rets: Vec<Value>) -> Result<Vec<ExternalMsg>> {
    match rets.into_iter().next() {
        None | Some(Value::Nil) => Ok(vec![]),
        Some(v) => from_lua::<Vec<ExternalMsg>>(v).map_err(|e| anyhow!("{}", e)),
    }
}

pub fn check_version(version: &str, path: &str) -> Result<()> {
    let mut parts = version.split('.');
    let major: u16 = parts.next().unwrap_or("").parse()?;
    let minor: u16 = parts.next().unwrap_or("").parse()?;
    let patch_s = parts.next().unwrap_or("");
    let patch: u16 = patch_s.split('-').next().unwrap_or("").parse()?;
    let extra = parts.next().is_some();
    let mut app_parts = VERSION.split('.');
    let amajor: u16 = app_parts.next().unwrap_or("0").parse().unwrap_or(0);
    let aminor: u16 = app_parts.next().unwrap_or("0").parse().unwrap_or(0);
    let apatch: u16 = app_parts.next().unwrap_or("0").parse().unwrap_or(0);
    let compatible = !extra && major == amajor && minor <= aminor && patch <= apatch;
    if !compatible {
        bail!(
            "incompatible script version in: {}. The script version is: {}, the required version is: {}. Visit https://xplr.dev/en/upgrade-guide",
            path,
            version,
            VERSION
        );
    }
    Ok(())
}

fn relativity_from_lua(v: Option<&Value>) -> Result<RelativityConfig, LuaError> {
    match v {
        Some(Value::Table(t)) => Ok(RelativityConfig {
            base: t.get_str("base").as_str_lossy(),
            with_prefix_dots: t.get_str("with_prefix_dots").truthy(),
            without_suffix_dots: t.get_str("without_suffix_dots").truthy(),
        }),
        _ => Ok(RelativityConfig::default()),
    }
}

pub fn node_type_of(types: &NodeTypesConfig, node: &Node) -> NodeTypeConfig {
    let mut cfg = if node.is_symlink {
        types.symlink.clone()
    } else if node.is_dir {
        types.directory.clone()
    } else {
        types.file.clone()
    };
    if let Some((t, sub)) = node.mime_essence.split_once('/') {
        if let Some(m) = types.mime_essence.get(t) {
            if let Some(c) = m.get("*") {
                cfg = cfg.extend(c);
            }
            if let Some(c) = m.get(sub) {
                cfg = cfg.extend(c);
            }
        }
    }
    if let Some(c) = types.extension.get(&node.extension) {
        cfg = cfg.extend(c);
    }
    if let Some(c) = types.special.get(&node.relative_path) {
        cfg = cfg.extend(c);
    }
    cfg
}

fn deep_clone(v: &Value) -> Value {
    match v {
        Value::Table(t) => {
            let n = TableRef::new();
            let mut k = Value::Nil;
            while let Ok(Some((nk, nv))) = t.next(&k) {
                let _ = n.set(deep_clone(&nk), deep_clone(&nv));
                k = nk;
            }
            n.set_metatable(t.metatable());
            Value::Table(n)
        }
        other => other.clone(),
    }
}

fn debug_repr(it: &mut Interp, v: &Value, indent: usize) -> String {
    match v {
        Value::Str(s) => format!("{:?}", String::from_utf8_lossy(s)),
        Value::Table(t) => {
            let pad = "  ".repeat(indent + 1);
            let mut out = String::from("{\n");
            let mut k = Value::Nil;
            while let Ok(Some((nk, nv))) = t.next(&k) {
                let key = match &nk {
                    Value::Str(s) => format!("[{:?}]", String::from_utf8_lossy(s)),
                    other => format!("[{}]", String::from_utf8_lossy(&tostring_basic(other))),
                };
                out.push_str(&format!("{}{} = {},\n", pad, key, debug_repr(it, &nv, indent + 1)));
                k = nk;
            }
            out.push_str(&"  ".repeat(indent));
            out.push('}');
            out
        }
        other => String::from_utf8_lossy(&tostring_basic(other)).to_string(),
    }
}

fn textwrap(text: &str, width: usize, initial: &str, subsequent: &str, break_words: bool) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    for para in text.split('\n') {
        let mut line = String::from(initial);
        let mut line_has_word = false;
        for word in para.split_whitespace() {
            let indent_len = if lines.is_empty() { initial.len() } else { subsequent.len() };
            let candidate_len = line.chars().count() + if line_has_word { 1 } else { 0 } + word.chars().count();
            if candidate_len <= width || !line_has_word && line.chars().count() == indent_len && !break_words {
                if line_has_word {
                    line.push(' ');
                }
                line.push_str(word);
                line_has_word = true;
            } else if !line_has_word && break_words {
                // word longer than width: break it
                let mut w = word.to_string();
                loop {
                    let avail = width.saturating_sub(line.chars().count()).max(1);
                    let chunk: String = w.chars().take(avail).collect();
                    let rest: String = w.chars().skip(avail).collect();
                    line.push_str(&chunk);
                    if rest.is_empty() {
                        line_has_word = true;
                        break;
                    }
                    lines.push(std::mem::take(&mut line));
                    line = String::from(subsequent);
                    w = rest;
                }
            } else {
                lines.push(std::mem::take(&mut line));
                line = String::from(subsequent);
                line.push_str(word);
                line_has_word = true;
            }
        }
        lines.push(line);
    }
    lines
}

pub fn lua_str(s: &str) -> Rc<[u8]> {
    Rc::from(s.as_bytes())
}
