/// Render spans into a string with ANSI escape codes.
pub fn spans_to_ansi(spans: &[ratatui::text::Span<'static>]) -> String {
    let mut out = String::new();
    for sp in spans {
        let style: Style = sp.style.into();
        out.push_str(&paint(&sp.content, &style));
    }
    out
}

fn color_code(c: &crate::config::Color, fg: bool) -> String {
    use crate::config::Color::*;
    let base = if fg { 30 } else { 40 };
    match c {
        Reset => (if fg { 39 } else { 49 }).to_string(),
        Black => base.to_string(),
        Red => (base + 1).to_string(),
        Green => (base + 2).to_string(),
        Yellow => (base + 3).to_string(),
        Blue => (base + 4).to_string(),
        Magenta => (base + 5).to_string(),
        Cyan => (base + 6).to_string(),
        Gray => (base + 7).to_string(),
        DarkGray => (base + 60).to_string(),
        LightRed => (base + 61).to_string(),
        LightGreen => (base + 62).to_string(),
        LightYellow => (base + 63).to_string(),
        LightBlue => (base + 64).to_string(),
        LightMagenta => (base + 65).to_string(),
        LightCyan => (base + 66).to_string(),
        White => (base + 67).to_string(),
        Rgb(r, g, b) => format!("{};2;{};{};{}", base + 8, r, g, b),
        Indexed(i) => format!("{};5;{}", base + 8, i),
    }
}

/// Apply a style to a string using escape sequences.
pub fn paint(text: &str, style: &Style) -> String {
    let mut codes: Vec<String> = Vec::new();
    if let Some(add) = &style.add_modifiers {
        for m in add {
            use crate::config::Modifier::*;
            codes.push(
                match m {
                    Bold => 1,
                    Dim => 2,
                    Italic => 3,
                    Underlined => 4,
                    SlowBlink => 5,
                    RapidBlink => 6,
                    Reversed => 7,
                    Hidden => 8,
                    CrossedOut => 9,
                }
                .to_string(),
            );
        }
    }
    if let Some(fg) = &style.fg {
        codes.push(color_code(fg, true));
    }
    if let Some(bg) = &style.bg {
        codes.push(color_code(bg, false));
    }
    if codes.is_empty() {
        return text.to_string();
    }
    format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
}

impl Runtime {
    pub fn new() -> Result<Self> {
        let mut it = Interp::new();
