    fn xplr_table(&self) -> TableRef {
        let it = self.interp.borrow();
        match it.globals.get_str("xplr") {
            Value::Table(t) => t,
            _ => TableRef::new(),
        }
    }

    fn setup_xplr(&self, config: &Config) -> Result<()> {
        let xplr = TableRef::new();
        let cfg = to_lua(config).map_err(|e| anyhow!("{}", e))?;
        xplr.set_str("config", cfg);

        let fn_table = TableRef::new();
        let builtin = TableRef::new();
        let lscolors = self.lscolors.clone();
        for i in 0..5 {
            let name = format!("fmt_general_table_row_cols_{}", i);
            let ls = lscolors.clone();
            builtin.set_str(
                &name,
                native(&name, move |_, args| {
                    let arg: RowInfo = from_lua(arg(&args, 0)).map_err(lerr)?;
                    let pwd = std::env::current_dir()
                        .map(|p| p.to_string_lossy().to_string())
                        .unwrap_or_default();
                    let spans = match i {
                        0 => ui::format_col_0(&arg),
                        1 => ui::format_col_1(&ls, &pwd, &arg),
                        2 => ui::format_col_2(&arg),
                        3 => ui::format_col_3(&arg),
                        _ => ui::format_col_4(&arg),
                    };
                    Ok(vec![Value::str(&spans_to_ansi(&spans))])
                }),
            );
        }
        let ls = lscolors.clone();
        builtin.set_str(
            "fmt_general_selection_item",
            native("fmt_general_selection_item", move |_, args| {
                let node: Node = from_lua(arg(&args, 0)).map_err(lerr)?;
                let pwd = std::env::current_dir()
                    .map(|p| p.to_string_lossy().to_string())
                    .unwrap_or_default();
                let mut s = path_util::shorten(
                    &node.absolute_path,
                    &RelativityConfig {
                        base: Some(pwd),
                        with_prefix_dots: true,
                        without_suffix_dots: true,
                    },
                )
                .unwrap_or_else(|_| node.absolute_path.clone());
                if node.is_dir {
                    s.push('/');
                }
                let style = ls
                    .style_for_path(Path::new(&node.absolute_path))
                    .unwrap_or_default();
                Ok(vec![Value::str(&paint(&s, &style))])
            }),
        );
        builtin.set_str(
            "try_complete_path",
            native("try_complete_path", |_, _| {
                let t = TableRef::new();
                t.push(Value::str("TryCompletePath"));
                Ok(vec![Value::Table(t)])
            }),
        );
        fn_table.set_str("builtin", Value::Table(builtin));
        fn_table.set_str("custom", Value::Table(TableRef::new()));
        xplr.set_str("fn", Value::Table(fn_table));

        let util = TableRef::new();
        self.setup_util(&util);
        xplr.set_str("util", Value::Table(util));

        let it = self.interp.borrow();
        it.globals.set_str("xplr", Value::Table(xplr));
        Ok(())
    }

    fn setup_util(&self, util: &TableRef) {
        let reg = |name: &str, f: fn(&mut Interp, Vec<Value>) -> Result<Vec<Value>, LuaError>| {
            util.set_str(name, native(name, f));
        };
        reg("version", |_, _| {
            let t = TableRef::new();
            let parts: Vec<&str> = VERSION.split('.').collect();
            t.set_str("major", Value::Num(parts.first().and_then(|p| p.parse().ok()).unwrap_or(0.0)));
            t.set_str("minor", Value::Num(parts.get(1).and_then(|p| p.parse().ok()).unwrap_or(0.0)));
            t.set_str("patch", Value::Num(parts.get(2).and_then(|p| p.parse().ok()).unwrap_or(0.0)));
            Ok(vec![Value::Table(t)])
        });
        reg("debug", |it, args| {
            let v = arg(&args, 0);
            let s = debug_repr(it, &v, 0);
            println!("{}", s);
            Ok(vec![Value::str(&s)])
        });
        reg("clone", |_, args| Ok(vec![deep_clone(&arg(&args, 0))]));
        reg("exists", |_, args| {
            let p = arg_string(&args, 0, "exists")?;
            Ok(vec![Value::Bool(Path::new(&p).exists())])
        });
        reg("is_dir", |_, args| {
            let p = arg_string(&args, 0, "is_dir")?;
            Ok(vec![Value::Bool(Path::new(&p).is_dir())])
        });
        reg("is_file", |_, args| {
            let p = arg_string(&args, 0, "is_file")?;
            Ok(vec![Value::Bool(Path::new(&p).is_file())])
        });
        reg("is_symlink", |_, args| {
            let p = arg_string(&args, 0, "is_symlink")?;
            Ok(vec![Value::Bool(
                Path::new(&p)
                    .symlink_metadata()
                    .map(|m| m.file_type().is_symlink())
                    .unwrap_or(false),
            )])
        });
        reg("is_absolute", |_, args| {
            let p = arg_string(&args, 0, "is_absolute")?;
            Ok(vec![Value::Bool(Path::new(&p).is_absolute())])
        });
        reg("path_split", |_, args| {
            let p = arg_string(&args, 0, "path_split")?;
            let t = TableRef::new();
            for c in path_util::split(&p) {
                t.push(Value::str(&c));
            }
            Ok(vec![Value::Table(t)])
        });
        reg("node", |_, args| {
            let p = arg_string(&args, 0, "node")?;
            let abs = path_util::absolutize(Path::new(&p))
                .map_err(|e| LuaError::msg(&e.to_string()))?;
            match Node::from_path(&abs) {
                Some(n) => Ok(vec![to_lua(&n).map_err(lerr)?]),
                None => Ok(vec![Value::Nil]),
            }
        });
        reg("node_type", |it, args| {
            let node: Node = from_lua(arg(&args, 0)).map_err(lerr)?;
            let types: NodeTypesConfig = match args.get(1) {
                Some(v) if !matches!(v, Value::Nil) => from_lua(v.clone()).map_err(lerr)?,
                _ => {
                    let xplr = it.globals.get_str("xplr");
                    let cfg = match &xplr {
                        Value::Table(t) => t.get_str("config"),
                        _ => Value::Nil,
                    };
                    let nt = match &cfg {
                        Value::Table(t) => t.get_str("node_types"),
                        _ => Value::Nil,
                    };
                    from_lua(nt).map_err(lerr)?
                }
            };
            let cfg = node_type_of(&types, &node);
            Ok(vec![to_lua(&cfg).map_err(lerr)?])
        });
        reg("dirname", |_, args| {
            let p = arg_string(&args, 0, "dirname")?;
            Ok(vec![match path_util::dirname(&p) {
                Some(d) => Value::str(&d),
                None => Value::Nil,
            }])
        });
        reg("basename", |_, args| {
            let p = arg_string(&args, 0, "basename")?;
            Ok(vec![match path_util::basename(&p) {
                Some(d) => Value::str(&d),
                None => Value::Nil,
            }])
        });
        reg("absolute", |_, args| {
            let p = arg_string(&args, 0, "absolute")?;
            let abs = path_util::absolutize(Path::new(&p))
                .map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![Value::str(&abs.to_string_lossy())])
        });
        reg("relative_to", |_, args| {
            let p = arg_string(&args, 0, "relative_to")?;
            let cfg = relativity_from_lua(args.get(1))?;
            let r = path_util::relative_to(&p, &cfg).map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![Value::str(&r)])
        });
        reg("shorten", |_, args| {
            let p = arg_string(&args, 0, "shorten")?;
            let cfg = relativity_from_lua(args.get(1))?;
            let r = path_util::shorten(&p, &cfg).map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![Value::str(&r)])
        });
        reg("explore", |_, args| {
            let p = arg_string(&args, 0, "explore")?;
            let cfg: ExplorerConfig = match args.get(1) {
                Some(v) if !matches!(v, Value::Nil) => from_lua(v.clone()).map_err(lerr)?,
                _ => ExplorerConfig::default(),
            };
            let nodes = crate::explorer::explore(Path::new(&p), &cfg)
                .map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![to_lua(&nodes).map_err(lerr)?])
        });
        reg("shell_execute", |_, args| {
            let program = arg_string(&args, 0, "shell_execute")?;
            let cmd_args: Vec<String> = match args.get(1) {
                Some(Value::Table(t)) => {
                    let n = t.len();
                    (1..=n)
                        .map(|i| String::from_utf8_lossy(&tostring_basic(&t.get(&Value::Num(i as f64)))).to_string())
                        .collect()
                }
                _ => vec![],
            };
            let out = std::process::Command::new(&program)
                .args(&cmd_args)
                .output()
                .map_err(|e| LuaError::msg(&e.to_string()))?;
            let t = TableRef::new();
            t.set_str("stdout", Value::bytes(&out.stdout));
            t.set_str("stderr", Value::bytes(&out.stderr));
            t.set_str(
                "returncode",
                match out.status.code() {
                    Some(c) => Value::Num(c as f64),
                    None => Value::Nil,
