            Ok(vec![Value::Table(t)])
        });
        reg("shell_quote", |_, args| {
            let s = arg_string(&args, 0, "shell_quote")?;
            Ok(vec![Value::str(&shell::quote(&s))])
        });
        reg("shell_escape", |_, args| {
            let s = arg_string(&args, 0, "shell_escape")?;
            Ok(vec![Value::str(&shell::escape(&s))])
        });
        reg("from_json", |_, args| {
            let s = arg_string(&args, 0, "from_json")?;
            let v: serde_json::Value =
                serde_json::from_str(&s).map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![serde_bridge::json_to_lua(&v)])
        });
        reg("to_json", |_, args| {
            let v = serde_bridge::lua_to_json(&arg(&args, 0));
            let pretty = match args.get(1) {
                Some(Value::Table(t)) => t.get_str("pretty").truthy(),
                _ => false,
            };
            let s = if pretty {
                serde_json::to_string_pretty(&v)
            } else {
                serde_json::to_string(&v)
            }
            .map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![Value::str(&s)])
        });
        reg("from_yaml", |_, args| {
            let s = arg_string(&args, 0, "from_yaml")?;
            let v: serde_yaml::Value =
                serde_yaml::from_str(&s).map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![serde_bridge::yaml_to_lua(&v)])
        });
        reg("to_yaml", |_, args| {
            let v = serde_bridge::lua_to_yaml(&arg(&args, 0));
            let s = serde_yaml::to_string(&v).map_err(|e| LuaError::msg(&e.to_string()))?;
            Ok(vec![Value::str(s.trim_end())])
        });
        let ls = self.lscolors.clone();
        util.set_str(
            "lscolor",
            native("lscolor", move |_, args| {
                let p = arg_string(&args, 0, "lscolor")?;
                let style = ls.style_for_path(Path::new(&p)).unwrap_or_default();
                let style = Style {
                    add_modifiers: Some(style.add_modifiers.unwrap_or_default()),
                    sub_modifiers: Some(style.sub_modifiers.unwrap_or_default()),
                    ..style
                };
                Ok(vec![to_lua(&style).map_err(lerr)?])
            }),
        );
        reg("paint", |_, args| {
            let s = arg_string(&args, 0, "paint")?;
            let style = style_from_lua(&arg(&args, 1))?;
            Ok(vec![Value::str(&paint(&s, &style))])
        });
        reg("style_mix", |_, args| {
            let t = arg_table(&args, 0, "style_mix")?;
            let mut style = Style::default();
            for i in 1..=t.len() {
                let s = style_from_lua(&t.get(&Value::Num(i as f64)))?;
                style = style.extend(&s);
            }
            let style = Style {
                add_modifiers: Some(style.add_modifiers.unwrap_or_default()),
                sub_modifiers: Some(style.sub_modifiers.unwrap_or_default()),
                ..style
            };
            Ok(vec![to_lua(&style).map_err(lerr)?])
        });
        reg("textwrap", |_, args| {
            let s = arg_string(&args, 0, "textwrap")?;
            let (width, initial, subsequent, break_words) = match args.get(1) {
                Some(Value::Table(t)) => (
                    t.get_str("width").as_num().unwrap_or(80.0) as usize,
                    t.get_str("initial_indent").as_str_lossy().unwrap_or_default(),
                    t.get_str("subsequent_indent").as_str_lossy().unwrap_or_default(),
                    match t.get_str("break_words") {
                        Value::Nil => true,
                        v => v.truthy(),
                    },
                ),
                Some(v) => (v.as_num().unwrap_or(80.0) as usize, String::new(), String::new(), true),
                None => (80, String::new(), String::new(), true),
            };
            let lines = textwrap(&s, width, &initial, &subsequent, break_words);
            let t = TableRef::new();
