    // ------------------------------------------------------------ config loading

    /// Run a config file against the current `xplr.config`, returning the
    /// updated config and the hooks it returned.
    pub fn load_config(&mut self, path: &Path, config: Config) -> Result<(Config, Hooks)> {
        // refresh xplr.config from the given config
        let cfg = to_lua(&config).map_err(|e| anyhow!("{}", e))?;
        self.xplr_table().set_str("config", cfg);
        let src = std::fs::read(path).map_err(|e| anyhow!("{}: {}", path.to_string_lossy(), e))?;
        let chunkname = path.to_string_lossy().to_string();
        let rets = {
            let mut it = self.interp.borrow_mut();
            it.exec(&src, &chunkname).map_err(|e| anyhow!("{}", e.message()))?
        };
        // version check
        let version = {
            let it = self.interp.borrow();
            it.globals.get_str("version")
        };
        let version = match version {
            Value::Str(s) => String::from_utf8_lossy(&s).to_string(),
            _ => bail!("'version' must be defined globally in {}", chunkname),
        };
        check_version(&version, &chunkname)?;
        let new_cfg: Config = from_lua(self.xplr_table().get_str("config"))
            .map_err(|e| anyhow!("{}", e))?;
        let hooks: Hooks = match rets.into_iter().next() {
            Some(Value::Table(t)) => from_lua(Value::Table(t)).map_err(|e| anyhow!("{}", e))?,
            _ => Hooks::default(),
        };
        Ok((new_cfg, hooks))
    }

    /// Replace `xplr.config` with the final config (e.g. after CLI overrides).
    pub fn sync_config(&self, config: &Config) -> Result<()> {
        let cfg = to_lua(config).map_err(|e| anyhow!("{}", e))?;
        self.xplr_table().set_str("config", cfg);
        Ok(())
    }

    // ------------------------------------------------------------ calls

    fn resolve_fn(&self, func: &str) -> Result<Value> {
        let xplr = self.xplr_table();
        let mut cur = xplr.get_str("fn");
        for part in func.split('.') {
            cur = match &cur {
                Value::Table(t) => t.get_str(part),
                _ => Value::Nil,
            };
        }
        match cur {
            Value::Func(_) => Ok(cur),
            Value::Nil => bail!("function not found: {}", func),
            other => bail!("{} is not a function (a {} value)", func, other.type_name()),
        }
    }

    fn call_fn(&self, f: &Value, args: Vec<Value>) -> Result<Vec<Value>> {
        let mut it = self.interp.borrow_mut();
        it.depth = 0;
        it.call(f, args).map_err(|e| anyhow!("{}", e.message()))
    }

    pub fn call(&self, func: &str, app: &App) -> Result<Vec<ExternalMsg>> {
        let f = self.resolve_fn(func)?;
        let arg = to_lua(&CallLuaArg::from_app(app, false)).map_err(|e| anyhow!("{}", e))?;
        let rets = self.call_fn(&f, vec![arg])?;
        msgs_from(rets)
    }

    pub fn eval(&self, code: &str, app: &App) -> Result<Vec<ExternalMsg>> {
        let f = {
            let it = self.interp.borrow();
            it.load(code.as_bytes(), code)
                .map_err(|e| anyhow!("{}", e.message()))?
        };
        let rets = self.call_fn(&f, vec![])?;
        // if the result is callable, call it with the context
        if let Some(Value::Func(_)) = rets.first() {
            let f = rets[0].clone();
            let arg = to_lua(&CallLuaArg::from_app(app, false)).map_err(|e| anyhow!("{}", e))?;
            let rets = self.call_fn(&f, vec![arg])?;
            return msgs_from(rets);
        }
        msgs_from(rets)
    }

    fn renderer_arg(&self, app: &App, screen: Rect, area: Rect) -> Result<Value> {
        let arg = ContentRendererArg {
            layout_size: area.into(),
            screen_size: screen.into(),
            scrolltop: app.scroll_top,
            app: CallLuaArg::from_app(app, true),
        };
        to_lua(&arg).map_err(|e| anyhow!("{}", e))
    }

    pub fn render_dynamic(&self, func: &str, app: &App, screen: Rect, area: Rect) -> Result<CustomPanel> {
