fn msgs_from(rets: Vec<Value>) -> Result<Vec<ExternalMsg>> {
    match rets.into_iter().next() {
        None | Some(Value::Nil) => Ok(vec![]),
        Some(v) => from_lua::<Vec<ExternalMsg>>(v).map_err(|e| anyhow!("{}", e)),
    }
}

pub fn check_version(version: &str, path: &str) -> Result<()> {
    let mut parts = version.split('.');
    let major: u16 = parts.next().unwrap_or("").parse()?;
    let minor: u16 = parts.next().unwrap_or("").parse()?;
    let patch_s = parts.next().unwrap_or("");
    let patch: u16 = patch_s.split('-').next().unwrap_or("").parse()?;
    let extra = parts.next().is_some();
    let mut app_parts = VERSION.split('.');
    let amajor: u16 = app_parts.next().unwrap_or("0").parse().unwrap_or(0);
    let aminor: u16 = app_parts.next().unwrap_or("0").parse().unwrap_or(0);
    let apatch: u16 = app_parts.next().unwrap_or("0").parse().unwrap_or(0);
    let compatible = !extra && major == amajor && minor <= aminor && patch <= apatch;
    if !compatible {
        bail!(
            "incompatible script version in: {}. The script version is: {}, the required version is: {}. Visit https://xplr.dev/en/upgrade-guide",
            path,
            version,
            VERSION
        );
    }
    Ok(())
}

fn relativity_from_lua(v: Option<&Value>) -> Result<RelativityConfig, LuaError> {
    match v {
        Some(Value::Table(t)) => Ok(RelativityConfig {
            base: t.get_str("base").as_str_lossy(),
            with_prefix_dots: t.get_str("with_prefix_dots").truthy(),
            without_suffix_dots: t.get_str("without_suffix_dots").truthy(),
        }),
        _ => Ok(RelativityConfig::default()),
    }
}

pub fn node_type_of(types: &NodeTypesConfig, node: &Node) -> NodeTypeConfig {
    let mut cfg = if node.is_symlink {
        types.symlink.clone()
    } else if node.is_dir {
        types.directory.clone()
    } else {
        types.file.clone()
    };
    if let Some((t, sub)) = node.mime_essence.split_once('/') {
        if let Some(m) = types.mime_essence.get(t) {
            if let Some(c) = m.get("*") {
                cfg = cfg.extend(c);
            }
            if let Some(c) = m.get(sub) {
                cfg = cfg.extend(c);
            }
        }
    }
    if let Some(c) = types.extension.get(&node.extension) {
        cfg = cfg.extend(c);
    }
    if let Some(c) = types.special.get(&node.relative_path) {
        cfg = cfg.extend(c);
    }
    cfg
}

fn deep_clone(v: &Value) -> Value {
    match v {
        Value::Table(t) => {
            let n = TableRef::new();
            let mut k = Value::Nil;
            while let Ok(Some((nk, nv))) = t.next(&k) {
                let _ = n.set(deep_clone(&nk), deep_clone(&nv));
                k = nk;
            }
            n.set_metatable(t.metatable());
            Value::Table(n)
        }
        other => other.clone(),
    }
}

fn debug_repr(it: &mut Interp, v: &Value, indent: usize) -> String {
    match v {
        Value::Str(s) => format!("{:?}", String::from_utf8_lossy(s)),
        Value::Table(t) => {
            let pad = "  ".repeat(indent + 1);
            let mut out = String::from("{\n");
            let mut k = Value::Nil;
            while let Ok(Some((nk, nv))) = t.next(&k) {
                let key = match &nk {
                    Value::Str(s) => format!("[{:?}]", String::from_utf8_lossy(s)),
                    other => format!("[{}]", String::from_utf8_lossy(&tostring_basic(other))),
                };
                out.push_str(&format!("{}{} = {},\n", pad, key, debug_repr(it, &nv, indent + 1)));
                k = nk;
            }
            out.push_str(&"  ".repeat(indent));
            out.push('}');
            out
        }
        other => String::from_utf8_lossy(&tostring_basic(other)).to_string(),
    }
}

fn textwrap(text: &str, width: usize, initial: &str, subsequent: &str, break_words: bool) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    for para in text.split('\n') {
        let mut line = String::from(initial);
        let mut line_has_word = false;
        for word in para.split_whitespace() {
            let indent_len = if lines.is_empty() { initial.len() } else { subsequent.len() };
            let candidate_len = line.chars().count() + if line_has_word { 1 } else { 0 } + word.chars().count();
            if candidate_len <= width || !line_has_word && line.chars().count() == indent_len && !break_words {
                if line_has_word {
                    line.push(' ');
                }
                line.push_str(word);
                line_has_word = true;
            } else if !line_has_word && break_words {
                // word longer than width: break it
                let mut w = word.to_string();
                loop {
                    let avail = width.saturating_sub(line.chars().count()).max(1);
                    let chunk: String = w.chars().take(avail).collect();
                    let rest: String = w.chars().skip(avail).collect();
                    line.push_str(&chunk);
                    if rest.is_empty() {
                        line_has_word = true;
                        break;
                    }
                    lines.push(std::mem::take(&mut line));
                    line = String::from(subsequent);
                    w = rest;
                }
            } else {
                lines.push(std::mem::take(&mut line));
                line = String::from(subsequent);
                line.push_str(word);
                line_has_word = true;
            }
        }
        lines.push(line);
    }
    lines
}

pub fn lua_str(s: &str) -> Rc<[u8]> {
    Rc::from(s.as_bytes())
}
