const BONUS_FIRST_CHAR: i64 = 2;
const BONUS_BREAK: i64 = 7;
const BONUS_PUNCT: i64 = 6;
const BONUS_CAMEL: i64 = 6;
const BONUS_CONSECUTIVE: i64 = 4;
const GAP_START: i64 = -3;
const GAP_EXTENSION: i64 = -1;
const PENALTY_CASE_MISMATCH: i64 = -2;

#[derive(Debug, Clone)]
pub struct MatchResult {
    pub score: i64,
    pub begin: usize,
    pub end: usize,
    pub indices: Vec<usize>,
}

pub struct Matcher {
    exact: bool,
}

#[derive(Clone, Copy, PartialEq)]
enum CharType {
    Lower,
    Upper,
    Number,
    Word,
    Break,
    Punct,
}

fn char_type(c: char) -> CharType {
    if c.is_lowercase() {
        CharType::Lower
    } else if c.is_uppercase() {
        CharType::Upper
    } else if c.is_numeric() {
        CharType::Number
    } else if c.is_alphanumeric() {
        CharType::Word
    } else if c.is_whitespace() || matches!(c, '(' | ')' | '[' | ']' | '{' | '}' | '|' | '\\') {
        CharType::Break
    } else if c.is_ascii_punctuation() {
        CharType::Punct
    } else {
        CharType::Word
    }
}

fn in_place_bonus(prev: Option<char>, cur: char) -> i64 {
    match prev {
        None => BONUS_HEAD,
        Some(p) => match (char_type(p), char_type(cur)) {
            (CharType::Break, _) => BONUS_BREAK,
            (CharType::Punct, _) => BONUS_PUNCT,
            (CharType::Lower, CharType::Upper) => BONUS_CAMEL,
            (p, CharType::Number) if p != CharType::Number => BONUS_CAMEL,
            _ => 0,
        },
    }
}

fn char_eq(a: char, b: char, case_sensitive: bool) -> bool {
    if case_sensitive {
        a == b
    } else {
        a == b || a.to_lowercase().eq(b.to_lowercase())
    }
}

impl Matcher {
    pub fn new(exact: bool) -> Self {
        Matcher { exact }
    }

    pub fn match_str(&self, choice: &str, pattern: &str) -> Option<MatchResult> {
        if self.exact {
            return self.exact_match(choice, pattern);
        }
        self.fuzzy_match(choice, pattern)
