        };
        let byte_pos = c.find(&p)?;
        let begin = c[..byte_pos].chars().count();
        let plen = p.chars().count();
        let end = begin + plen;
        let indices: Vec<usize> = (begin..end).collect();
        // Score the exact range with the fuzzy scoring rules.
        let chars: Vec<char> = choice.chars().collect();
        let mut score = 0;
        for (k, &j) in indices.iter().enumerate() {
            let prev = if j == 0 { None } else { Some(chars[j - 1]) };
            let ip = in_place_bonus(prev, chars[j]);
            score += SCORE_MATCH;
            if k == 0 {
                score += if j == 0 { BONUS_HEAD } else { ip + BONUS_FIRST_CHAR };
            } else {
                score += BONUS_CONSECUTIVE.max(ip);
            }
        }
        Some(MatchResult {
            score,
            begin,
            end,
            indices,
        })
    }

    fn fuzzy_match(&self, choice: &str, pattern: &str) -> Option<MatchResult> {
        if pattern.is_empty() {
            return Some(MatchResult {
                score: 0,
                begin: 0,
                end: 0,
                indices: vec![],
            });
        }
        let case_sensitive = pattern.chars().any(|c| c.is_uppercase());
        let choice: Vec<char> = choice.chars().collect();
        let pattern: Vec<char> = pattern.chars().collect();
        let n = choice.len();
        let m = pattern.len();
        if m > n {
            return None;
        }

        // Quick subsequence check.
        {
            let mut pi = 0;
            for &c in &choice {
                if pi < m && char_eq(c, pattern[pi], case_sensitive) {
                    pi += 1;
                }
            }
            if pi < m {
                return None;
            }
        }

        let bonus: Vec<i64> = (0..n)
            .map(|j| {
                let prev = if j == 0 { None } else { Some(choice[j - 1]) };
                in_place_bonus(prev, choice[j])
            })
            .collect();

        const NEG: i64 = i64::MIN / 4;
        // mat[i][j]: best score with pattern[i] matched at choice[j]
        // gap[i][j]: best score of pattern[..=i] matched somewhere before j,
        //            followed by a gap that ends right before j (exclusive)
        let mut mat = vec![vec![NEG; n]; m];
        let mut from: Vec<Vec<Option<usize>>> = vec![vec![None; n]; m];
        for i in 0..m {
