            for j in 0..n {
                if i > 0 && j >= 1 {
                    // extend/start gap using the previous row's match at j-1
                    // (gap state refers to pattern[i-1] matched before j)
                    let start = if mat[i - 1][j - 1] > NEG {
                        mat[i - 1][j - 1] + GAP_START
                    } else {
                        NEG
                    };
                    let ext = if gap_best > NEG { gap_best + GAP_EXTENSION } else { NEG };
