                    // k+1..=j-1 skipped
                    if j >= 2 {
                        let cand_start = if mat[i - 1][j - 2] > NEG {
                            mat[i - 1][j - 2] + GAP_START
                        } else {
                            NEG
                        };
                        let cand_ext = ext;
                        if cand_start >= cand_ext {
                            gap_best = cand_start;
                            if cand_start > NEG {
                                gap_src = Some(j - 2);
                            }
                        } else {
                            gap_best = cand_ext;
                        }
                    } else {
                        gap_best = NEG;
                        gap_src = None;
                    }
                    let _ = start;
                }
                if !char_eq(choice[j], pattern[i], case_sensitive) {
                    continue;
                }
                let case_pen = if choice[j] == pattern[i] {
                    0
                } else {
                    PENALTY_CASE_MISMATCH
                };
                if i == 0 {
                    let first = if j == 0 {
                        BONUS_HEAD
                    } else {
                        bonus[j] + BONUS_FIRST_CHAR
                    };
                    mat[0][j] = SCORE_MATCH + first + case_pen;
                    continue;
                }
                let mut best = NEG;
                let mut src = None;
                if j >= 1 && mat[i - 1][j - 1] > NEG {
                    let cand = mat[i - 1][j - 1] + BONUS_CONSECUTIVE.max(bonus[j]);
                    if cand > best {
                        best = cand;
                        src = Some(j - 1);
                    }
                }
                if gap_best > NEG {
                    let cand = gap_best + bonus[j];
                    if cand > best {
                        best = cand;
                        src = gap_src;
                    }
                }
                if best > NEG {
                    mat[i][j] = best + SCORE_MATCH + case_pen;
                    from[i][j] = src;
                }
            }
        }

        let mut best_j = None;
        let mut best = NEG;
        for j in 0..n {
            if mat[m - 1][j] > NEG && mat[m - 1][j] >= best {
                best = mat[m - 1][j];
                best_j = Some(j);
            }
        }
        let mut j = best_j?;
        let mut indices = vec![0usize; m];
        for i in (0..m).rev() {
            indices[i] = j;
            if i > 0 {
                j = from[i][j]?;
            }
        }
        Some(MatchResult {
            score: best,
            begin: indices[0],
            end: indices[m - 1] + 1,
            indices,
        })
    }
}
