    config = { constraints = { { Percentage = 50 }, { Percentage = 50 } } },
    splits = {
      "Table",
      { Vertical = { config = { constraints = { { Length = 8 }, { Length = 10 }, { Min = 1 } } }, splits = {
        { Dynamic = "custom.render_para" },
        { Dynamic = "custom.render_list" },
        { Dynamic = "custom.render_table" },
      } } },
    },
  },
}
xplr.fn.custom.render_para = function(ctx)
  return {
    CustomParagraph = {
      ui = { title = { format = ctx.app.pwd }, style = { fg = "Cyan" } },
      body = "focus: " .. (ctx.app.focused_node and ctx.app.focused_node.relative_path or "nil") .. "\nmode: " .. ctx.app.mode.name .. "\nscrolltop: " .. tostring(ctx.scrolltop) .. "\nsize: " .. tostring(ctx.layout_size.width) .. "x" .. tostring(ctx.layout_size.height) .. " screen " .. tostring(ctx.screen_size.width) .. "x" .. tostring(ctx.screen_size.height),
    },
  }
end
xplr.fn.custom.render_list = function(ctx)
  local items = {}
  for i, n in ipairs(ctx.app.selection) do
    table.insert(items, xplr.util.paint(n.relative_path, { fg = "Green" }))
  end
  table.insert(items, "version " .. ctx.app.version .. " pid? " .. type(ctx.app.pid) .. " vroot " .. tostring(ctx.app.vroot))
  table.insert(items, "input " .. tostring(ctx.app.input_buffer) .. " layout " .. type(ctx.app.layout) .. " sorters " .. #ctx.app.explorer_config.sorters)
  return { CustomList = { ui = { title = { format = " sel " } }, body = items } }
end
xplr.fn.custom.render_table = function(ctx)
  return {
    CustomTable = {
      ui = { title = { format = " tbl " }, border_type = "Double", border_style = { fg = "Red" } },
      widths = { { Percentage = 30 }, { Percentage = 70 } },
      col_spacing = 2,
      body = { { "a", "b" }, { "c", "d" }, { "pwd", ctx.app.pwd } },
    },
  }
end
