new=r'''    let lscolors = LsColors::from_env();
    init_pipes(&app)?;

    // ---- terminal
    let mouse = app.config.general.enable_mouse;
    let guard = TerminalGuard::enter(mouse)?;
    let backend = CrosstermBackend::new(io::stdout());
    let mut terminal = Terminal::new(backend)?;
    clear_terminal(&mut terminal)?;

    let (tx, rx): (Sender<Task>, Receiver<Task>) = mpsc::channel();
    let stop = Arc::new(AtomicBool::new(false));
    let paused = Arc::new(AtomicBool::new(false));
    let reader_idle = Arc::new(AtomicBool::new(false));
    spawn_key_reader(tx.clone(), stop.clone(), paused.clone(), reader_idle.clone());
    spawn_pipe_reader(tx.clone(), app.pipe.msg_in.clone(), stop.clone(), paused.clone());

    let mut lp = Loop {
        app,
        cli: cli.clone(),
        lua,
        lscolors,
        pending: VecDeque::new(),
        terminal,
        guard,
        fifo: None,
        mouse_enabled: mouse,
        paused,
        reader_idle,
        parents_pending: false,
        need_draw: true,
    };

    let result: Result<Option<String>> = (|| {
        // ---- initial exploration (as a task, so that hooks fire)
        let pwd = lp.app.pwd.clone();
        lp.app.change_directory(&pwd, true)?;
        lp.app
            .msg_out
            .retain(|m| !matches!(m, MsgOut::ExplorePwdAsync));
        lp.app
            .handle_task(Task::new(MsgIn::External(ExternalMsg::ExplorePwd), None))?;
        if let Some(r) = lp.drain()? {
            return Ok(r);
        }

        if let Some(fp) = &runner.focused_path {
            lp.pending.push_back(Task::new(
                MsgIn::External(ExternalMsg::FocusPath(fp.to_string_lossy().to_string())),
                None,
            ));
        }
        for s in &runner.selection {
            lp.pending.push_back(Task::new(
                MsgIn::External(ExternalMsg::SelectPath(s.to_string_lossy().to_string())),
                None,
            ));
        }
        lp.pending.push_back(Task::new(
            MsgIn::External(ExternalMsg::ExploreParentsAsync),
            None,
        ));

        let had_errors = !load_errors.is_empty();
        for e in load_errors {
            lp.app.log_error(e);
        }
        if had_errors && !lp.app.config.general.disable_debug_error_mode {
            lp.pending.push_back(Task::new(
                MsgIn::External(ExternalMsg::SwitchModeBuiltin("debug_error".to_string())),
                None,
            ));
        }
        for m in lp.app.hooks.on_load.clone() {
            lp.pending.push_back(Task::new(MsgIn::External(m), None));
        }
        for raw in &cli.on_load {
            match crate::yaml::from_str::<ExternalMsg>(raw) {
                Ok(m) => lp.pending.push_back(Task::new(MsgIn::External(m), None)),
                Err(e) => bail!("{}", e),
            }
        }
        if let Some(fifo) = lp.app.config.general.start_fifo.clone() {
            lp.pending.push_back(Task::new(
                MsgIn::External(ExternalMsg::StartFifo(fifo)),
                None,
            ));
        }

        loop {
            let task = match lp.pending.pop_front() {
                Some(t) => t,
                None => {
                    if lp.need_draw {
                        lp.draw()?;
                    }
                    match rx.recv() {
                        Ok(t) => t,
                        Err(_) => bail!("event channel closed"),
                    }
                }
            };
            lp.app.handle_task(task)?;
            lp.need_draw = true;
            if let Some(r) = lp.drain()? {
                return Ok(r);
            }
        }
    })();

    stop.store(true, Ordering::Relaxed);
    lp.guard.leave()?;
    let _ = fs::remove_dir_all(&lp.app.session_path);
    result
}

struct Loop {
    app: App,
    cli: Cli,
    lua: Option<Runtime>,
    lscolors: LsColors,
    pending: VecDeque<Task>,
    terminal: Terminal<CrosstermBackend<io::Stdout>>,
    guard: TerminalGuard,
    fifo: Option<Fifo>,
    mouse_enabled: bool,
    paused: Arc<AtomicBool>,
    reader_idle: Arc<AtomicBool>,
    parents_pending: bool,
    need_draw: bool,
}

impl Loop {
    fn draw(&mut self) -> Result<()> {
        if self.parents_pending {
            self.parents_pending = false;
            add_parent_focus(&mut self.app);
        }
        let mut ctx = RenderCtx {
            app: &mut self.app,
            lua: self.lua.as_ref(),
            lscolors: &self.lscolors,
        };
        self.terminal.draw(|f| ui::draw(f, &mut ctx))?;
        self.need_draw = false;
        if let Some(fifo) = self.fifo.as_mut() {
            let focus = self.app.focused_node_str();
            fifo.write(&focus);
        }
        Ok(())
    }

    fn lua_call(&self, func: &str) -> Result<Vec<ExternalMsg>> {
        match self.lua.as_ref() {
            Some(l) => l.call(func, &self.app),
            None => Err(anyhow::anyhow!("lua scripting is not available")),
        }
    }

    fn lua_eval(&self, code: &str, silent: bool) -> Result<Vec<ExternalMsg>> {
        match self.lua.as_ref() {
            Some(l) => l.eval(code, &self.app, silent),
            None => Err(anyhow::anyhow!("lua scripting is not available")),
        }
    }

    fn start_fifo(&mut self, path: &str) {
        match Fifo::start(path) {
            Ok(mut f) => {
                f.write(&self.app.focused_node_str());
                self.fifo = Some(f);
            }
            Err(e) => self
                .app
                .log_error(format!("could not start fifo {:?}: {}", path, e)),
        }
    }

    /// Drain the outgoing message queue. Returns `Some(result)` when the
    /// application should quit.
    fn drain(&mut self) -> Result<Option<Option<String>>> {
        while let Some(out) = self.app.msg_out.pop_front() {
            match out {
                MsgOut::Enqueue(t) => self.pending.push_back(t),
                MsgOut::Refresh => self.need_draw = true,
                MsgOut::ClearScreen => {
                    clear_terminal(&mut self.terminal)?;
                    self.need_draw = true;
                }
                MsgOut::ExplorePwdAsync => explore_now(&mut self.app, false),
                MsgOut::ExploreParentsAsync => {
                    explore_now(&mut self.app, false);
                    self.parents_pending = true;
                }
                MsgOut::Quit => return Ok(Some(None)),
                MsgOut::Terminate => bail!("terminated"),
                MsgOut::PrintPwdAndQuit => {
                    return Ok(Some(Some(format!("{}\n", self.app.pwd))));
                }
                MsgOut::PrintFocusPathAndQuit => {
                    let d = if self.cli.write0 { '\0' } else { '\n' };
                    let out = self
                        .app
                        .focused_node()
                        .map(|n| format!("{}{}", n.absolute_path, d))
                        .unwrap_or_default();
                    return Ok(Some(Some(out)));
                }
                MsgOut::PrintSelectionAndQuit => {
                    let d = if self.cli.write0 { '\0' } else { '\n' };
                    return Ok(Some(Some(self.app.selection_str(d))));
                }
                MsgOut::PrintResultAndQuit => {
                    let d = if self.cli.write0 { '\0' } else { '\n' };
                    return Ok(Some(Some(self.app.result_str(d))));
                }
                MsgOut::PrintAppStateAndQuit => {
                    return Ok(Some(Some(self.app.to_yaml())));
                }
                MsgOut::Debug(path) => {
                    if let Err(e) = fs::write(&path, self.app.to_yaml()) {
                        self.app
                            .log_error(format!("could not write {:?}: {}", path, e));
                    }
                }
                MsgOut::Call(cmd) => self.run_command(&cmd, '\n', false)?,
                MsgOut::Call0(cmd) => self.run_command(&cmd, '\0', false)?,
                MsgOut::CallSilently(cmd) => self.run_command(&cmd, '\n', true)?,
                MsgOut::CallSilently0(cmd) => self.run_command(&cmd, '\0', true)?,
                MsgOut::CallLua(func) => {
                    pause_input(&self.paused, &self.reader_idle);
                    self.guard.suspend()?;
                    let res = self.lua_call(&func);
                    self.guard.resume()?;
                    clear_terminal(&mut self.terminal)?;
                    self.paused.store(false, Ordering::SeqCst);
                    handle_lua_result(&mut self.app, res, &mut self.pending);
                }
                MsgOut::CallLuaSilently(func) => {
                    let res = self.lua_call(&func);
                    handle_lua_result(&mut self.app, res, &mut self.pending);
                }
                MsgOut::LuaEval(code) => {
                    pause_input(&self.paused, &self.reader_idle);
                    self.guard.suspend()?;
                    let res = self.lua_eval(&code, false);
                    self.guard.resume()?;
                    clear_terminal(&mut self.terminal)?;
                    self.paused.store(false, Ordering::SeqCst);
                    handle_lua_result(&mut self.app, res, &mut self.pending);
                }
                MsgOut::LuaEvalSilently(code) => {
                    let res = self.lua_eval(&code, true);
                    handle_lua_result(&mut self.app, res, &mut self.pending);
                }
                MsgOut::EnableMouse => {
                    if !self.mouse_enabled {
                        execute!(io::stdout(), EnableMouseCapture)?;
                        self.mouse_enabled = true;
                    }
                }
                MsgOut::DisableMouse => {
                    if self.mouse_enabled {
                        execute!(io::stdout(), DisableMouseCapture)?;
                        self.mouse_enabled = false;
                    }
                }
                MsgOut::ToggleMouse => {
                    if self.mouse_enabled {
                        execute!(io::stdout(), DisableMouseCapture)?;
                        self.mouse_enabled = false;
                    } else {
                        execute!(io::stdout(), EnableMouseCapture)?;
                        self.mouse_enabled = true;
                    }
                }
                MsgOut::StartFifo(path) => self.start_fifo(&path),
                MsgOut::StopFifo => self.fifo = None,
                MsgOut::ToggleFifo(path) => {
                    if self.fifo.is_some() {
                        self.fifo = None;
                    } else {
                        self.start_fifo(&path);
                    }
                }
            }
        }
        Ok(None)
    }

    fn run_command(&mut self, cmd: &Command, delimiter: char, silent: bool) -> Result<()> {
        if silent {
            self.paused.store(true, Ordering::SeqCst);
        } else {
            pause_input(&self.paused, &self.reader_idle);
        }
        call(&mut self.app, cmd, delimiter, silent, &self.guard, &mut self.terminal)?;
        let tasks = drain_msg_in(&self.app);
        self.pending.extend(tasks);
        self.paused.store(false, Ordering::SeqCst);
        Ok(())
    }
}

