/// Stop the input reader thread and wait until it is idle so that an
/// external command can own the terminal input.
fn pause_input(paused: &Arc<AtomicBool>, idle: &Arc<AtomicBool>) {
    paused.store(true, Ordering::SeqCst);
    for _ in 0..50 {
        if idle.load(Ordering::SeqCst) {
            break;
        }
        std::thread::sleep(Duration::from_millis(5));
    }
}

/// Clear the screen and force a full redraw without querying the cursor.
fn clear_terminal(terminal: &mut Terminal<CrosstermBackend<io::Stdout>>) -> Result<()> {
    execute!(
        io::stdout(),
        crossterm::terminal::Clear(crossterm::terminal::ClearType::All)
    )?;
    terminal.swap_buffers();
    terminal.swap_buffers();
    Ok(())
}
