    pub fn with_array_size(n: usize) -> Self {
        let t = TableRef::new();
        t.0.borrow_mut().arr = vec![Value::Nil; n];
        t
    }

    pub fn get(&self, key: &Value) -> Value {
        let t = self.0.borrow();
        if let Value::Num(n) = key {
            if n.fract() == 0.0 && *n >= 1.0 && (*n as usize) <= t.arr.len() {
                return t.arr[*n as usize - 1].clone();
            }
        }
        match Key::from_value(key) {
            Some(k) => t.hash.get(&k).cloned().unwrap_or(Value::Nil),
            None => Value::Nil,
        }
    }

