    /// Create a table whose array part is pre-sized (like a constructor
    /// with `n` positional items).
    pub fn with_array_size(n: usize) -> Self {
        let t = TableRef::new();
        t.0.borrow_mut().arr = vec![Value::Nil; n];
        t
    }

    pub fn get(&self, key: &Value) -> Value {
        let t = self.0.borrow();
        if let Value::Num(n) = key {
            if n.fract() == 0.0 && *n >= 1.0 && (*n as usize) <= t.arr.len() {
                return t.arr[*n as usize - 1].clone();
            }
        }
        match Key::from_value(key) {
            Some(k) => t.hash.get(&k).cloned().unwrap_or(Value::Nil),
            None => Value::Nil,
        }
    }

    pub fn get_str(&self, key: &str) -> Value {
        self.get(&Value::str(key))
    }

    /// Set a slot of the array part directly (used by constructors).
    pub fn set_array_slot(&self, idx: usize, val: Value) {
        let mut t = self.0.borrow_mut();
        if idx >= 1 && idx <= t.arr.len() {
            t.arr[idx - 1] = val;
        }
    }

    pub fn set(&self, key: Value, val: Value) -> Result<(), LuaError> {
        let mut t = self.0.borrow_mut();
        if let Value::Num(n) = &key {
            if n.is_nan() {
                return Err(LuaError::msg("table index is NaN"));
            }
            if n.fract() == 0.0 && *n >= 1.0 && *n < 1e15 {
                let idx = *n as usize;
                if idx <= t.arr.len() {
                    t.arr[idx - 1] = val;
                    return Ok(());
                }
                if matches!(val, Value::Nil) {
                    t.hash.shift_remove(&Key::Int(idx as i64));
                    return Ok(());
                }
                if idx == t.arr.len() + 1 {
                    t.arr.push(val);
                    // migrate following keys from hash
                    let mut next = idx + 1;
                    while let Some(v) = t.hash.shift_remove(&Key::Int(next as i64)) {
                        t.arr.push(v);
                        next += 1;
                    }
                    return Ok(());
                }
                // Decide whether the array part should grow to cover `idx`
                // (more than half of the slots 1..n must be in use).
                let mut n_size = 1usize;
                while n_size < idx {
                    n_size *= 2;
                }
                let in_arr = t.arr.iter().filter(|v| !matches!(v, Value::Nil)).count();
                let in_hash = t
                    .hash
                    .keys()
                    .filter(|k| matches!(k, Key::Int(i) if *i > t.arr.len() as i64 && *i <= n_size as i64))
                    .count();
                if in_arr + in_hash + 1 > n_size / 2 {
                    let old_len = t.arr.len();
                    t.arr.resize(n_size, Value::Nil);
                    for i in (old_len + 1)..=n_size {
                        if let Some(v) = t.hash.shift_remove(&Key::Int(i as i64)) {
                            t.arr[i - 1] = v;
                        }
                    }
                    t.arr[idx - 1] = val;
                    return Ok(());
                }
            }
        }
        let k = match Key::from_value(&key) {
            Some(k) => k,
            None => return Err(LuaError::msg("table index is nil")),
        };
        if matches!(val, Value::Nil) {
            t.hash.shift_remove(&k);
        } else {
            t.hash.insert(k, val);
        }
        Ok(())
    }

    pub fn set_str(&self, key: &str, val: Value) {
        let _ = self.set(Value::str(key), val);
    }

    /// The length operator: a border of the table, computed like Lua does.
    pub fn len(&self) -> usize {
        let t = self.0.borrow();
        let j = t.arr.len();
        if j > 0 && matches!(t.arr[j - 1], Value::Nil) {
            // binary search for a border inside the array part
            let (mut i, mut j) = (0usize, j);
            while j - i > 1 {
                let m = (i + j) / 2;
                if matches!(t.arr[m - 1], Value::Nil) {
                    j = m;
                } else {
                    i = m;
                }
            }
            return i;
        }
        if !t.hash.contains_key(&Key::Int(j as i64 + 1)) {
            return j;
        }
        // unbound search in the hash part
        let mut i = j;
        let mut j = j + 1;
        while t.hash.contains_key(&Key::Int(j as i64)) {
            i = j;
            if j > usize::MAX / 2 {
                // linear fallback
                let mut k = 1;
                while t.hash.contains_key(&Key::Int(k)) {
                    k += 1;
                }
                return (k - 1) as usize;
            }
            j *= 2;
        }
        while j - i > 1 {
            let m = (i + j) / 2;
            if t.hash.contains_key(&Key::Int(m as i64)) {
                i = m;
            } else {
                j = m;
            }
        }
        i
    }

